,\n    \"summary\": {\n      \"en\": \"Labelled step indicator (numbered/checked circles + connecting lines).\",\n      \"pt\": \"Indicador de etapas rotuladas (círculos numerados/check + linhas).\"\n    },\n    \"description\": {\n      \"en\": \"Horizontal or vertical multi-step wizard/form. Completed steps show a check and can be tapped to go back; transitions run through AppMotion.\",\n      \"pt\": \"Wizard/formulário multi-etapa horizontal ou vertical. Passos concluídos mostram check e podem ser tocados para voltar; transições via AppMotion.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Forms and wizards with a title per step.\"\n      ],\n      \"pt\": [\n        \"Formulários/wizards com títulos por etapa.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Only the position among pages, with no labels → AppDotsIndicator.\"\n      ],\n      \"pt\": [\n        \"Só posição entre páginas, sem rótulos → AppDotsIndicator.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"currentStep\",\n        \"type\": \"int\",\n        \"required\": true\n      },\n      {\n        \"name\": \"steps\",\n        \"type\": \"List<AppStepData>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"axis\",\n        \"type\": \"Axis\",\n        \"required\": false,\n        \"default\": \"Axis.horizontal\"\n      },\n      {\n        \"name\": \"showLabels\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"onStepTapped\",\n        \"type\": \"ValueChanged<int>?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"activeColor\",\n        \"type\": \"Color?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"completedColor\",\n        \"type\": \"Color?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"upcomingColor\",\n        \"type\": \"Color?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"completed\",\n      \"active\",\n      \"upcoming\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Wizard\",\n          \"pt\": \"Wizard\"\n        },\n        \"code\": \"AppStepper(currentStep: 1, steps: [AppStepData(title: \\\"Dados\\\"), ...])\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Provide onStepTapped so completed steps can be revisited.\"\n      ],\n      \"pt\": [\n        \"Forneça onStepTapped para permitir voltar a etapas concluídas.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not let currentStep fall outside [0, steps.length).\"\n      ],\n      \"pt\": [\n        \"Não deixe currentStep fora de [0, steps.length).\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Every step is labelled (number + title + state); completed ones become buttons (go back) via AppSemantics.\",\n      \"pt\": \"Cada passo é rotulado (número + título + estado); concluídos viram botões (voltar) via AppSemantics.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_dots_indicator\",\n      \"app_icon\",\n      \"app_text\"\n    ]\n  },\n  {\n    \"id\": \"app_circular_loading\",\n    \"name\": \"AppCircularLoading\",\n    \"category\": \"atom\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Circular progress ring (indeterminate or determinate).\",\n      \"pt\": \"Anel de progresso circular (indeterminado ou determinado).\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Indeterminate loading in buttons, overlays and lists.\",\n        \"Determinate progress (a static arc) by passing value (0..1).\"\n      ],\n      \"pt\": [\n        \"Carregamento indeterminado em botões, overlays, listas.\",\n        \"Progresso determinado (arco estático) informando value (0..1).\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"value\",\n        \"type\": \"double?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"null = indeterminate (spins). 0..1 draws a static arc — no animation, so it is the mode that survives reduce-motion.\",\n          \"pt\": \"null = indeterminado (gira). 0..1 desenha um arco estático — sem animação, então é o modo que sobrevive a reduce-motion.\"\n        }\n      },\n      {\n        \"name\": \"size\",\n        \"type\": \"double\",\n        \"required\": false,\n        \"default\": \"AppSizes.s16\",\n        \"description\": {\n          \"en\": \"Ring diameter.\",\n          \"pt\": \"Diâmetro do anel.\"\n        }\n      },\n      {\n        \"name\": \"stroke\",\n        \"type\": \"double\",\n        \"required\": false,\n        \"default\": \"AppStrokes.xl\",\n        \"description\": {\n          \"en\": \"Stroke thickness; the strokeCap follows the radius mode.\",\n          \"pt\": \"Espessura do traço; o strokeCap segue o modo de raio.\"\n        }\n      },\n      {\n        \"name\": \"color\",\n        \"type\": \"Color?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Arc color. Defaults to focusRing (the base primary disappears into the near-black of some brands).\",\n          \"pt\": \"Cor do arco. Default focusRing (o primary base some no quase-preto de algumas marcas).\"\n        }\n      },\n      {\n        \"name\": \"backgroundColor\",\n        \"type\": \"Color?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Track behind the arc. Defaults to surfaceContainer.\",\n          \"pt\": \"Trilho atrás do arco. Default surfaceContainer.\"\n        }\n      }\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Spinner\",\n          \"pt\": \"Spinner\"\n        },\n        \"code\": \"AppCircularLoading(size: AppSizes.s32)\"\n      },\n      {\n        \"title\": {\n          \"en\": \"Determinate\",\n          \"pt\": \"Determinado\"\n        },\n        \"code\": \"AppCircularLoading(value: 0.7)\"\n      }\n    ],\n    \"a11y\": {\n      \"en\": \"A visual indicator; wrap it in AppSemantics.liveRegion + label wherever the loading state has to be announced.\",\n      \"pt\": \"Indicador visual; envolva com AppSemantics.liveRegion + label onde o estado de carregamento precise ser anunciado.\"\n    },\n    \"crossPlatform\": false,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_linear_loading\",\n      \"app_shimmer_loading\"\n    ]\n  },\n  {\n    \"id\": \"app_linear_loading\",\n    \"name\": \"AppLinearLoading\",\n    \"category\": \"atom\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Linear progress bar (indeterminate or determinate).\",\n      \"pt\": \"Barra de progresso linear (indeterminada ou determinada).\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Indeterminate progress at the top of an area or page.\",\n        \"Determinate progress by passing value (0..1).\"\n      ],\n      \"pt\": [\n        \"Progresso indeterminado no topo de uma área/página.\",\n        \"Progresso determinado informando value (0..1).\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"value\",\n        \"type\": \"double?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"null = indeterminate (a sliding bar). 0..1 fills from the left, static.\",\n          \"pt\": \"null = indeterminado (barra deslizante). 0..1 preenche da esquerda, estático.\"\n        }\n      },\n      {\n        \"name\": \"height\",\n        \"type\": \"double\",\n        \"required\": false,\n        \"default\": \"AppSizes.s4\",\n        \"description\": {\n          \"en\": \"Bar thickness; the end caps follow the global radius.\",\n          \"pt\": \"Espessura da barra; as pontas seguem o raio global.\"\n        }\n      },\n      {\n        \"name\": \"color\",\n        \"type\": \"Color?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Fill color.\",\n          \"pt\": \"Cor do preenchimento.\"\n        }\n      },\n      {\n        \"name\": \"backgroundColor\",\n        \"type\": \"Color?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Track. Defaults to surfaceContainer.\",\n          \"pt\": \"Trilho. Default surfaceContainer.\"\n        }\n      }\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Indeterminate\",\n          \"pt\": \"Indeterminada\"\n        },\n        \"code\": \"AppLinearLoading()\"\n      },\n      {\n        \"title\": {\n          \"en\": \"Determinate\",\n          \"pt\": \"Determinada\"\n        },\n        \"code\": \"AppLinearLoading(value: 0.7)\"\n      }\n    ],\n    \"a11y\": {\n      \"en\": \"A visual indicator; under reduce-motion it stays static.\",\n      \"pt\": \"Indicador visual; sob reduce-motion fica estático.\"\n    },\n    \"crossPlatform\": false,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_circular_loading\"\n    ]\n  },\n  {\n    \"id\": \"app_border_progress\",\n    \"name\": \"AppBorderProgress\",\n    \"category\": \"atom\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Animated progress border around a child.\",\n      \"pt\": \"Borda de progresso animada ao redor de um filho.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Progress (driven by `progress`) or a timer (automatic, through `duration`).\"\n      ],\n      \"pt\": [\n        \"Progresso (controlado por `progress`) ou timer (auto por `duration`).\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"child\",\n        \"type\": \"Widget\",\n        \"required\": true,\n        \"description\": {\n          \"en\": \"What the border encircles.\",\n          \"pt\": \"O que a borda circunda.\"\n        }\n      },\n      {\n        \"name\": \"progress\",\n        \"type\": \"double?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Controlled mode (0..1). Mutually exclusive with duration.\",\n          \"pt\": \"Modo controlado (0..1). Exclusivo com duration.\"\n        }\n      },\n      {\n        \"name\": \"duration\",\n        \"type\": \"Duration?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Timer mode: the border closes on its own over this span. Under reduce-motion it starts at the final state.\",\n          \"pt\": \"Modo timer: a borda fecha sozinha nesse tempo. Sob reduce-motion nasce no estado final.\"\n        }\n      },\n      {\n        \"name\": \"borderRadius\",\n        \"type\": \"BorderRadius\",\n        \"required\": false,\n        \"default\": \"BorderRadius.zero\",\n        \"description\": {\n          \"en\": \"Stroke corners, concentric with the child.\",\n          \"pt\": \"Cantos do traço, concêntricos ao filho.\"\n        }\n      },\n      {\n        \"name\": \"strokeWidth\",\n        \"type\": \"double\",\n        \"required\": false,\n        \"default\": \"AppStrokes.l\"\n      },\n      {\n        \"name\": \"color\",\n        \"type\": \"Color?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"backgroundColor\",\n        \"type\": \"Color?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Track.\",\n          \"pt\": \"Trilho.\"\n        }\n      },\n      {\n        \"name\": \"repeat\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\",\n        \"description\": {\n          \"en\": \"Timer mode only: restarts on completion.\",\n          \"pt\": \"Só no modo timer: reinicia ao completar.\"\n        }\n      },\n      {\n        \"name\": \"onComplete\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      }\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Controlled\",\n          \"pt\": \"Controlado\"\n        },\n        \"code\": \"AppBorderProgress(progress: 0.5, child: child)\"\n      }\n    ],\n    \"a11y\": {\n      \"en\": \"A visual indicator; auto mode sits at the final state under reduce-motion.\",\n      \"pt\": \"Indicador visual; auto-mode fica no estado final sob reduce-motion.\"\n    },\n    \"crossPlatform\": false,\n    \"themeAware\": true,\n    \"reducesMotion\": true\n  },\n  {\n    \"id\": \"app_overlay_loading\",\n    \"name\": \"AppOverlayLoading\",\n    \"category\": \"atom\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Loading overlay on top of a child (barrier + indicator).\",\n      \"pt\": \"Overlay de carregamento sobre um filho (barrier + indicador).\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Blocking an area while it loads, keeping the content visible.\"\n      ],\n      \"pt\": [\n        \"Bloquear uma área enquanto carrega, mantendo o conteúdo.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"isLoading\",\n        \"type\": \"bool\",\n        \"required\": true,\n        \"description\": {\n          \"en\": \"Turns the barrier on. False mounts nothing on top.\",\n          \"pt\": \"Liga o barrier. False não monta nada por cima.\"\n        }\n      },\n      {\n        \"name\": \"overlay\",\n        \"type\": \"Widget\",\n        \"required\": true,\n        \"description\": {\n          \"en\": \"The indicator shown over the content.\",\n          \"pt\": \"O indicador mostrado sobre o conteúdo.\"\n        }\n      },\n      {\n        \"name\": \"child\",\n        \"type\": \"Widget\",\n        \"required\": true,\n        \"description\": {\n          \"en\": \"Content that stays visible underneath.\",\n          \"pt\": \"Conteúdo que continua visível por baixo.\"\n        }\n      }\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Default\",\n          \"pt\": \"Padrão\"\n        },\n        \"code\": \"AppOverlayLoading(isLoading: true, overlay: AppCircularLoading(), child: form)\"\n      }\n    ],\n    \"a11y\": {\n      \"en\": \"Blocks interaction visually; pair it with \\\"loading\\\" semantics.\",\n      \"pt\": \"Bloqueia interação visual; combine com semântica de \\\"carregando\\\".\"\n    },\n    \"crossPlatform\": false,\n    \"themeAware\": true,\n    \"reducesMotion\": true\n  },\n  {\n    \"id\": \"app_shimmer_loading\",\n    \"name\": \"AppShimmerLoading\",\n    \"category\": \"atom\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Skeleton placeholder with an animated sheen.\",\n      \"pt\": \"Placeholder skeleton com brilho animado.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"A content skeleton while the data loads.\"\n      ],\n      \"pt\": [\n        \"Skeleton de conteúdo enquanto os dados carregam.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"height\",\n        \"type\": \"double\",\n        \"required\": true,\n        \"description\": {\n          \"en\": \"Height of the skeleton block.\",\n          \"pt\": \"Altura do bloco de skeleton.\"\n        }\n      },\n      {\n        \"name\": \"width\",\n        \"type\": \"double\",\n        \"required\": false,\n        \"default\": \"double.infinity\",\n        \"description\": {\n          \"en\": \"Width; infinity fills the parent.\",\n          \"pt\": \"Largura; infinity preenche o pai.\"\n        }\n      },\n      {\n        \"name\": \"borderRadius\",\n        \"type\": \"BorderRadius?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Corners. Default: the theme's global radius.\",\n          \"pt\": \"Cantos. Default: o raio global do tema.\"\n        }\n      },\n      {\n        \"name\": \"color\",\n        \"type\": \"Color?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Base of the block.\",\n          \"pt\": \"Base do bloco.\"\n        }\n      },\n      {\n        \"name\": \"highlightColor\",\n        \"type\": \"Color?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Color of the sheen that sweeps across.\",\n          \"pt\": \"Cor do brilho que passa.\"\n        }\n      },\n      {\n        \"name\": \"margin\",\n        \"type\": \"EdgeInsets?\",\n        \"required\": false\n      }\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Default\",\n          \"pt\": \"Padrão\"\n        },\n        \"code\": \"AppShimmerLoading(height: AppSizes.s16)\"\n      }\n    ],\n    \"a11y\": {\n      \"en\": \"A decorative placeholder; under reduce-motion it shows the static box.\",\n      \"pt\": \"Placeholder decorativo; sob reduce-motion mostra o box estático.\"\n    },\n    \"crossPlatform\": false,\n    \"themeAware\": true,\n    \"reducesMotion\": true\n  },\n  {\n    \"id\": \"app_divider\",\n    \"name\": \"AppDivider\",\n    \"category\": \"atom\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Thin rule that separates content, adapted to the theme.\",\n      \"pt\": \"Régua fina que separa conteúdo, adaptada ao tema.\"\n    },\n    \"description\": {\n      \"en\": \"Horizontal or vertical hairline whose color comes from the theme (`outline` by default). Fills the cross axis of a bounded parent and is decorative (outside the semantics tree).\",\n      \"pt\": \"Linha hairline horizontal ou vertical com cor vinda do tema (`outline` por padrão). Preenche o eixo cruzado de um pai de dimensão limitada e é decorativa (fora da semântica).\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Separating sections of a list or column (horizontal).\",\n        \"Separating items in a bar or row (vertical, AppDivider.vertical).\"\n      ],\n      \"pt\": [\n        \"Separar seções de uma lista/coluna (horizontal).\",\n        \"Separar itens numa barra/linha (vertical, AppDivider.vertical).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"As a container's border → use BoxDecoration.border.\",\n        \"For spacing with no line → use SizedBox/AppSpacings.\"\n      ],\n      \"pt\": [\n        \"Como borda de um container → use BoxDecoration.border.\",\n        \"Para espaçamento sem linha → use SizedBox/AppSpacings.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"thickness\",\n        \"type\": \"double\",\n        \"required\": false,\n        \"default\": \"AppStrokes.s\",\n        \"description\": {\n          \"en\": \"Line thickness (an AppStrokes token).\",\n          \"pt\": \"Espessura da linha (token de AppStrokes).\"\n        }\n      },\n      {\n        \"name\": \"indent\",\n        \"type\": \"double\",\n        \"required\": false,\n        \"default\": \"0\",\n        \"description\": {\n          \"en\": \"Inset before the line (left/top).\",\n          \"pt\": \"Recuo antes da linha (esquerda/topo).\"\n        }\n      },\n      {\n        \"name\": \"endIndent\",\n        \"type\": \"double\",\n        \"required\": false,\n        \"default\": \"0\",\n        \"description\": {\n          \"en\": \"Inset after the line (right/bottom).\",\n          \"pt\": \"Recuo depois da linha (direita/base).\"\n        }\n      },\n      {\n        \"name\": \"color\",\n        \"type\": \"Color?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Overrides the color (default: theme.colorTheme.outline).\",\n          \"pt\": \"Sobrescreve a cor (default: theme.colorTheme.outline).\"\n        }\n      },\n      {\n        \"name\": \"radius\",\n        \"type\": \"double?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"End-cap radius (default: the global radius in round mode, clamped to the thickness).\",\n          \"pt\": \"Raio das pontas (default: radius global no modo redondo, clampado à espessura).\"\n        }\n      }\n    ],\n    \"variants\": [\n      \"horizontal\",\n      \"vertical\"\n    ],\n    \"states\": [\n      \"default\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Between rows\",\n          \"pt\": \"Entre linhas\"\n        },\n        \"code\": \"AppDivider(indent: 8, endIndent: 8)\"\n      },\n      {\n        \"title\": {\n          \"en\": \"Vertical inside a bar\",\n          \"pt\": \"Vertical numa barra\"\n        },\n        \"code\": \"SizedBox(height: 16, child: AppDivider.vertical())\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Let the color come from the theme (outline).\"\n      ],\n      \"pt\": [\n        \"Deixe a cor vir do tema (outline).\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it as a card border; do not hardcode a color.\"\n      ],\n      \"pt\": [\n        \"Não use como borda de card; não embuta cor fixa.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Decorative: excluded from the semantics tree (AppSemantics.decorative), never read by screen readers.\",\n      \"pt\": \"Decorativo: excluído da árvore de semântica (AppSemantics.decorative), não é lido por leitores de tela.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_text\"\n    ]\n  },\n  {\n    \"id\": \"app_badge\",\n    \"name\": \"AppBadge\",\n    \"category\": \"atom\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Compact status pill, tinted by a semantic color role.\",\n      \"pt\": \"Pill compacta de status, tingida por papel de cor semântico.\"\n    },\n    \"description\": {\n      \"en\": \"Shows short text in a semantic role's full color over a background of the same color at 10%. Sized by a named step (s/m/l/xl); adapts to light/dark and to the brand. Read-only by default; with onTap it becomes an interactive pill (hover/press/focus + ring + button role).\",\n      \"pt\": \"Mostra um texto curto com a cor cheia de um papel semântico sobre um fundo da mesma cor a 10%. Dimensionada por um passo nomeado (s/m/l/xl); adapta a claro/escuro e marca. Somente-leitura por padrão; com onTap vira uma pill interativa (hover/press/foco + anel + role de botão).\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"State or category label: alert status, severity, a short tag.\",\n        \"With onTap: an actionable filter/chip (e.g. toggling a list filter).\"\n      ],\n      \"pt\": [\n        \"Rótulo de estado/categoria: status de alerta, severidade, tag curta.\",\n        \"Com onTap: filtro/chip acionável (ex.: alternar um filtro de lista).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Primary action/CTA → use a button (the badge is a label pill).\"\n      ],\n      \"pt\": [\n        \"Ação primária/CTA → use um botão (o badge é uma pill de rótulo).\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"label\",\n        \"type\": \"String\",\n        \"required\": true,\n        \"description\": {\n          \"en\": \"Short text shown in the pill.\",\n          \"pt\": \"Texto curto exibido na pill.\"\n        }\n      },\n      {\n        \"name\": \"color\",\n        \"type\": \"AppBadgeColor\",\n        \"required\": false,\n        \"default\": \"AppBadgeColor.neutral\",\n        \"description\": {\n          \"en\": \"Semantic color role.\",\n          \"pt\": \"Papel de cor semântico.\"\n        },\n        \"enumValues\": [\n          \"neutral\",\n          \"primary\",\n          \"info\",\n          \"success\",\n          \"warning\",\n          \"danger\"\n        ]\n      },\n      {\n        \"name\": \"size\",\n        \"type\": \"AppBadgeSize\",\n        \"required\": false,\n        \"default\": \"AppBadgeSize.m\",\n        \"description\": {\n          \"en\": \"Size step: drives the padding and the text role.\",\n          \"pt\": \"Passo de tamanho: dirige o padding e o papel de texto.\"\n        },\n        \"enumValues\": [\n          \"s\",\n          \"m\",\n          \"l\",\n          \"xl\"\n        ]\n      },\n      {\n        \"name\": \"onTap\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Makes the pill interactive (hover/press/focus + button role). Null = read-only.\",\n          \"pt\": \"Torna a pill interativa (hover/press/foco + role de botão). Nulo = somente-leitura.\"\n        }\n      },\n      {\n        \"name\": \"effect\",\n        \"type\": \"AppBadgeEffect\",\n        \"required\": false,\n        \"default\": \"AppBadgeEffect.scale\",\n        \"description\": {\n          \"en\": \"Hover/press micro-animation (only when onTap != null).\",\n          \"pt\": \"Micro-animação de hover/press (só quando onTap != null).\"\n        },\n        \"enumValues\": [\n          \"none\",\n          \"scale\",\n          \"lift\"\n        ]\n      }\n    ],\n    \"variants\": [\n      \"neutral\",\n      \"primary\",\n      \"info\",\n      \"success\",\n      \"warning\",\n      \"danger\"\n    ],\n    \"states\": [\n      \"default\",\n      \"hovered\",\n      \"pressed\",\n      \"focused\",\n      \"dragged\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Alert status\",\n          \"pt\": \"Status de alerta\"\n        },\n        \"code\": \"AppBadge('Pendente', color: AppBadgeColor.warning)\"\n      },\n      {\n        \"title\": {\n          \"en\": \"Neutral\",\n          \"pt\": \"Neutro\"\n        },\n        \"code\": \"AppBadge('Resolvido')\"\n      },\n      {\n        \"title\": {\n          \"en\": \"Interactive (filter)\",\n          \"pt\": \"Interativa (filtro)\"\n        },\n        \"code\": \"AppBadge('Ativos', color: AppBadgeColor.info, onTap: _toggle)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Pick the semantic role by meaning.\",\n        \"Keep the text short (1–2 words).\",\n        \"Use onTap only when the pill stands for an action or a filter.\"\n      ],\n      \"pt\": [\n        \"Escolha o papel semântico pelo significado.\",\n        \"Mantenha o texto curto (1–2 palavras).\",\n        \"Use onTap só quando a pill representa uma ação/filtro.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it as a primary CTA; do not hardcode a color (use AppBadgeColor).\"\n      ],\n      \"pt\": [\n        \"Não use como CTA primário; não embuta cor fixa (use AppBadgeColor).\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Read-only: exposes label as a single labelled node (AppSemantics.label), excluding the inner semantics. With onTap: becomes a button role (AppSemantics.button), keyboard-activatable (Enter/Space) with a focus ring. Do not rely on color alone: the label carries the state.\",\n      \"pt\": \"Somente-leitura: expõe label como nó rotulado único (AppSemantics.label), excluindo a semântica interna. Com onTap: vira role de botão (AppSemantics.button), ativável por teclado (Enter/Espaço) com anel de foco. Não dependa só da cor: o label carrega o estado.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_text\",\n      \"app_avatar\"\n    ]\n  },\n  {\n    \"id\": \"app_tooltip\",\n    \"name\": \"AppTooltip\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Tooltip (hint balloon) shown on hover, through the Overlay.\",\n      \"pt\": \"Tooltip (balão de dica) exibido ao passar o mouse, via Overlay.\"\n    },\n    \"description\": {\n      \"en\": \"No Material. Shows a balloon carrying [message] on hover over the [child]; it renders through the Overlay so a parent container cannot clip it.\",\n      \"pt\": \"Sem Material. Mostra um balão com [message] no hover sobre o [child]; renderiza via Overlay para não ser cortado por containers pai.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"A short hint on icons or actions with no visible label (desktop/web).\"\n      ],\n      \"pt\": [\n        \"Dica curta em ícones/ações sem rótulo visível (desktop/web).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Essential content (hover does not exist on touch).\"\n      ],\n      \"pt\": [\n        \"Conteúdo essencial (hover não existe em toque).\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"child\",\n        \"type\": \"Widget\",\n        \"required\": true\n      },\n      {\n        \"name\": \"message\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"enabled\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"position\",\n        \"type\": \"AppTooltipPosition\",\n        \"required\": false,\n        \"default\": \"top\",\n        \"enumValues\": [\n          \"top\",\n          \"bottom\",\n          \"left\",\n          \"right\"\n        ]\n      },\n      {\n        \"name\": \"size\",\n        \"type\": \"AppTooltipSize\",\n        \"required\": false,\n        \"default\": \"medium\",\n        \"enumValues\": [\n          \"small\",\n          \"medium\",\n          \"large\"\n        ]\n      },\n      {\n        \"name\": \"maxWidth\",\n        \"type\": \"double?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"textStyle\",\n        \"type\": \"TextStyle?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"hidden\",\n      \"visible\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"On an icon\",\n          \"pt\": \"Em um ícone\"\n        },\n        \"code\": \"AppTooltip(message: \\\"Mês anterior\\\", child: AppIcon(AppIconToken.chevronLeft))\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use short text; for navigation, do not rely on the tooltip alone.\"\n      ],\n      \"pt\": [\n        \"Use texto curto; para navegação, não dependa só do tooltip.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not put essential information only in the tooltip (touch has no hover).\"\n      ],\n      \"pt\": [\n        \"Não coloque informação essencial só no tooltip (toque não tem hover).\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Affects the pointer only (hover); the [child] must carry its own semantics (e.g. an AppIcon with a semanticLabel).\",\n      \"pt\": \"Afeta apenas ponteiro (hover); o [child] deve ter semântica própria (ex.: AppIcon com semanticLabel).\"\n    },\n    \"crossPlatform\": false,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_icon\"\n    ]\n  },\n  {\n    \"id\": \"app_interaction\",\n    \"name\": \"AppInteraction\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Interaction wrapper (InkWell-like) that makes any widget clickable.\",\n      \"pt\": \"Wrapper de interação (tipo InkWell) para tornar qualquer widget clicável.\"\n    },\n    \"description\": {\n      \"en\": \"Wraps any child with gestures (tap/double-tap/long-press), states (hover/focus/press/disabled + keyboard), a background highlight, a preset micro-animation, a loading state and an optional tooltip — all driven by tokens and by reduce-motion. Replaces the old AppTextButton/AppIconButton.\",\n      \"pt\": \"Envolve qualquer child com gestos (tap/double-tap/long-press), estados (hover/foco/press/disabled + teclado), realce de fundo, uma micro-animação pré-setada, loading e tooltip opcional — tudo dirigido por tokens e reduce-motion. Substitui os antigos AppTextButton/AppIconButton.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Making an icon, a piece of text or a card clickable with standard hover/press/tooltip.\",\n        \"Replacing \\\"clickable text\\\"/\\\"clickable icon\\\" (the former AppTextButton/AppIconButton).\"\n      ],\n      \"pt\": [\n        \"Tornar clicável um ícone, texto ou card com hover/press/tooltip padrão.\",\n        \"Substituir \\\"texto clicável\\\"/\\\"ícone clicável\\\" (ex-AppTextButton/AppIconButton).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A primary action with a background and a label → use AppButton.\"\n      ],\n      \"pt\": [\n        \"Ação primária com fundo/rótulo → use AppButton.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"child\",\n        \"type\": \"Widget\",\n        \"required\": true,\n        \"description\": {\n          \"en\": \"Content made interactive.\",\n          \"pt\": \"Conteúdo tornado interativo.\"\n        }\n      },\n      {\n        \"name\": \"onTap\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onDoubleTap\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onLongPress\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"tooltip\",\n        \"type\": \"String?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Tooltip text on hover/focus (null = none).\",\n          \"pt\": \"Texto do tooltip no hover/foco (null = sem).\"\n        }\n      },\n      {\n        \"name\": \"motion\",\n        \"type\": \"AppMotionPreset\",\n        \"required\": false,\n        \"default\": \"AppMotionPreset.scale\",\n        \"description\": {\n          \"en\": \"Hover/press micro-animation.\",\n          \"pt\": \"Micro-animação de hover/press.\"\n        },\n        \"enumValues\": [\n          \"none\",\n          \"scale\",\n          \"lift\",\n          \"pop\",\n          \"rotate\"\n        ]\n      },\n      {\n        \"name\": \"highlight\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\",\n        \"description\": {\n          \"en\": \"Translucent background highlight on hover/press.\",\n          \"pt\": \"Realce de fundo translúcido no hover/press.\"\n        }\n      },\n      {\n        \"name\": \"radius\",\n        \"type\": \"BorderRadius?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Radius of the highlight and focus ring (default: the global radius, round mode).\",\n          \"pt\": \"Raio do realce/anel de foco (default: radius global, modo redondo).\"\n        }\n      },\n      {\n        \"name\": \"padding\",\n        \"type\": \"EdgeInsetsGeometry\",\n        \"required\": false,\n        \"default\": \"EdgeInsets.zero\",\n        \"description\": {\n          \"en\": \"Inner gap between the highlight and the child.\",\n          \"pt\": \"Folga interna entre realce e child.\"\n        }\n      },\n      {\n        \"name\": \"enabled\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\",\n        \"description\": {\n          \"en\": \"When false, it does not react and dims the child.\",\n          \"pt\": \"Quando false, não reage e esmaece o child.\"\n        }\n      },\n      {\n        \"name\": \"loading\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\",\n        \"description\": {\n          \"en\": \"Blocks interaction and shows a spinner over the child.\",\n          \"pt\": \"Bloqueia a interação e mostra um spinner sobre o child.\"\n        }\n      },\n      {\n        \"name\": \"semanticLabel\",\n        \"type\": \"String?\",\n        \"required\": false\n      }\n    ],\n    \"variants\": [\n      \"none\",\n      \"scale\",\n      \"lift\",\n      \"pop\",\n      \"rotate\"\n    ],\n    \"states\": [\n      \"hovered\",\n      \"focused\",\n      \"pressed\",\n      \"disabled\",\n      \"loading\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Clickable icon with a tooltip\",\n          \"pt\": \"Ícone clicável com tooltip\"\n        },\n        \"code\": \"AppInteraction(tooltip: 'Adicionar', onTap: add, padding: const EdgeInsets.all(AppSpacings.s8), child: AppIcon(AppIconToken.plus))\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use it to give icons and text a standard click, hover and tooltip.\",\n        \"Add padding for the feel of an icon button.\"\n      ],\n      \"pt\": [\n        \"Use para dar clique/hover/tooltip padrão a ícones e textos.\",\n        \"Adicione padding para o feel de botão de ícone.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it for a primary action with a background and a label — use AppButton.\"\n      ],\n      \"pt\": [\n        \"Não use para ação primária com fundo/rótulo — use AppButton.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Applies a button role (AppSemantics.button) with a semanticLabel; activation with Enter/Space when focused; a focus ring on the highlight. Focus disappears on touch (FocusHighlightMode).\",\n      \"pt\": \"Aplica role de botão (AppSemantics.button) com semanticLabel; ativação por Enter/Space quando focado; anel de foco no highlight. O foco some no toque (FocusHighlightMode).\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_scale_on_tap\",\n      \"app_interactive_motion\",\n      \"app_tooltip\"\n    ]\n  },\n  {\n    \"id\": \"app_hover_highlight\",\n    \"name\": \"AppHoverHighlight\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Purely visual hover highlight — no gesture, no focus, no Tab stop.\",\n      \"pt\": \"Realce de hover puramente visual — sem gesto, sem foco, sem parada de Tab.\"\n    },\n    \"description\": {\n      \"en\": \"It exists for overlay triggers (AppMenu, AppPopover, AppPickerAnchor): they already install click and focus around the trigger, so wrapping the content in an AppInteraction would create TWO targets — a second Tab stop and the classic double-toggle, where the overlay opens on the inner gesture and closes on the outer one. This paints the same translucent highlight as AppInteraction (onSurface at 8%) and nothing else, giving the trigger the affordance of every other clickable item without fighting over the gesture with whoever already owns it.\",\n      \"pt\": \"Existe para os gatilhos de overlay (AppMenu, AppPopover, AppPickerAnchor): eles já instalam clique e foco em volta do trigger, então embrulhar o conteúdo num AppInteraction criaria DOIS alvos — uma segunda parada de Tab e o duplo-toggle clássico, em que o overlay abre no gesto de dentro e fecha no de fora. Este pinta o mesmo realce translúcido do AppInteraction (onSurface a 8%) e nada mais, dando ao gatilho a afordância dos outros itens clicáveis sem disputar o gesto com quem já o tem.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"The content of an overlay trigger that already has a gesture and focus around it.\",\n        \"A row highlight where the click belongs to an ancestor.\"\n      ],\n      \"pt\": [\n        \"Conteúdo de um gatilho de overlay que já tem gesto e foco por fora.\",\n        \"Realce de linha onde o clique é de um ancestral.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A genuinely clickable target → AppInteraction (it brings the gesture, the focus and the semantics).\",\n        \"A button → AppButton.\"\n      ],\n      \"pt\": [\n        \"Alvo clicável de verdade → AppInteraction (traz gesto, foco e semântica).\",\n        \"Botão → AppButton.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"child\",\n        \"type\": \"Widget\",\n        \"required\": true,\n        \"description\": {\n          \"en\": \"Highlighted content.\",\n          \"pt\": \"Conteúdo realçado.\"\n        }\n      },\n      {\n        \"name\": \"padding\",\n        \"type\": \"EdgeInsetsGeometry\",\n        \"required\": false,\n        \"default\": \"EdgeInsets.zero\",\n        \"description\": {\n          \"en\": \"Breathing room between the highlight and the content — it is what gives the painted area its body; at zero the highlight clings to the text.\",\n          \"pt\": \"Respiro entre o realce e o conteúdo — é ele que dá corpo à área pintada; com zero o realce fica colado no texto.\"\n        }\n      },\n      {\n        \"name\": \"borderRadius\",\n        \"type\": \"BorderRadius?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Shape of the highlight. Default: the theme's global radius.\",\n          \"pt\": \"Forma do realce. Default: o raio global do tema.\"\n        }\n      }\n    ],\n    \"states\": [\n      \"rest\",\n      \"hover\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Trigger for a menu\",\n          \"pt\": \"Gatilho de um menu\"\n        },\n        \"code\": \"AppMenu(\\n  entries: entries,\\n  child: const AppHoverHighlight(\\n    padding: EdgeInsets.symmetric(\\n      horizontal: AppSpacings.s8,\\n      vertical: AppSpacings.s4,\\n    ),\\n    child: AppText('Ações'),\\n  ),\\n)\",\n        \"description\": {\n          \"en\": \"AppMenu already installs click and focus; only the affordance was missing.\",\n          \"pt\": \"O AppMenu já instala clique e foco; aqui só falta a afordância.\"\n        }\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Give it padding: without it the highlight clings to the text and disappears visually.\"\n      ],\n      \"pt\": [\n        \"Dê padding: sem ele o realce nasce colado no texto e some visualmente.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it as a clickable target — it has no gesture, no focus and no semantics.\",\n        \"Do not nest it inside an AppInteraction: the two highlights add up.\"\n      ],\n      \"pt\": [\n        \"Não use como alvo clicável — ele não tem gesto, foco nem semântica.\",\n        \"Não aninhe dentro de um AppInteraction: os dois realces somam.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"It stays out of the semantics tree on purpose: the role, the label and the focus belong to the trigger outside it. Not creating a second focusable node is precisely why it exists.\",\n      \"pt\": \"Não entra na árvore semântica de propósito: quem carrega papel, rótulo e foco é o gatilho por fora. É justamente por não criar um segundo nó focável que ele existe.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_interaction\",\n      \"app_menu\",\n      \"app_popover\"\n    ]\n  },\n  {\n    \"id\": \"app_copy_button\",\n    \"name\": \"AppCopyButton\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Copy button with animated confirmation in the button itself (icon and tooltip).\",\n      \"pt\": \"Botão de copiar com confirmação animada no próprio botão (ícone e tooltip).\"\n    },\n    \"description\": {\n      \"en\": \"Writes a value to the clipboard and confirms it under the cursor: the icon becomes a check in the success color and the tooltip changes from \\\"Copy\\\" to \\\"Copied!\\\", both with a smooth transition, returning to rest after 1.6 s. The tick is DRAWN (AppCheckmarkPainter), not downloaded: a network SVG that fails never retries, and the failure would become a permanent visual error at the very moment of confirmation.\",\n      \"pt\": \"Escreve um valor na área de transferência e confirma sob o cursor: o ícone vira um check na cor de sucesso e a tooltip troca de \\\"Copiar\\\" para \\\"Copiado!\\\", as duas com transição suave, voltando ao repouso após 1,6 s. O tique é DESENHADO (AppCheckmarkPainter), não baixado: um SVG de rede que falha nunca retenta, e a falha viraria um erro visual permanente bem no momento da confirmação.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Copying an identifier next to its value (ID, tax number, integration code).\",\n        \"Screens with several copy buttons, where snackbars would pile up.\"\n      ],\n      \"pt\": [\n        \"Copiar um identificador ao lado do valor dele (ID, CNPJ, código de integração).\",\n        \"Telas com vários botões de copiar, onde snackbars se empilhariam.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Copy as a menu item or a labelled action → AppMenuItem/AppButton.\",\n        \"A trigger that is not an icon (a chip with text) → AppInteraction + Clipboard.\"\n      ],\n      \"pt\": [\n        \"Copiar como item de menu ou ação com rótulo → AppMenuItem/AppButton.\",\n        \"Trigger que não é um ícone (chip com texto) → AppInteraction + Clipboard.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"value\",\n        \"type\": \"String\",\n        \"required\": true,\n        \"description\": {\n          \"en\": \"Text written to the clipboard.\",\n          \"pt\": \"Texto escrito na área de transferência.\"\n        }\n      },\n      {\n        \"name\": \"color\",\n        \"type\": \"Color?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Icon color at rest (null = onSurface).\",\n          \"pt\": \"Cor do ícone em repouso (null = onSurface).\"\n        }\n      },\n      {\n        \"name\": \"copiedDuration\",\n        \"type\": \"Duration\",\n        \"required\": false,\n        \"default\": \"kAppCopiedFeedback (1600ms)\",\n        \"description\": {\n          \"en\": \"How long the copied state lasts.\",\n          \"pt\": \"Quanto tempo o estado copiado dura.\"\n        }\n      },\n      {\n        \"name\": \"copiedTooltip\",\n        \"type\": \"String\",\n        \"required\": false,\n        \"default\": \"'Copiado!'\"\n      },\n      {\n        \"name\": \"copyTooltip\",\n        \"type\": \"String\",\n        \"required\": false,\n        \"default\": \"'Copiar'\"\n      },\n      {\n        \"name\": \"enabled\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\",\n        \"description\": {\n          \"en\": \"When false, it does not react and dims the icon.\",\n          \"pt\": \"Quando false, não reage e esmaece o ícone.\"\n        }\n      },\n      {\n        \"name\": \"iconSize\",\n        \"type\": \"AppIconSize\",\n        \"required\": false,\n        \"default\": \"AppIconSize.s\",\n        \"description\": {\n          \"en\": \"Icon size; together with the padding it sets the target's side.\",\n          \"pt\": \"Tamanho do ícone; define o lado do alvo com o padding.\"\n        },\n        \"enumValues\": [\n          \"s\",\n          \"m\",\n          \"l\",\n          \"xl\"\n        ]\n      },\n      {\n        \"name\": \"onCopied\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Fired after writing to the clipboard.\",\n          \"pt\": \"Disparado depois de escrever na área de transferência.\"\n        }\n      },\n      {\n        \"name\": \"onCopyFailed\",\n        \"type\": \"ValueChanged<Object>?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Fired when the write fails; the button does not confirm in that case.\",\n          \"pt\": \"Disparado quando a escrita falha; o botão não confirma nesse caso.\"\n        }\n      },\n      {\n        \"name\": \"padding\",\n        \"type\": \"EdgeInsetsGeometry\",\n        \"required\": false,\n        \"default\": \"EdgeInsets.all(AppSpacings.s4)\",\n        \"description\": {\n          \"en\": \"Symmetric inner gap between the highlight and the icon.\",\n          \"pt\": \"Folga interna simétrica entre o realce e o ícone.\"\n        }\n      },\n      {\n        \"name\": \"tooltipPosition\",\n        \"type\": \"AppTooltipPosition\",\n        \"required\": false,\n        \"default\": \"AppTooltipPosition.top\",\n        \"enumValues\": [\n          \"top\",\n          \"bottom\",\n          \"left\",\n          \"right\"\n        ]\n      }\n    ],\n    \"variants\": [\n      \"s\",\n      \"m\",\n      \"l\",\n      \"xl\"\n    ],\n    \"states\": [\n      \"hovered\",\n      \"focused\",\n      \"pressed\",\n      \"disabled\",\n      \"copied\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Copyable identifier\",\n          \"pt\": \"Identificador copiável\"\n        },\n        \"code\": \"AppCopyButton(value: account.integrationId)\"\n      },\n      {\n        \"title\": {\n          \"en\": \"Its own label and telemetry\",\n          \"pt\": \"Rótulo próprio e telemetria\"\n        },\n        \"code\": \"AppCopyButton(value: endpoint.path, copyTooltip: 'Copiar path', onCopied: () => analytics.track('path_copied'))\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Keep the spacing to its neighbours outside the button (the highlight wraps the whole child).\",\n        \"Use onCopied to instrument or react to the copy.\"\n      ],\n      \"pt\": [\n        \"Deixe o espaçamento com os vizinhos fora do botão (o realce envolve o child inteiro).\",\n        \"Use onCopied para instrumentar ou reagir à cópia.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not stack a snackbar on top — the inline feedback is already the confirmation.\",\n        \"Do not swap AppCheckmarkPainter for AppIconToken.check: that puts the network back in the exact moment of confirmation, and an SvgPicture that fails never tries again.\"\n      ],\n      \"pt\": [\n        \"Não empilhe um snackbar por cima — o feedback inline já é a confirmação.\",\n        \"Não troque o AppCheckmarkPainter por AppIconToken.check: volta a depender da rede no exato momento da confirmação, e um SvgPicture que falha nunca tenta de novo.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"A button role (AppSemantics.button) with the semanticLabel following the tooltip, so the screen reader announces \\\"Copied!\\\" after the action. The inner icons are decorative. Enter/Space activate it when focused; under reduce-motion the swap is instant.\",\n      \"pt\": \"Role de botão (AppSemantics.button) com semanticLabel acompanhando a tooltip, então o leitor de tela anuncia \\\"Copiado!\\\" após a ação. Os ícones internos são decorativos. Enter/Space acionam quando focado; sob reduce-motion a troca é instantânea.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_interaction\",\n      \"app_tooltip\",\n      \"app_code_block\"\n    ]\n  },\n  {\n    \"id\": \"app_breadcrumb\",\n    \"name\": \"AppBreadcrumb\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Navigation trail with clickable items and separators.\",\n      \"pt\": \"Trilha de navegação com itens clicáveis e separadores.\"\n    },\n    \"description\": {\n      \"en\": \"Clickable items on FlocksInteraction (hover/press/focus/keyboard) with a highlight and a focus ring; link text in a legible stop (≥ AA) of the accent color, current item in onSurface. Colors from the theme; radius and animation global.\",\n      \"pt\": \"Itens clicáveis sobre FlocksInteraction (hover/press/foco/teclado) com realce e anel de foco; texto do link num stop legível (≥ AA) da cor de acento, item atual em onSurface. Cores do tema; raio/animação globais.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Showing and navigating the current page hierarchy.\"\n      ],\n      \"pt\": [\n        \"Mostrar e navegar a hierarquia de páginas atual.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Primary navigation between sections → a menu or nav rail (organism).\"\n      ],\n      \"pt\": [\n        \"Navegação primária entre seções → menu/nav rail (organism).\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"items\",\n        \"type\": \"List<AppBreadcrumbItem>\",\n        \"required\": true,\n        \"description\": {\n          \"en\": \"Items from the shallowest to the current one; a null onTap marks the current item.\",\n          \"pt\": \"Itens do mais raso ao atual; onTap null = item atual.\"\n        }\n      }\n    ],\n    \"states\": [\n      \"clickable\",\n      \"current\",\n      \"hovered\",\n      \"focused\",\n      \"pressed\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Plain trail\",\n          \"pt\": \"Trilha simples\"\n        },\n        \"code\": \"AppBreadcrumb(items: [AppBreadcrumbItem(label: 'Início', onTap: goHome), AppBreadcrumbItem(label: 'Veículos')])\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Leave the last (current) item without an onTap — it becomes the onSurface highlight.\"\n      ],\n      \"pt\": [\n        \"Deixe o último item (atual) sem onTap — vira o destaque onSurface.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it as primary navigation.\"\n      ],\n      \"pt\": [\n        \"Não use como navegação primária.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Clickable items with a button role (AppSemantics.button) + Enter/Space; the link in a legible accent ≥ AA against the surface; current item in onSurface.\",\n      \"pt\": \"Itens clicáveis com role de botão (AppSemantics.button) + Enter/Space; link em acento legível ≥ AA sobre a superfície; item atual em onSurface.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_action_item\"\n    ]\n  },\n  {\n    \"id\": \"app_button\",\n    \"name\": \"AppButton\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Action button (label/icon) that varies along the global AppStyle axis.\",\n      \"pt\": \"Botão de ação (rótulo/ícone) que varia pelo eixo global AppStyle.\"\n    },\n    \"description\": {\n      \"en\": \"The design system's only button with a label/icon. It varies along the AppStyle axis: filled (solid primary), outlined (bordered secondary) and elevated (solid + symmetric shadow). Background and content hold AA contrast in every state; hover/press deepen the background. Built on FlocksInteraction (focus/keyboard/ring), with press-scale through AppMotion, a loading state and the global radius. Replaces AppFillButton/AppLineButton.\",\n      \"pt\": \"Único botão com rótulo/ícone do DS. Varia pelo eixo AppStyle: filled (primária preenchida), outlined (secundária contornada) e elevated (preenchida + sombra simétrica). Fundo/conteúdo com contraste AA em todos os estados; hover/press aprofundam o fundo. Sobre FlocksInteraction (foco/teclado/anel), press-scale via AppMotion, loading e raio global. Substitui AppFillButton/AppLineButton.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Any action with a label or icon; pick the emphasis through style.\"\n      ],\n      \"pt\": [\n        \"Qualquer ação com rótulo/ícone; escolha a ênfase via style.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Icon only → AppIconButton.\",\n        \"Tertiary/link (no container) → AppTextButton.\",\n        \"An action plus a menu of actions → AppSplitButton.\"\n      ],\n      \"pt\": [\n        \"Só ícone → AppIconButton.\",\n        \"Terciária/link (sem container) → AppTextButton.\",\n        \"Ação + menu de ações → AppSplitButton.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"onPressed\",\n        \"type\": \"VoidCallback?\",\n        \"required\": true\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppStyle?\",\n        \"required\": false,\n        \"default\": \"theme.styleTheme.style\",\n        \"enumValues\": [\n          \"filled\",\n          \"outlined\",\n          \"elevated\"\n        ]\n      },\n      {\n        \"name\": \"label\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"icon\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"color\",\n        \"type\": \"AppButtonColor\",\n        \"required\": false,\n        \"default\": \"AppButtonColor.primary\",\n        \"enumValues\": [\n          \"danger\",\n          \"info\",\n          \"neutral\",\n          \"primary\",\n          \"secondary\",\n          \"success\",\n          \"tertiary\",\n          \"warning\"\n        ]\n      },\n      {\n        \"name\": \"size\",\n        \"type\": \"AppButtonSize\",\n        \"required\": false,\n        \"default\": \"AppButtonSize.l\",\n        \"enumValues\": [\n          \"s\",\n          \"m\",\n          \"l\"\n        ]\n      },\n      {\n        \"name\": \"loading\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      },\n      {\n        \"name\": \"enabled\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"expandedWidth\",\n        \"type\": \"bool?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"fixedWidth\",\n        \"type\": \"double?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"radiusMode\",\n        \"type\": \"AppRadiusMode?\",\n        \"required\": false,\n        \"enumValues\": [\n          \"reto\",\n          \"redondo\",\n          \"circular\",\n          \"padrao\"\n        ]\n      },\n      {\n        \"name\": \"radius\",\n        \"type\": \"BorderRadius?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"semanticsLabel\",\n        \"type\": \"String?\",\n        \"required\": false\n      }\n    ],\n    \"variants\": [\n      \"filled\",\n      \"outlined\",\n      \"elevated\",\n      \"icon+label\",\n      \"icon-only\"\n    ],\n    \"states\": [\n      \"default\",\n      \"hovered\",\n      \"pressed\",\n      \"focused\",\n      \"disabled\",\n      \"loading\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Primary\",\n          \"pt\": \"Primária\"\n        },\n        \"code\": \"AppButton(label: 'Salvar', onPressed: save)\"\n      },\n      {\n        \"title\": {\n          \"en\": \"Secondary\",\n          \"pt\": \"Secundária\"\n        },\n        \"code\": \"AppButton(style: AppStyle.outlined, label: 'Cancelar', onPressed: cancel)\"\n      },\n      {\n        \"title\": {\n          \"en\": \"Elevated\",\n          \"pt\": \"Elevada\"\n        },\n        \"code\": \"AppButton(style: AppStyle.elevated, label: 'Publicar', onPressed: publish)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"One primary button per screen; use outlined for the secondary one.\"\n      ],\n      \"pt\": [\n        \"1 botão primário por tela; use outlined para o secundário.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it for plain text navigation (→ AppTextButton).\"\n      ],\n      \"pt\": [\n        \"Não use para navegação de texto puro (→ AppTextButton).\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"AppSemantics.button (label defaults to label; enabled/loading reflected); Enter/Space; content ≥ AA against the background in every state and style.\",\n      \"pt\": \"AppSemantics.button (label default = label; enabled/loading refletidos); Enter/Space; conteúdo ≥ AA sobre o fundo em todos os estados/estilos.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_interaction\",\n      \"app_split_button\"\n    ]\n  },\n  {\n    \"id\": \"app_floating_button\",\n    \"name\": \"AppFloatingButton\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Floating action button (FAB) with a shadow that is always there; icon and/or label, circular by default.\",\n      \"pt\": \"Ação flutuante (FAB) com sombra sempre presente; ícone e/ou rótulo, circular por padrão.\"\n    },\n    \"description\": {\n      \"en\": \"Floating action button. Takes an icon and/or a label (icon-only, text-only or extended). It floats above the content → it ALWAYS has a shadow, even outside the elevated style. It varies along the AppStyle axis: filled, outlined, elevated and glass (real blurred glass, through AppGlassSurface, degrading to opaque when transparency is reduced). Circular by default (it inherits the global shape; local reto/redondo/circular are honored). Delegates to ButtonCore: states, AA colors, focus ring, press-scale (AppMotion), loading and a11y.\",\n      \"pt\": \"Botão de ação flutuante. Aceita ícone e/ou rótulo (só-ícone, só-texto ou estendido). Paira sobre o conteúdo → tem sombra SEMPRE, mesmo fora do estilo elevated. Varia pelo eixo AppStyle: filled, outlined, elevated e glass (vidro real com blur, via AppGlassSurface, degradando para opaco quando a transparência é reduzida). Forma padrão circular (herda o global; reto/redondo/circular locais honrados). Delega a ButtonCore: estados, cores AA, anel de foco, press-scale (AppMotion), loading e a11y.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"A persistent primary action floating over the content (e.g. create/new).\"\n      ],\n      \"pt\": [\n        \"Ação primária persistente, flutuando sobre o conteúdo (ex.: criar/novo).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"An inline action in the flow (on the content's line, with a label) → AppButton.\",\n        \"A secondary/tertiary action with no floating prominence → AppButton.\"\n      ],\n      \"pt\": [\n        \"Ação inline no fluxo (na linha do conteúdo, com rótulo) → AppButton.\",\n        \"Ação secundária/terciária sem destaque flutuante → AppButton.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"onPressed\",\n        \"type\": \"VoidCallback?\",\n        \"required\": true\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppStyle?\",\n        \"required\": false,\n        \"default\": \"theme.styleTheme.style\",\n        \"enumValues\": [\n          \"filled\",\n          \"outlined\",\n          \"elevated\"\n        ]\n      },\n      {\n        \"name\": \"glass\",\n        \"type\": \"bool?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Glass axis (real glass). null follows the global glassTheme.\",\n          \"pt\": \"Eixo glass (vidro real). null segue o global glassTheme.\"\n        }\n      },\n      {\n        \"name\": \"label\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"icon\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"color\",\n        \"type\": \"AppButtonColor\",\n        \"required\": false,\n        \"default\": \"AppButtonColor.primary\",\n        \"enumValues\": [\n          \"danger\",\n          \"info\",\n          \"neutral\",\n          \"primary\",\n          \"secondary\",\n          \"success\",\n          \"tertiary\",\n          \"warning\"\n        ]\n      },\n      {\n        \"name\": \"size\",\n        \"type\": \"AppButtonSize\",\n        \"required\": false,\n        \"default\": \"AppButtonSize.l\",\n        \"description\": {\n          \"en\": \"Height/side (s=40/m=48/l=56) and the icon-only glyph (s→16/m→24/l→32).\",\n          \"pt\": \"Altura/lado (s=40/m=48/l=56) e o glifo só-ícone (s→16/m→24/l→32).\"\n        },\n        \"enumValues\": [\n          \"s\",\n          \"m\",\n          \"l\"\n        ]\n      },\n      {\n        \"name\": \"loading\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      },\n      {\n        \"name\": \"enabled\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"radiusMode\",\n        \"type\": \"AppRadiusMode?\",\n        \"required\": false,\n        \"enumValues\": [\n          \"reto\",\n          \"redondo\",\n          \"circular\",\n          \"padrao\"\n        ]\n      },\n      {\n        \"name\": \"radius\",\n        \"type\": \"BorderRadius?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onLongPress\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"semanticsLabel\",\n        \"type\": \"String?\",\n        \"required\": false\n      }\n    ],\n    \"variants\": [\n      \"filled\",\n      \"outlined\",\n      \"elevated\",\n      \"glass\",\n      \"icon-only\",\n      \"text-only\",\n      \"icon+label\"\n    ],\n    \"states\": [\n      \"default\",\n      \"hovered\",\n      \"pressed\",\n      \"focused\",\n      \"disabled\",\n      \"loading\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Circle (icon-only)\",\n          \"pt\": \"Círculo (só-ícone)\"\n        },\n        \"code\": \"AppFloatingButton(icon: AppIconToken.add, onPressed: create)\"\n      },\n      {\n        \"title\": {\n          \"en\": \"Extended (icon + label)\",\n          \"pt\": \"Estendido (ícone + rótulo)\"\n        },\n        \"code\": \"AppFloatingButton(icon: AppIconToken.add, label: 'Novo', onPressed: create)\"\n      },\n      {\n        \"title\": {\n          \"en\": \"Glass\",\n          \"pt\": \"Vidro\"\n        },\n        \"code\": \"AppFloatingButton(glass: true, icon: AppIconToken.add, onPressed: create)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"One FAB per screen; circular for icon-only, stadium when extended.\"\n      ],\n      \"pt\": [\n        \"1 FAB por tela; forma circular para só-ícone, stadium quando estendido.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it for inline labelled actions in the flow (→ AppButton).\"\n      ],\n      \"pt\": [\n        \"Não use para ações inline com rótulo no fluxo (→ AppButton).\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"AppSemantics.button (label defaults to label or to the icon name; enabled/loading reflected); Enter/Space; content ≥ AA against the background in every state and style. Glass degrades to opaque when transparency is reduced, preserving contrast.\",\n      \"pt\": \"AppSemantics.button (label default = label ou nome do ícone; enabled/loading refletidos); Enter/Space; conteúdo ≥ AA sobre o fundo em todos os estados/estilos. Glass degrada para opaco quando a transparência é reduzida, preservando contraste.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_button\",\n      \"app_scaffold\"\n    ]\n  },\n  {\n    \"id\": \"app_dropdown\",\n    \"name\": \"AppDropdown\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Single-selection dropdown.\",\n      \"pt\": \"Dropdown de seleção única.\"\n    },\n    \"description\": {\n      \"en\": \"A trigger with Tab focus (FlocksInteraction), an animated chevron (AppMotion) and an options overlay (AppCard). Colors 100% from the theme (outline border / primary when open / danger on error; accents in a legible stop). Choosing closes the overlay.\",\n      \"pt\": \"Trigger com foco-Tab (FlocksInteraction), chevron animado (AppMotion) e overlay de opções (AppCard). Cores 100% do tema (borda outline / primary aberto / danger erro; acentos em stop legível). A escolha fecha o overlay.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Choosing one option among a few or a moderate number (up to ~15).\"\n      ],\n      \"pt\": [\n        \"Escolher uma opção entre poucas/médias (até ~15).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Many options → AppSearchableDropdown.\",\n        \"Several selections → AppMultiSelect.\"\n      ],\n      \"pt\": [\n        \"Muitas opções → AppSearchableDropdown.\",\n        \"Várias seleções → AppMultiSelect.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"options\",\n        \"type\": \"List<AppDropdownOption<T>>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"onChanged\",\n        \"type\": \"ValueChanged<T?>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"selectedValue\",\n        \"type\": \"T?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"label\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"info\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"hintText\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"helperText\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"errorText\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"hasError\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      },\n      {\n        \"name\": \"enabled\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      }\n    ],\n    \"states\": [\n      \"closed\",\n      \"open\",\n      \"focused\",\n      \"error\",\n      \"disabled\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Single\",\n          \"pt\": \"Único\"\n        },\n        \"code\": \"AppDropdown<String>(options: opts, selectedValue: v, onChanged: set)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use label + hintText for clarity.\"\n      ],\n      \"pt\": [\n        \"Use label + hintText para clareza.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it for many options without search.\"\n      ],\n      \"pt\": [\n        \"Não use para muitas opções sem busca.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Focusable trigger (Enter/Space opens it); border/accent in a legible stop ≥ 3:1; error in a legible danger.\",\n      \"pt\": \"Trigger focável (Enter/Space abre); borda/acento em stop legível ≥ 3:1; erro em danger legível.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_multi_select\",\n      \"app_searchable_dropdown\"\n    ]\n  },\n  {\n    \"id\": \"app_input\",\n    \"name\": \"AppInput\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Design system text field (built on a bare EditableText).\",\n      \"pt\": \"Campo de texto do design system (sobre EditableText cru).\"\n    },\n    \"description\": {\n      \"en\": \"A text field with no Material and no Cupertino. It takes part in the global style (AppStyle: outlined by default, filled, elevated) and shape (AppRadiusMode) axes. State colors (rest/focus/error/disabled) are resolved by inputFieldColors — the same recipe as the dropdown trigger. Native mouse selection (double/triple-tap, context menu) through AppTextSelectionGestures. With onTap it becomes an action field (pickers).\",\n      \"pt\": \"Campo de texto sem Material/Cupertino. Participa do eixo global de estilo (AppStyle: outlined default, filled, elevated) e de forma (AppRadiusMode). Cores de estado (repouso/foco/erro/desabilitado) resolvidas por inputFieldColors — mesma receita do trigger do dropdown. Seleção nativa de mouse (double/triple-tap, menu de contexto) via AppTextSelectionGestures. Com onTap vira campo de ação (pickers).\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Single-line or multiline text input (up to 5 lines).\",\n        \"The base for action fields (date/time/color pickers) through onTap.\"\n      ],\n      \"pt\": [\n        \"Entrada de texto de linha única ou multilinha (até 5 linhas).\",\n        \"Base para campos de ação (date/time/color pickers) via onTap.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Choosing among options → AppDropdown.\",\n        \"Picking a date or time → AppDatePickerInput/AppTimePickerInput.\"\n      ],\n      \"pt\": [\n        \"Escolha entre opções → AppDropdown.\",\n        \"Seleção de data/hora → AppDatePickerInput/AppTimePickerInput.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"controller\",\n        \"type\": \"TextEditingController?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"initialValue\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"label\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"hintText\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"helperText\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"errorText\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"prefixIcon\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"suffixIcon\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"info\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onClear\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppStyle\",\n        \"required\": false,\n        \"default\": \"AppStyle.outlined\",\n        \"enumValues\": [\n          \"filled\",\n          \"outlined\",\n          \"elevated\"\n        ]\n      },\n      {\n        \"name\": \"radiusMode\",\n        \"type\": \"AppRadiusMode?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"radius\",\n        \"type\": \"BorderRadius?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"background\",\n        \"type\": \"Color?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"enabled\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"hasError\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      },\n      {\n        \"name\": \"obscureText\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      },\n      {\n        \"name\": \"readOnly\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      },\n      {\n        \"name\": \"maxLines\",\n        \"type\": \"int\",\n        \"required\": false,\n        \"default\": \"1\"\n      },\n      {\n        \"name\": \"maxLength\",\n        \"type\": \"int?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"showCounter\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      },\n      {\n        \"name\": \"onChanged\",\n        \"type\": \"void Function(String)?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onSubmitted\",\n        \"type\": \"void Function(String)?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onTap\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      }\n    ],\n    \"variants\": [\n      \"outlined\",\n      \"filled\",\n      \"elevated\"\n    ],\n    \"states\": [\n      \"enabled\",\n      \"focused\",\n      \"error\",\n      \"disabled\",\n      \"read-only\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Basic\",\n          \"pt\": \"Básico\"\n        },\n        \"code\": \"AppInput(label: 'E-mail', hintText: 'nome@dominio.com', onChanged: set)\"\n      },\n      {\n        \"title\": {\n          \"en\": \"Error\",\n          \"pt\": \"Erro\"\n        },\n        \"code\": \"AppInput(label: 'Nome', errorText: 'Obrigatório', hasError: true)\"\n      },\n      {\n        \"title\": {\n          \"en\": \"Info (popover)\",\n          \"pt\": \"Info (popover)\"\n        },\n        \"code\": \"AppInput(label: 'E-mail', info: AppText('Usamos só para login.'))\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use label + hintText for clarity.\",\n        \"Use errorText for validation feedback.\",\n        \"Pass info to explain the field in a popover beside the label.\"\n      ],\n      \"pt\": [\n        \"Use label + hintText para clareza.\",\n        \"Use errorText para feedback de validação.\",\n        \"Passe info para explicar o campo num popover ao lado do label.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it to choose among options (use AppDropdown).\"\n      ],\n      \"pt\": [\n        \"Não use para escolher entre opções (use AppDropdown).\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Native mouse/keyboard selection; border/accent in a legible stop ≥ 3:1; error in a legible danger.\",\n      \"pt\": \"Seleção nativa de mouse/teclado; borda/acento em stop legível ≥ 3:1; erro em danger legível.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_dropdown\",\n      \"app_date_picker_input\",\n      \"app_color_picker_input\"\n    ]\n  },\n  {\n    \"id\": \"app_date_picker_input\",\n    \"name\": \"AppDatePickerInput\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Date field: type it with a DD/MM/YYYY mask or pick it from the calendar.\",\n      \"pt\": \"Campo de data: digitar com máscara DD/MM/AAAA ou escolher no calendário.\"\n    },\n    \"description\": {\n      \"en\": \"The two doors are deliberate. Whoever knows the date types it — always faster than navigating months in a calendar — and gets an automatic mask (AppDateMaskFormatter). Whoever only knows \\\"next Tuesday\\\" opens the panel from the icon. The panel is an elevated AppCard anchored to the field, exactly like AppDropdown's: the same gesture opens a panel on any field in the form. firstDate/lastDate bound both the calendar AND what can be typed.\",\n      \"pt\": \"As duas portas de entrada convivem de propósito. Quem sabe a data digita — é sempre mais rápido que navegar meses num calendário — e ganha máscara automática (AppDateMaskFormatter). Quem só sabe \\\"a próxima terça\\\" abre o painel pelo ícone. O painel é um AppCard elevado, ancorado ao campo, igual ao do AppDropdown: o mesmo gesto abre painel em qualquer campo do formulário. firstDate/lastDate limitam o calendário E a digitação.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"A single date in a form (a due date, the start of a validity period).\",\n        \"A date filter in a list toolbar.\"\n      ],\n      \"pt\": [\n        \"Data única num formulário (vencimento, início de vigência).\",\n        \"Filtro por data em toolbar de listagem.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A range (from/to) → AppDateRangePicker.\",\n        \"Date + time in the same field → AppDateTimePickerInput.\",\n        \"A calendar kept visible on the screen → AppDatePicker directly.\"\n      ],\n      \"pt\": [\n        \"Intervalo (de/até) → AppDateRangePicker.\",\n        \"Data + hora no mesmo campo → AppDateTimePickerInput.\",\n        \"Calendário sempre visível na tela → AppDatePicker direto.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"onDateSelected\",\n        \"type\": \"ValueChanged<DateTime>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"initialDate\",\n        \"type\": \"DateTime?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"firstDate\",\n        \"type\": \"DateTime?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Floor for the calendar and for validating what is typed.\",\n          \"pt\": \"Piso do calendário e da validação da digitação.\"\n        }\n      },\n      {\n        \"name\": \"lastDate\",\n        \"type\": \"DateTime?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Ceiling, likewise.\",\n          \"pt\": \"Teto idem.\"\n        }\n      },\n      {\n        \"name\": \"label\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"hintText\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"helperText\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"errorText\",\n        \"type\": \"String?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Replaces the helper on the same line (the form does not jump).\",\n          \"pt\": \"Substitui o helper na mesma linha (o form não salta).\"\n        }\n      },\n      {\n        \"name\": \"hasError\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\",\n        \"description\": {\n          \"en\": \"The frame only, for when the message lives somewhere else.\",\n          \"pt\": \"Só a moldura, para quando a mensagem está em outro lugar.\"\n        }\n      },\n      {\n        \"name\": \"enabled\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"info\",\n        \"type\": \"Widget?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Help in a popover beside the label.\",\n          \"pt\": \"Ajuda em popover ao lado do rótulo.\"\n        }\n      },\n      {\n        \"name\": \"size\",\n        \"type\": \"AppFieldSize\",\n        \"required\": false,\n        \"default\": \"AppFieldSize.m\",\n        \"enumValues\": [\n          \"s\",\n          \"m\",\n          \"l\"\n        ]\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppStyle?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"radiusMode\",\n        \"type\": \"AppRadiusMode?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"radius\",\n        \"type\": \"BorderRadius?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"empty\",\n      \"filled\",\n      \"error\",\n      \"disabled\",\n      \"open\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Due date\",\n          \"pt\": \"Data de vencimento\"\n        },\n        \"code\": \"AppDatePickerInput(\\n  label: 'Vencimento',\\n  hintText: 'DD/MM/AAAA',\\n  firstDate: DateTime.now(),\\n  onDateSelected: form.setDueDate,\\n)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Give it firstDate/lastDate — they bound the calendar and the typing at once.\"\n      ],\n      \"pt\": [\n        \"Informe firstDate/lastDate — limitam calendário e digitação de uma vez.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not block typing to \\\"force\\\" the calendar: it is slower for someone who already knows the date.\"\n      ],\n      \"pt\": [\n        \"Não bloqueie a digitação para \\\"forçar\\\" o calendário: é mais lento para quem já sabe a data.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"The field is a textField with the label as its label; the icon that opens the panel is a labelled button, not a mute glyph. The error enters as a live region, so validation is announced without the user going back to the field.\",\n      \"pt\": \"O campo é textField com o label como rótulo; o ícone que abre o painel é botão rotulado, não um glifo mudo. O erro entra como região viva, para a validação ser anunciada sem o usuário voltar ao campo.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_date_picker\",\n      \"app_date_time_picker_input\",\n      \"app_input\"\n    ]\n  },\n  {\n    \"id\": \"app_time_picker_input\",\n    \"name\": \"AppTimePickerInput\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Time field: type it with an HH:mm mask or pick it from the wheels.\",\n      \"pt\": \"Campo de horário: digitar com máscara HH:mm ou escolher nas rodas.\"\n    },\n    \"description\": {\n      \"en\": \"The same piece as the date field, with a time mask (AppTimeMaskFormatter) and wheels in the panel. `showSeconds` adds the third wheel and changes the mask along with it — the two always move together, otherwise the field accepts a format the panel cannot produce. The floors (minHour/minMinute/minSecond) exist for the \\\"end time after the start time\\\" case, where the limit depends on another field.\",\n      \"pt\": \"Mesma peça do campo de data, com máscara de horário (AppTimeMaskFormatter) e rodas no painel. `showSeconds` acrescenta a terceira roda e muda a máscara junto — as duas coisas andam sempre casadas, senão o campo aceita um formato que o painel não produz. Os pisos (minHour/minMinute/minSecond) existem para o caso \\\"hora final depois da inicial\\\", em que o limite muda conforme outro campo.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"A standalone time (a service window, a cutoff time).\",\n        \"A from/to pair, where the second one's floor comes from the first.\"\n      ],\n      \"pt\": [\n        \"Horário isolado (janela de atendimento, horário de corte).\",\n        \"Par de campos de/até, com o piso do segundo vindo do primeiro.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Date + time in the same field → AppDateTimePickerInput.\",\n        \"A duration (2h30) → a numeric field; this is a time of day.\"\n      ],\n      \"pt\": [\n        \"Data + hora no mesmo campo → AppDateTimePickerInput.\",\n        \"Duração (2h30) → campo numérico; isto é hora do dia.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"onTimeSelected\",\n        \"type\": \"ValueChanged<TimeOfDay>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"initialHour\",\n        \"type\": \"int?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"initialMinute\",\n        \"type\": \"int?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"initialSecond\",\n        \"type\": \"int?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"showSeconds\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\",\n        \"description\": {\n          \"en\": \"Adds the seconds wheel and adjusts the mask.\",\n          \"pt\": \"Acrescenta a roda de segundos e ajusta a máscara.\"\n        }\n      },\n      {\n        \"name\": \"minHour\",\n        \"type\": \"int\",\n        \"required\": false,\n        \"default\": \"0\"\n      },\n      {\n        \"name\": \"minMinute\",\n        \"type\": \"int\",\n        \"required\": false,\n        \"default\": \"0\"\n      },\n      {\n        \"name\": \"minSecond\",\n        \"type\": \"int\",\n        \"required\": false,\n        \"default\": \"0\"\n      },\n      {\n        \"name\": \"label\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"hintText\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"helperText\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"errorText\",\n        \"type\": \"String?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Replaces the helper on the same line (the form does not jump).\",\n          \"pt\": \"Substitui o helper na mesma linha (o form não salta).\"\n        }\n      },\n      {\n        \"name\": \"hasError\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\",\n        \"description\": {\n          \"en\": \"The frame only, for when the message lives somewhere else.\",\n          \"pt\": \"Só a moldura, para quando a mensagem está em outro lugar.\"\n        }\n      },\n      {\n        \"name\": \"enabled\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"info\",\n        \"type\": \"Widget?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Help in a popover beside the label.\",\n          \"pt\": \"Ajuda em popover ao lado do rótulo.\"\n        }\n      },\n      {\n        \"name\": \"size\",\n        \"type\": \"AppFieldSize\",\n        \"required\": false,\n        \"default\": \"AppFieldSize.m\",\n        \"enumValues\": [\n          \"s\",\n          \"m\",\n          \"l\"\n        ]\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppStyle?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"radiusMode\",\n        \"type\": \"AppRadiusMode?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"radius\",\n        \"type\": \"BorderRadius?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"empty\",\n      \"filled\",\n      \"error\",\n      \"disabled\",\n      \"open\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Service window\",\n          \"pt\": \"Janela de atendimento\"\n        },\n        \"code\": \"AppTimePickerInput(\\n  label: 'Abre às',\\n  hintText: 'HH:mm',\\n  onTimeSelected: form.setOpensAt,\\n)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use the floors when the time depends on another field.\"\n      ],\n      \"pt\": [\n        \"Use os pisos quando o horário depende de outro campo.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not turn showSeconds on just \\\"for precision\\\": three wheels for an office hour is friction with no information.\"\n      ],\n      \"pt\": [\n        \"Não ligue showSeconds só \\\"por precisão\\\": três rodas para um horário de expediente é fricção sem informação.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"A labelled textField; the icon opens the panel and is a labelled button. The panel's wheels are keyboard-navigable.\",\n      \"pt\": \"Campo textField rotulado; o ícone abre o painel e é botão rotulado. As rodas do painel são navegáveis por teclado.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_time_picker\",\n      \"app_date_time_picker_input\"\n    ]\n  },\n  {\n    \"id\": \"app_date_time_picker_input\",\n    \"name\": \"AppDateTimePickerInput\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Single date + time field: a DD/MM/YYYY HH:mm mask, with the calendar and the wheels in one panel.\",\n      \"pt\": \"Campo único de data + hora: máscara DD/MM/AAAA HH:mm, calendário e rodas no mesmo painel.\"\n    },\n    \"description\": {\n      \"en\": \"It exists for the instant that is ONE piece of data — the moment of an event, the scheduling of a command. Two separate fields let the form accept a date with no time, and then somebody picks a silent default (midnight) that nobody chose. Here the panel delivers the calendar and the wheels together, and the mask covers both at once.\",\n      \"pt\": \"Existe para o instante que é UM dado só — o momento de um evento, o agendamento de um comando. Dois campos separados deixam o formulário aceitar data sem hora, e aí alguém decide um default silencioso (meia-noite) que ninguém escolheu. Aqui o painel entrega calendário e rodas juntos, e a máscara cobre os dois de uma vez.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"The exact moment of an event (scheduling, a report cutoff).\",\n        \"A period filter with minute precision.\"\n      ],\n      \"pt\": [\n        \"Momento exato de um evento (agendamento, corte de relatório).\",\n        \"Filtro de período com precisão de minutos.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Only the date matters → AppDatePickerInput (do not ask for a time for nothing).\",\n        \"A range of days → AppDateRangePicker.\"\n      ],\n      \"pt\": [\n        \"Só a data importa → AppDatePickerInput (não peça hora à toa).\",\n        \"Intervalo de dias → AppDateRangePicker.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"onDateTimeSelected\",\n        \"type\": \"ValueChanged<DateTime>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"initialDateTime\",\n        \"type\": \"DateTime?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"firstDate\",\n        \"type\": \"DateTime?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"lastDate\",\n        \"type\": \"DateTime?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"label\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"hintText\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"helperText\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"errorText\",\n        \"type\": \"String?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Replaces the helper on the same line (the form does not jump).\",\n          \"pt\": \"Substitui o helper na mesma linha (o form não salta).\"\n        }\n      },\n      {\n        \"name\": \"hasError\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\",\n        \"description\": {\n          \"en\": \"The frame only, for when the message lives somewhere else.\",\n          \"pt\": \"Só a moldura, para quando a mensagem está em outro lugar.\"\n        }\n      },\n      {\n        \"name\": \"enabled\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"info\",\n        \"type\": \"Widget?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Help in a popover beside the label.\",\n          \"pt\": \"Ajuda em popover ao lado do rótulo.\"\n        }\n      },\n      {\n        \"name\": \"size\",\n        \"type\": \"AppFieldSize\",\n        \"required\": false,\n        \"default\": \"AppFieldSize.m\",\n        \"enumValues\": [\n          \"s\",\n          \"m\",\n          \"l\"\n        ]\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppStyle?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"radiusMode\",\n        \"type\": \"AppRadiusMode?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"radius\",\n        \"type\": \"BorderRadius?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"empty\",\n      \"filled\",\n      \"error\",\n      \"disabled\",\n      \"open\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Scheduling a command\",\n          \"pt\": \"Agendar um comando\"\n        },\n        \"code\": \"AppDateTimePickerInput(\\n  label: 'Executar em',\\n  hintText: 'DD/MM/AAAA HH:mm',\\n  firstDate: DateTime.now(),\\n  onDateTimeSelected: form.setScheduledAt,\\n)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use it when the date and the time are one piece of data.\"\n      ],\n      \"pt\": [\n        \"Use quando data e hora formam um dado só.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not replace two independent fields with this one: if one can exist without the other, they are two pieces of data.\"\n      ],\n      \"pt\": [\n        \"Não substitua dois campos independentes por este: se um pode existir sem o outro, são dois dados.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"A labelled textField with the full format in the hint; the panel combines the calendar and the wheels into a single keyboard-navigable node.\",\n      \"pt\": \"Campo textField rotulado com o formato completo no hint; o painel combina calendário e rodas num só nó navegável por teclado.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_date_picker_input\",\n      \"app_time_picker_input\"\n    ]\n  },\n  {\n    \"id\": \"app_date_picker\",\n    \"name\": \"AppDatePicker\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Single-date calendar: a day grid, month navigation and a direct jump to year/month.\",\n      \"pt\": \"Calendário de data única: grade de dias, navegação por mês e salto direto para ano/mês.\"\n    },\n    \"description\": {\n      \"en\": \"The bare calendar — no field, no overlay. Whoever mounts the panel decides where it lives (AppDatePickerInput opens it anchored; a scheduling screen keeps it fixed). Clicking the header label swaps the day grid for the year/month grid: without that, picking a date of birth costs dozens of taps on the chevron. `markToday` is opt-in because \\\"today\\\" only helps when the chosen date is near today — in a historical calendar it becomes noise; and `today` is injectable so the test does not depend on the clock.\",\n      \"pt\": \"O calendário nu — sem campo, sem overlay. Quem monta o painel decide onde ele vive (o AppDatePickerInput o abre ancorado; uma tela de agenda o deixa fixo). Clicar no rótulo do cabeçalho troca a grade de dias pela de ano/mês: sem isso, escolher uma data de nascimento custa dezenas de toques no chevron. `markToday` é opt-in porque o \\\"hoje\\\" só ajuda quando a data escolhida é perto de hoje — num calendário de histórico ele vira ruído; e `today` é injetável para o teste não depender do relógio.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"A calendar kept visible on a screen (scheduling, a report).\",\n        \"The panel of a hand-assembled date field.\"\n      ],\n      \"pt\": [\n        \"Calendário sempre visível numa tela (agenda, relatório).\",\n        \"Painel de um campo de data montado à mão.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A form field → AppDatePickerInput (it brings the mask and validation).\",\n        \"A from/to range → AppDateRangePicker.\"\n      ],\n      \"pt\": [\n        \"Campo de formulário → AppDatePickerInput (traz máscara e validação).\",\n        \"Intervalo de/até → AppDateRangePicker.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"initialDate\",\n        \"type\": \"DateTime\",\n        \"required\": true\n      },\n      {\n        \"name\": \"onDateSelected\",\n        \"type\": \"ValueChanged<DateTime>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"firstDate\",\n        \"type\": \"DateTime?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Earlier days are disabled, not hidden.\",\n          \"pt\": \"Dias anteriores ficam desabilitados, não escondidos.\"\n        }\n      },\n      {\n        \"name\": \"lastDate\",\n        \"type\": \"DateTime?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"markToday\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\",\n        \"description\": {\n          \"en\": \"Highlights today. Opt-in.\",\n          \"pt\": \"Realça o dia de hoje. Opt-in.\"\n        }\n      },\n      {\n        \"name\": \"today\",\n        \"type\": \"DateTime?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Injects \\\"today\\\" — it is what makes the component testable.\",\n          \"pt\": \"Injeta \\\"hoje\\\" — é o que torna o componente testável.\"\n        }\n      }\n    ],\n    \"states\": [\n      \"day-selected\",\n      \"today\",\n      \"out-of-range (disabled)\",\n      \"hover\",\n      \"year-month-grid\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Calendar fixed on a screen\",\n          \"pt\": \"Calendário fixo numa tela\"\n        },\n        \"code\": \"AppDatePicker(\\n  initialDate: DateTime.now(),\\n  markToday: true,\\n  onDateSelected: controller.select,\\n)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Inject `today` in tests instead of depending on the machine's clock.\"\n      ],\n      \"pt\": [\n        \"Injete `today` nos testes em vez de depender do relógio da máquina.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not hide days outside the range: disabled ones keep the grid stable.\"\n      ],\n      \"pt\": [\n        \"Não esconda dias fora do intervalo: desabilitados mantêm a grade estável.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Each day is a button labelled with the date spelled out; disabled ones announce the state instead of disappearing. The header is a button (it opens the year/month grid), not decorative text.\",\n      \"pt\": \"Cada dia é um botão rotulado com a data por extenso; os desabilitados anunciam o estado em vez de sumirem. O cabeçalho é botão (abre a grade de ano/mês), não texto decorativo.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_date_range_picker\",\n      \"app_date_picker_input\"\n    ]\n  },\n  {\n    \"id\": \"app_date_range_picker\",\n    \"name\": \"AppDateRangePicker\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Range calendar: one tap for the start, another for the end.\",\n      \"pt\": \"Calendário de intervalo: um toque no início, outro no fim.\"\n    },\n    \"description\": {\n      \"en\": \"A single month, navigated with the arrows. The range is drawn as a CONTINUOUS band behind the days — half a cell on the first and the last, a whole cell in between — so the selection reads as a stretch and not as a collection of marked days. While only the start is chosen, hover previews the band up to the day under the cursor: it is the answer to \\\"how long does this cover?\\\" before the second tap.\",\n      \"pt\": \"Mês único, navegável pelas setas. O intervalo é desenhado como uma banda CONTÍNUA por trás dos dias — meia célula no primeiro e no último, célula inteira no meio — para a seleção ler como uma faixa e não como uma coleção de dias marcados. Enquanto só há início escolhido, o hover pré-visualiza a banda até o dia sob o cursor: é a resposta à pergunta \\\"quanto tempo isso pega?\\\" antes do segundo toque.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"The period of a report or a filter (from/to).\",\n        \"A validity window.\"\n      ],\n      \"pt\": [\n        \"Período de um relatório ou filtro (de/até).\",\n        \"Janela de vigência.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A single date → AppDatePicker.\",\n        \"A period with a time → two AppDateTimePickerInputs.\"\n      ],\n      \"pt\": [\n        \"Data única → AppDatePicker.\",\n        \"Período com hora → dois AppDateTimePickerInput.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"onRangeSelected\",\n        \"type\": \"ValueChanged<AppDateRange>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"initialRange\",\n        \"type\": \"AppDateRange?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"firstDate\",\n        \"type\": \"DateTime?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"lastDate\",\n        \"type\": \"DateTime?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"markToday\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      },\n      {\n        \"name\": \"today\",\n        \"type\": \"DateTime?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Injects \\\"today\\\" — it is what makes the component testable.\",\n          \"pt\": \"Injeta \\\"hoje\\\" — é o que torna o componente testável.\"\n        }\n      }\n    ],\n    \"states\": [\n      \"nothing-picked\",\n      \"start-only\",\n      \"hover-preview\",\n      \"range-closed\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Period of a report\",\n          \"pt\": \"Período de um relatório\"\n        },\n        \"code\": \"AppDateRangePicker(\\n  lastDate: DateTime.now(),\\n  onRangeSelected: filters.setPeriod,\\n)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Bound it with lastDate when the future makes no sense.\"\n      ],\n      \"pt\": [\n        \"Limite com lastDate quando o futuro não faz sentido.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not demand an order: tapping the end before the start should swap them, not error.\"\n      ],\n      \"pt\": [\n        \"Não exija ordem: tocar no fim antes do início deve inverter, não errar.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Each day is a labelled button; the day that opens and the one that closes the range announce their role, so the stretch does not depend on background color alone.\",\n      \"pt\": \"Cada dia é botão rotulado; o dia que abre e o que fecha o intervalo anunciam o papel, para a faixa não depender só da cor de fundo.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_date_picker\"\n    ]\n  },\n  {\n    \"id\": \"app_time_picker\",\n    \"name\": \"AppTimePicker\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Hour/minute (and second) wheels in 24h format, with finite scrolling.\",\n      \"pt\": \"Rodas de hora/minuto (e segundo) em formato 24h, com scroll finito.\"\n    },\n    \"description\": {\n      \"en\": \"The bare time panel — no field, no overlay. The wheels are FINITE, not circular: the list stops at 00 and at 23, so the user feels where the ends are instead of spinning forever looking for the beginning. Always 24h, because the product is operational (shift rosters, service windows) and AM/PM introduces a 12-hour error that goes unnoticed. Values below the minimum appear DISABLED, not gone: the wheel keeps the same height and the user sees that a limit exists, instead of thinking the list starts there.\",\n      \"pt\": \"O painel de horário nu — sem campo, sem overlay. As rodas são FINITAS, não circulares: a lista para em 00 e em 23, então o usuário sente onde estão os extremos em vez de girar sem fim procurando o começo. Formato 24h sempre, porque o produto é operacional (escala, janela de atendimento) e AM/PM introduz um erro de 12 horas que passa despercebido. Valores abaixo do mínimo aparecem DESABILITADOS, não sumidos: a roda mantém a mesma altura e o usuário vê que existe um limite, em vez de achar que a lista começa ali.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"A hand-assembled time panel (AppTimePickerInput uses this one underneath).\",\n        \"Time selection kept visible on a screen.\"\n      ],\n      \"pt\": [\n        \"Painel de horário montado à mão (o AppTimePickerInput usa este por baixo).\",\n        \"Seleção de hora sempre visível numa tela.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A form field → AppTimePickerInput (it brings the mask and typing).\",\n        \"A duration (2h30) → a numeric field; this is a time of day.\"\n      ],\n      \"pt\": [\n        \"Campo de formulário → AppTimePickerInput (traz máscara e digitação).\",\n        \"Duração (2h30) → campo numérico; isto é hora do dia.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"onTimeSelected\",\n        \"type\": \"ValueChanged<({int hour, int minute, int second})>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"initialHour\",\n        \"type\": \"int\",\n        \"required\": false,\n        \"default\": \"0\"\n      },\n      {\n        \"name\": \"initialMinute\",\n        \"type\": \"int\",\n        \"required\": false,\n        \"default\": \"0\"\n      },\n      {\n        \"name\": \"initialSecond\",\n        \"type\": \"int\",\n        \"required\": false,\n        \"default\": \"0\"\n      },\n      {\n        \"name\": \"minHour\",\n        \"type\": \"int\",\n        \"required\": false,\n        \"default\": \"0\",\n        \"description\": {\n          \"en\": \"Floor; values below it are disabled.\",\n          \"pt\": \"Piso; abaixo dele os valores ficam desabilitados.\"\n        }\n      },\n      {\n        \"name\": \"minMinute\",\n        \"type\": \"int\",\n        \"required\": false,\n        \"default\": \"0\"\n      },\n      {\n        \"name\": \"minSecond\",\n        \"type\": \"int\",\n        \"required\": false,\n        \"default\": \"0\"\n      },\n      {\n        \"name\": \"showSeconds\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\",\n        \"description\": {\n          \"en\": \"Adds the third wheel.\",\n          \"pt\": \"Acrescenta a terceira roda.\"\n        }\n      }\n    ],\n    \"states\": [\n      \"item-selected\",\n      \"adjacent-items\",\n      \"below-min (disabled)\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Time panel\",\n          \"pt\": \"Painel de horário\"\n        },\n        \"code\": \"AppTimePicker(\\n  initialHour: 8,\\n  onTimeSelected: (({int hour, int minute, int second}) t) =>\\n      form.setTime(t.hour, t.minute),\\n)\"\n      },\n      {\n        \"title\": {\n          \"en\": \"The end time cannot precede the start\",\n          \"pt\": \"Hora final não pode ser antes da inicial\"\n        },\n        \"code\": \"AppTimePicker(\\n  minHour: start.hour,\\n  minMinute: start.minute,\\n  onTimeSelected: form.setEnd,\\n)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use the floors to tie the end time to the start instead of validating afterwards.\"\n      ],\n      \"pt\": [\n        \"Use os pisos para amarrar a hora final à inicial em vez de validar depois.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not turn showSeconds on \\\"for precision\\\": three wheels for an office hour is friction with no information.\"\n      ],\n      \"pt\": [\n        \"Não ligue showSeconds \\\"por precisão\\\": três rodas para um horário de expediente é fricção sem informação.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Each wheel is a keyboard-navigable list whose current value is announced on change; disabled ones announce the state instead of disappearing, so the limit is perceivable without seeing the color.\",\n      \"pt\": \"Cada roda é uma lista navegável por teclado, com o valor corrente anunciado ao mudar; os desabilitados anunciam o estado em vez de sumirem, para o limite ser perceptível sem enxergar a cor.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_time_picker_input\",\n      \"app_date_time_picker_input\"\n    ]\n  },\n  {\n    \"id\": \"app_color_picker_input\",\n    \"name\": \"AppColorPickerInput\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Color field: a painted swatch + an editable hex, with the HSV panel in an overlay.\",\n      \"pt\": \"Campo de cor: amostra pintada + hex editável, com o painel HSV num overlay.\"\n    },\n    \"description\": {\n      \"en\": \"Three ways of saying the same color, because people arrive by different routes: pasting the hex from a brand guide, picking a preset, or hunting through the spectrum. The field ALWAYS emits the normalized hex '#RRGGBB' (or '' when cleared), ready to persist — the consumer never receives `#abc`, `abc` or `#AABBCCDD` to normalize later. The swatch sits in the prefix, not the suffix: it is the field's value, not an action.\",\n      \"pt\": \"Três formas de dizer a mesma cor, porque quem usa chega por caminhos diferentes: colar o hex da identidade visual, pegar um preset, ou caçar no espectro. O campo emite SEMPRE o hex normalizado '#RRGGBB' (ou '' quando esvaziado), pronto para persistir — o consumidor nunca recebe `#abc`, `abc` ou `#AABBCCDD` para normalizar depois. A amostra fica no prefixo, não no sufixo: é o valor do campo, não uma ação.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"The color of a product entity (group, geofence, category).\",\n        \"Any form where the color is data, not decoration.\"\n      ],\n      \"pt\": [\n        \"Cor de uma entidade do produto (grupo, geocerca, categoria).\",\n        \"Qualquer formulário em que a cor é dado, não decoração.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Choosing among a few fixed colors → AppDropdown with AppSwatch.\",\n        \"Showing a color without editing it → AppSwatch.\"\n      ],\n      \"pt\": [\n        \"Escolher entre poucas cores fixas → AppDropdown com AppSwatch.\",\n        \"Mostrar uma cor sem editar → AppSwatch.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"onChanged\",\n        \"type\": \"ValueChanged<String>\",\n        \"required\": true,\n        \"description\": {\n          \"en\": \"Receives the normalized hex '#RRGGBB', or '' if cleared.\",\n          \"pt\": \"Recebe o hex normalizado '#RRGGBB', ou '' se esvaziado.\"\n        }\n      },\n      {\n        \"name\": \"value\",\n        \"type\": \"String?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Current hex.\",\n          \"pt\": \"Hex atual.\"\n        }\n      },\n      {\n        \"name\": \"label\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"hintText\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"helperText\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"errorText\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"hasError\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      },\n      {\n        \"name\": \"enabled\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"info\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"fallbackColor\",\n        \"type\": \"Color?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"What the swatch paints while the hex is invalid/empty.\",\n          \"pt\": \"O que a amostra pinta enquanto o hex é inválido/vazio.\"\n        }\n      },\n      {\n        \"name\": \"shape\",\n        \"type\": \"AppSwatchShape\",\n        \"required\": false,\n        \"default\": \"AppSwatchShape.square\",\n        \"enumValues\": [\n          \"square\",\n          \"circle\"\n        ]\n      },\n      {\n        \"name\": \"presets\",\n        \"type\": \"List<Color>?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Replaces the suggested palette.\",\n          \"pt\": \"Substitui a paleta sugerida.\"\n        }\n      },\n      {\n        \"name\": \"showSuggestedColors\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"size\",\n        \"type\": \"AppFieldSize\",\n        \"required\": false,\n        \"default\": \"AppFieldSize.m\",\n        \"enumValues\": [\n          \"s\",\n          \"m\",\n          \"l\"\n        ]\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppStyle?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"radiusMode\",\n        \"type\": \"AppRadiusMode?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"radius\",\n        \"type\": \"BorderRadius?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"empty\",\n      \"valid-hex\",\n      \"invalid-hex (error)\",\n      \"disabled\",\n      \"panel-open\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Color for a client group\",\n          \"pt\": \"Cor de um grupo de clientes\"\n        },\n        \"code\": \"AppColorPickerInput(\\n  label: 'Cor',\\n  value: group.colorHex,\\n  onChanged: (String hex) => form.setColor(hex),\\n)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Pass presets when the domain's palette is fixed (map categories).\"\n      ],\n      \"pt\": [\n        \"Passe presets quando a paleta do domínio for fixa (categorias de mapa).\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not normalize the hex again on the outside: it already arrives canonical.\"\n      ],\n      \"pt\": [\n        \"Não normalize o hex de novo do lado de fora: ele já chega canônico.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"The field is a textField with the hex as its content — color is never the ONLY channel: the textual value always accompanies the swatch. The panel's trigger is a labelled button.\",\n      \"pt\": \"O campo é textField com o hex como conteúdo — a cor nunca é o ÚNICO canal: o valor textual sempre acompanha a amostra. O gatilho do painel é botão rotulado.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_color_picker_panel\",\n      \"app_swatch\",\n      \"app_input\"\n    ]\n  },\n  {\n    \"id\": \"app_color_picker_panel\",\n    \"name\": \"AppColorPickerPanel\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Visual HSV picker: a saturation/value area, a hue bar and presets.\",\n      \"pt\": \"Seletor visual HSV: área de saturação/valor, barra de matiz e presets.\"\n    },\n    \"description\": {\n      \"en\": \"The bare panel, with no field and no overlay — AppColorPickerInput opens it anchored, but it serves anywhere that needs a visual color choice. The literal colors here (the hue spectrum, the gradient stops) are NOT an exception to the token rule: they are the color space itself. Tokenizing the spectrum's pure red would deform the tool, which exists precisely to navigate outside the palette.\",\n      \"pt\": \"O painel nu, sem campo nem overlay — o AppColorPickerInput o abre ancorado, mas ele serve a qualquer lugar que precise de escolha visual de cor. As cores literais aqui (o espectro de matiz, os stops do gradiente) NÃO são exceção à regra de tokens: são o espaço de cor em si. Tokenizar o vermelho puro do espectro deformaria a ferramenta, que existe justamente para navegar fora da paleta.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Free color choice kept visible on a screen.\",\n        \"The panel of a hand-assembled color field.\"\n      ],\n      \"pt\": [\n        \"Escolha livre de cor sempre visível numa tela.\",\n        \"Painel de um campo de cor montado à mão.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A form → AppColorPickerInput (it brings the hex, validation and normalization).\",\n        \"A small fixed palette → a row of AppSwatch.\"\n      ],\n      \"pt\": [\n        \"Formulário → AppColorPickerInput (traz hex, validação e normalização).\",\n        \"Paleta pequena e fixa → uma fileira de AppSwatch.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"color\",\n        \"type\": \"Color\",\n        \"required\": true\n      },\n      {\n        \"name\": \"onColorChanged\",\n        \"type\": \"ValueChanged<Color>\",\n        \"required\": true,\n        \"description\": {\n          \"en\": \"Emits continuously while the user drags.\",\n          \"pt\": \"Emite continuamente enquanto o usuário arrasta.\"\n        }\n      },\n      {\n        \"name\": \"presets\",\n        \"type\": \"List<Color>?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Replaces the suggested palette (distinguishable map colors).\",\n          \"pt\": \"Substitui a paleta sugerida (cores de mapa distinguíveis).\"\n        }\n      },\n      {\n        \"name\": \"showSuggestedColors\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      }\n    ],\n    \"states\": [\n      \"dragging-in-area\",\n      \"dragging-hue\",\n      \"preset-active\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Fixed panel\",\n          \"pt\": \"Painel fixo\"\n        },\n        \"code\": \"AppColorPickerPanel(\\n  color: current,\\n  onColorChanged: (Color c) => setState(() => current = c),\\n)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use domain presets when the colors have to be distinguishable from each other (map categories).\"\n      ],\n      \"pt\": [\n        \"Use presets do domínio quando as cores precisam ser distinguíveis entre si (categorias no mapa).\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not treat onColorChanged as confirmation: it fires while the user drags.\"\n      ],\n      \"pt\": [\n        \"Não trate onColorChanged como confirmação: ele dispara durante o arraste.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"The saturation/value area and the hue bar respond to the keyboard; the presets are buttons labelled with the hex, so the choice does not depend on seeing the difference between two near-identical tones.\",\n      \"pt\": \"A área de saturação/valor e a barra de matiz respondem a teclado; os presets são botões rotulados com o hex, para a escolha não depender só de enxergar a diferença entre dois tons próximos.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_color_picker_input\",\n      \"app_swatch\"\n    ]\n  },\n  {\n    \"id\": \"app_multi_select\",\n    \"name\": \"AppMultiSelect\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Multi-selection dropdown (chips + ✓).\",\n      \"pt\": \"Dropdown de seleção múltipla (chips + ✓).\"\n    },\n    \"description\": {\n      \"en\": \"A trigger with chips for the selected items; the overlay marks them with ✓ and does not close on selection. Reuses the dropdown core; colors 100% from the theme.\",\n      \"pt\": \"Trigger com chips dos selecionados; o overlay marca com ✓ e não fecha ao selecionar. Reusa o core de dropdown; cores 100% do tema.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Selecting several options among a few or a moderate number.\"\n      ],\n      \"pt\": [\n        \"Selecionar várias opções entre poucas/médias.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Many options → AppSearchableMultiSelect.\",\n        \"Single selection → AppDropdown.\"\n      ],\n      \"pt\": [\n        \"Muitas opções → AppSearchableMultiSelect.\",\n        \"Seleção única → AppDropdown.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"options\",\n        \"type\": \"List<AppDropdownOption<T>>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"onChanged\",\n        \"type\": \"ValueChanged<List<T>>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"selectedValues\",\n        \"type\": \"List<T>\",\n        \"required\": false,\n        \"default\": \"const []\"\n      },\n      {\n        \"name\": \"label\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"info\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"hintText\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"helperText\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"errorText\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"hasError\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      },\n      {\n        \"name\": \"enabled\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      }\n    ],\n    \"states\": [\n      \"closed\",\n      \"open\",\n      \"focused\",\n      \"error\",\n      \"disabled\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Multiple\",\n          \"pt\": \"Múltiplo\"\n        },\n        \"code\": \"AppMultiSelect<String>(options: opts, selectedValues: vs, onChanged: set)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Remove a chip with the ✕; select in the overlay without it closing.\"\n      ],\n      \"pt\": [\n        \"Remova um chip pelo ✕; selecione no overlay sem fechar.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it for many options without search.\"\n      ],\n      \"pt\": [\n        \"Não use para muitas opções sem busca.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Focusable trigger; chips at AA contrast; accents in a legible stop.\",\n      \"pt\": \"Trigger focável; chips com contraste AA; acentos em stop legível.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_dropdown\",\n      \"app_searchable_multi_select\"\n    ]\n  },\n  {\n    \"id\": \"app_searchable_dropdown\",\n    \"name\": \"AppSearchableDropdown\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Single-selection dropdown with a search field.\",\n      \"pt\": \"Dropdown de seleção única com campo de busca.\"\n    },\n    \"description\": {\n      \"en\": \"Like AppDropdown, with a filter field at the top of the overlay (focused automatically when it opens). The search field uses EditableText (a simple filter, not a full form field). Reuses the dropdown core.\",\n      \"pt\": \"Como AppDropdown, com um campo de filtro no topo do overlay (foco automático ao abrir). O campo de busca usa EditableText (filtro simples, não um campo de formulário completo). Reusa o core de dropdown.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Choosing one option among many (a long list).\"\n      ],\n      \"pt\": [\n        \"Escolher uma opção entre muitas (lista longa).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Few options → AppDropdown.\",\n        \"Several selections → AppSearchableMultiSelect.\"\n      ],\n      \"pt\": [\n        \"Poucas opções → AppDropdown.\",\n        \"Várias seleções → AppSearchableMultiSelect.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"options\",\n        \"type\": \"List<AppDropdownOption<T>>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"onChanged\",\n        \"type\": \"ValueChanged<T?>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"selectedValue\",\n        \"type\": \"T?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"searchHintText\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"label\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"info\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"hintText\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"helperText\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"errorText\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"hasError\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      },\n      {\n        \"name\": \"enabled\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      }\n    ],\n    \"states\": [\n      \"closed\",\n      \"open\",\n      \"searching\",\n      \"focused\",\n      \"error\",\n      \"disabled\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"With search\",\n          \"pt\": \"Com busca\"\n        },\n        \"code\": \"AppSearchableDropdown<String>(options: opts, searchHintText: 'Buscar…', onChanged: set)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use it for long lists; offer a searchHintText.\"\n      ],\n      \"pt\": [\n        \"Use para listas longas; ofereça searchHintText.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it for 2–3 options.\"\n      ],\n      \"pt\": [\n        \"Não use para 2–3 opções.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Search takes focus when it opens; options at AA contrast; a legible accent.\",\n      \"pt\": \"Busca ganha foco ao abrir; opções com contraste AA; acento legível.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_dropdown\",\n      \"app_searchable_multi_select\"\n    ]\n  },\n  {\n    \"id\": \"app_searchable_multi_select\",\n    \"name\": \"AppSearchableMultiSelect\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Multi-selection with chips and a search field.\",\n      \"pt\": \"Seleção múltipla com chips e campo de busca.\"\n    },\n    \"description\": {\n      \"en\": \"Like AppMultiSelect, with a filter field at the top of the overlay (focused automatically when it opens); selecting does not close it. Reuses the dropdown core.\",\n      \"pt\": \"Como AppMultiSelect, com um campo de filtro no topo do overlay (foco automático ao abrir); selecionar não fecha. Reusa o core de dropdown.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Selecting several options among many (a long list).\"\n      ],\n      \"pt\": [\n        \"Selecionar várias opções entre muitas (lista longa).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Few options → AppMultiSelect.\",\n        \"Single selection → AppSearchableDropdown.\"\n      ],\n      \"pt\": [\n        \"Poucas opções → AppMultiSelect.\",\n        \"Seleção única → AppSearchableDropdown.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"options\",\n        \"type\": \"List<AppDropdownOption<T>>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"onChanged\",\n        \"type\": \"ValueChanged<List<T>>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"selectedValues\",\n        \"type\": \"List<T>\",\n        \"required\": false,\n        \"default\": \"const []\"\n      },\n      {\n        \"name\": \"searchHintText\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"label\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"info\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"hintText\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"helperText\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"errorText\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"hasError\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      },\n      {\n        \"name\": \"enabled\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      }\n    ],\n    \"states\": [\n      \"closed\",\n      \"open\",\n      \"searching\",\n      \"focused\",\n      \"error\",\n      \"disabled\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Multiple with search\",\n          \"pt\": \"Múltiplo com busca\"\n        },\n        \"code\": \"AppSearchableMultiSelect<String>(options: opts, selectedValues: vs, onChanged: set)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use it for long lists with multiple selection.\"\n      ],\n      \"pt\": [\n        \"Use para listas longas com seleção múltipla.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it for a handful of options.\"\n      ],\n      \"pt\": [\n        \"Não use para poucas opções.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Search takes focus when it opens; chips and options at AA contrast.\",\n      \"pt\": \"Busca ganha foco ao abrir; chips e opções com contraste AA.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_multi_select\",\n      \"app_searchable_dropdown\"\n    ]\n  },\n  {\n    \"id\": \"app_pie_chart\",\n    \"name\": \"AppPieChart\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Pie chart (distribution in slices).\",\n      \"pt\": \"Gráfico de pizza (distribuição em fatias).\"\n    },\n    \"description\": {\n      \"en\": \"Slices proportional to the values; colors from the theme's categorical palette (chartCategorical) when not given. Hover/tap shows a tooltip and emits a selection. Tooltip with surfaceContainer + outline.\",\n      \"pt\": \"Fatias proporcionais aos valores; cores da paleta categórica do tema (chartCategorical) quando não dadas. Hover/tap mostra tooltip e emite seleção. Tooltip com surfaceContainer + outline.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Showing the composition of a whole (proportions).\"\n      ],\n      \"pt\": [\n        \"Mostrar a composição de um todo (proporções).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Comparing categories precisely → AppBarChart.\",\n        \"With a hole in the center → AppDonutChart.\"\n      ],\n      \"pt\": [\n        \"Comparar categorias com precisão → AppBarChart.\",\n        \"Com furo central → AppDonutChart.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"segments\",\n        \"type\": \"List<AppPieChartSegment>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"onSelectionChanged\",\n        \"type\": \"void Function(AppPieChartSelection)?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"valueFormatter\",\n        \"type\": \"AppChartValueFormatter?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"default\",\n      \"selected\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Pie\",\n          \"pt\": \"Pizza\"\n        },\n        \"code\": \"AppPieChart(segments: [AppPieChartSegment(label: \\\"A\\\", value: 30), AppPieChartSegment(label: \\\"B\\\", value: 70)])\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use few slices (≤ ~6) to keep it readable.\"\n      ],\n      \"pt\": [\n        \"Use poucas fatias (≤ ~6) para leitura clara.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it with many categories.\"\n      ],\n      \"pt\": [\n        \"Não use com muitas categorias.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"The semantic label aggregates the values; colors from the data-viz palette (the categorical one is decorative — the distinction comes from the legend/label).\",\n      \"pt\": \"Rótulo semântico agrega os valores; cores da paleta data-viz (categórica é decorativa — distinção por legenda/rótulo).\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_donut_chart\",\n      \"app_bar_chart\"\n    ]\n  },\n  {\n    \"id\": \"app_donut_chart\",\n    \"name\": \"AppDonutChart\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Donut chart (a pie with a hole in the middle).\",\n      \"pt\": \"Gráfico de rosca (pizza com furo central).\"\n    },\n    \"description\": {\n      \"en\": \"Like the pie, with a central hole (innerRadiusFactor 0.58). Colors from the theme's categorical palette when not given; hover/tap shows a tooltip.\",\n      \"pt\": \"Como o pizza, com furo central (innerRadiusFactor 0.58). Cores da paleta categórica do tema quando não dadas; hover/tap mostra tooltip.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"The composition of a whole, leaving the center free.\"\n      ],\n      \"pt\": [\n        \"Composição de um todo, deixando o centro livre.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Comparing categories precisely → AppBarChart.\"\n      ],\n      \"pt\": [\n        \"Comparar categorias com precisão → AppBarChart.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"segments\",\n        \"type\": \"List<AppPieChartSegment>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"onSelectionChanged\",\n        \"type\": \"void Function(AppPieChartSelection)?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"valueFormatter\",\n        \"type\": \"AppChartValueFormatter?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"default\",\n      \"selected\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Donut\",\n          \"pt\": \"Rosca\"\n        },\n        \"code\": \"AppDonutChart(segments: [AppPieChartSegment(label: \\\"A\\\", value: 30), AppPieChartSegment(label: \\\"B\\\", value: 70)])\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use few slices; put a total in the center.\"\n      ],\n      \"pt\": [\n        \"Use poucas fatias; aproveite o centro para um total.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it with many categories.\"\n      ],\n      \"pt\": [\n        \"Não use com muitas categorias.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"The semantic label aggregates the values; data-viz palette.\",\n      \"pt\": \"Rótulo semântico agrega os valores; paleta data-viz.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_pie_chart\"\n    ]\n  },\n  {\n    \"id\": \"app_line_chart\",\n    \"name\": \"AppLineChart\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Line chart for a trend over time.\",\n      \"pt\": \"Gráfico de linha para tendência ao longo do tempo.\"\n    },\n    \"description\": {\n      \"en\": \"One polyline per series over cartesian axes. Hover/tap emits onSelectionChanged and shows the point's tooltip. Colors from the theme's categorical palette when not given.\",\n      \"pt\": \"Uma polilinha por série sobre eixos cartesianos. Hover/tap emite onSelectionChanged e mostra o tooltip do ponto. Cores da paleta categórica do tema quando não dadas.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"How a metric evolves over time.\"\n      ],\n      \"pt\": [\n        \"Evolução de uma métrica no tempo.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Comparing categories → AppBarChart.\"\n      ],\n      \"pt\": [\n        \"Comparar categorias → AppBarChart.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"series\",\n        \"type\": \"List<AppCartesianChartSeries>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"minY\",\n        \"type\": \"double\",\n        \"required\": false\n      },\n      {\n        \"name\": \"maxY\",\n        \"type\": \"double?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"showGrid\",\n        \"type\": \"bool\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onSelectionChanged\",\n        \"type\": \"void Function(AppCartesianChartSelection)?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"valueFormatter\",\n        \"type\": \"AppChartValueFormatter?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"default\",\n      \"selected\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Line\",\n          \"pt\": \"Linha\"\n        },\n        \"code\": \"AppLineChart(series: series)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Few series; label each one in the legend.\"\n      ],\n      \"pt\": [\n        \"Poucas séries; rotule cada uma na legenda.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it to compare close values across categories.\"\n      ],\n      \"pt\": [\n        \"Não use para comparar valores próximos entre categorias.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"The semantic label aggregates the series; color is never the only cue.\",\n      \"pt\": \"Rótulo semântico agrega a série; a cor nunca é a única pista.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_area_chart\",\n      \"app_bar_chart\"\n    ]\n  },\n  {\n    \"id\": \"app_area_chart\",\n    \"name\": \"AppAreaChart\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Area chart: a line with the space beneath it filled.\",\n      \"pt\": \"Gráfico de área: linha com o espaço abaixo preenchido.\"\n    },\n    \"description\": {\n      \"en\": \"Same geometry as the line, with the fill controlled by areaOpacity. Use it when accumulated volume matters as much as the trend.\",\n      \"pt\": \"Mesma geometria da linha, com preenchimento controlado por areaOpacity. Use quando o volume acumulado importa tanto quanto a tendência.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Accumulated volume over time.\"\n      ],\n      \"pt\": [\n        \"Volume acumulado ao longo do tempo.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Series that cross each other often → AppLineChart.\"\n      ],\n      \"pt\": [\n        \"Séries que se cruzam muito → AppLineChart.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"series\",\n        \"type\": \"List<AppCartesianChartSeries>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"areaOpacity\",\n        \"type\": \"double\",\n        \"required\": false\n      },\n      {\n        \"name\": \"minY\",\n        \"type\": \"double\",\n        \"required\": false\n      },\n      {\n        \"name\": \"maxY\",\n        \"type\": \"double?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"showGrid\",\n        \"type\": \"bool\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onSelectionChanged\",\n        \"type\": \"void Function(AppCartesianChartSelection)?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"valueFormatter\",\n        \"type\": \"AppChartValueFormatter?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"default\",\n      \"selected\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Area\",\n          \"pt\": \"Área\"\n        },\n        \"code\": \"AppAreaChart(series: series)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"One or two series; beyond that the fills overlap.\"\n      ],\n      \"pt\": [\n        \"Uma ou duas séries; mais que isso o preenchimento se sobrepõe.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not stack many translucent areas.\"\n      ],\n      \"pt\": [\n        \"Não empilhe muitas áreas translúcidas.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"The semantic label aggregates the series; color is never the only cue.\",\n      \"pt\": \"Rótulo semântico agrega a série; a cor nunca é a única pista.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_line_chart\"\n    ]\n  },\n  {\n    \"id\": \"app_bar_chart\",\n    \"name\": \"AppBarChart\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Bar chart, grouped or stacked.\",\n      \"pt\": \"Gráfico de barras, agrupado ou empilhado.\"\n    },\n    \"description\": {\n      \"en\": \"Vertical or horizontal, grouped or stacked. It is the comparison chart: values over a common baseline. Stacked, the joint stays square and only the outer end rounds — the corner comes from the brand's shape axis.\",\n      \"pt\": \"Vertical ou horizontal, agrupado ou empilhado. É o gráfico de comparação: valores sobre uma linha de base comum. Empilhado, a junta fica reta e só a ponta de fora arredonda — o canto sai do eixo de forma da marca.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Comparing categories precisely.\"\n      ],\n      \"pt\": [\n        \"Comparar categorias com precisão.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A trend over time → AppLineChart.\",\n        \"The composition of a whole → AppPieChart.\"\n      ],\n      \"pt\": [\n        \"Tendência no tempo → AppLineChart.\",\n        \"Composição de um todo → AppPieChart.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"labels\",\n        \"type\": \"List<String>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"series\",\n        \"type\": \"List<AppBarChartSeries>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"layout\",\n        \"type\": \"AppBarChartLayout\",\n        \"required\": false\n      },\n      {\n        \"name\": \"orientation\",\n        \"type\": \"AppBarChartOrientation\",\n        \"required\": false\n      },\n      {\n        \"name\": \"barThickness\",\n        \"type\": \"double?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"categorySpacing\",\n        \"type\": \"double?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"maxValue\",\n        \"type\": \"double?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"showGrid\",\n        \"type\": \"bool\",\n        \"required\": false\n      },\n      {\n        \"name\": \"enableInternalScroll\",\n        \"type\": \"bool\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onSelectionChanged\",\n        \"type\": \"void Function(AppBarChartSelection)?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"valueFormatter\",\n        \"type\": \"AppChartValueFormatter?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"default\",\n      \"selected\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Grouped bars\",\n          \"pt\": \"Barras agrupadas\"\n        },\n        \"code\": \"AppBarChart(labels: labels, series: series)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Start the axis at zero — a truncated bar lies about the comparison.\"\n      ],\n      \"pt\": [\n        \"Comece o eixo no zero — barra truncada mente na comparação.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use stacked bars to compare the segments in the middle.\"\n      ],\n      \"pt\": [\n        \"Não use empilhado para comparar segmentos do meio.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"The semantic label aggregates each series; the legend is keyboard-navigable.\",\n      \"pt\": \"Rótulo semântico agrega cada série; a legenda é navegável por teclado.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_line_chart\",\n      \"app_bubble_chart\"\n    ]\n  },\n  {\n    \"id\": \"app_bubble_chart\",\n    \"name\": \"AppBubbleChart\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Bubble chart: the circle's area is the value.\",\n      \"pt\": \"Gráfico de bolhas: a área do círculo é o valor.\"\n    },\n    \"description\": {\n      \"en\": \"Each node is a circle whose area represents the value. It serves orders of magnitude across a few categories, not precise comparison.\",\n      \"pt\": \"Cada nó é um círculo cuja área representa o valor. Serve para ordem de grandeza entre poucas categorias, não para comparação precisa.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Showing relative magnitude across a few categories.\"\n      ],\n      \"pt\": [\n        \"Mostrar magnitude relativa entre poucas categorias.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Comparing close values → AppBarChart.\"\n      ],\n      \"pt\": [\n        \"Comparar valores próximos → AppBarChart.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"nodes\",\n        \"type\": \"List<AppBubbleChartNode>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"onSelectionChanged\",\n        \"type\": \"void Function(AppBubbleChartSelection)?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"valueFormatter\",\n        \"type\": \"AppChartValueFormatter?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"default\",\n      \"selected\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Bubbles\",\n          \"pt\": \"Bolhas\"\n        },\n        \"code\": \"AppBubbleChart(nodes: nodes)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Few nodes, each with a visible label.\"\n      ],\n      \"pt\": [\n        \"Poucos nós, com rótulo visível.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not ask the reader to compare areas of similar size.\"\n      ],\n      \"pt\": [\n        \"Não peça ao leitor para comparar áreas parecidas.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Every bubble carries its own semantic label (label + value).\",\n      \"pt\": \"Cada bolha tem rótulo semântico próprio (label + valor).\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_bar_chart\"\n    ]\n  },\n  {\n    \"id\": \"app_gauge_chart\",\n    \"name\": \"AppGaugeChart\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Gauge: a segmented arc with a central label.\",\n      \"pt\": \"Medidor: arco segmentado com rótulo central.\"\n    },\n    \"description\": {\n      \"en\": \"For one indicator against a scale — occupancy, health, percentage of a target. variant chooses between a half arc and a full arc.\",\n      \"pt\": \"Para um indicador contra uma escala — ocupação, saúde, percentual de meta. variant escolhe entre meio-arco e arco completo.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"One indicator against a scale.\"\n      ],\n      \"pt\": [\n        \"Um indicador contra uma escala.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Several indicators side by side → AppBarChart.\"\n      ],\n      \"pt\": [\n        \"Vários indicadores lado a lado → AppBarChart.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"segments\",\n        \"type\": \"List<AppGaugeChartSegment>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"variant\",\n        \"type\": \"AppGaugeChartVariant\",\n        \"required\": false\n      },\n      {\n        \"name\": \"centerLabel\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"centerValueLabel\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onSelectionChanged\",\n        \"type\": \"void Function(AppGaugeChartSelection)?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"valueFormatter\",\n        \"type\": \"AppChartValueFormatter?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"default\",\n      \"selected\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Occupancy gauge\",\n          \"pt\": \"Medidor de ocupação\"\n        },\n        \"code\": \"AppGaugeChart(centerLabel: \\\"Ocupação\\\", segments: segments)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use the central label for the number that matters.\"\n      ],\n      \"pt\": [\n        \"Use o rótulo central para o número que importa.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not stack gauges to compare them.\"\n      ],\n      \"pt\": [\n        \"Não empilhe medidores para comparar.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"The central label is read together with the value; segments carry their own labels.\",\n      \"pt\": \"O rótulo central é lido junto do valor; segmentos têm rótulo próprio.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_bar_chart\",\n      \"app_donut_chart\"\n    ]\n  },\n  {\n    \"id\": \"app_chart_shell\",\n    \"name\": \"AppChartShell\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Chart frame: title, legend and states.\",\n      \"pt\": \"Moldura de gráfico: título, legenda e estados.\"\n    },\n    \"description\": {\n      \"en\": \"Title, subtitle, summary, legend and the loading and empty states around the plot area. It is a content card: it follows the global style (AppStyle) and shape axes, like AppCard.\",\n      \"pt\": \"Título, subtítulo, resumo, legenda e os estados de carregando e vazio em volta da área de plotagem. É um cartão de conteúdo: segue os eixos globais de estilo (AppStyle) e de forma, como o AppCard.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Giving a chart its chrome (title, legend, empty, loading).\"\n      ],\n      \"pt\": [\n        \"Dar cromo a um gráfico (título, legenda, vazio, carregando).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A bare chart inside a card that already has a title.\"\n      ],\n      \"pt\": [\n        \"Gráfico solto dentro de um card que já tem título.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"child\",\n        \"type\": \"Widget\",\n        \"required\": true\n      },\n      {\n        \"name\": \"title\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"subtitle\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"summary\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"legendItems\",\n        \"type\": \"List<AppChartLegendItem>\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onLegendTap\",\n        \"type\": \"void Function(AppChartLegendItem)?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"isEmpty\",\n        \"type\": \"bool\",\n        \"required\": false\n      },\n      {\n        \"name\": \"isLoading\",\n        \"type\": \"bool\",\n        \"required\": false\n      },\n      {\n        \"name\": \"emptyChild\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"expandChart\",\n        \"type\": \"bool\",\n        \"required\": false\n      },\n      {\n        \"name\": \"chartConstraints\",\n        \"type\": \"BoxConstraints\",\n        \"required\": false\n      },\n      {\n        \"name\": \"constraints\",\n        \"type\": \"BoxConstraints?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppStyle?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"default\",\n      \"loading\",\n      \"empty\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Frame with a title\",\n          \"pt\": \"Moldura com título\"\n        },\n        \"code\": \"AppChartShell(title: \\\"Consumo\\\", child: chart)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use the legend to name the series — color alone carries nothing.\"\n      ],\n      \"pt\": [\n        \"Use a legenda para nomear as séries — a cor sozinha não informa.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not repeat the card's title in the frame.\"\n      ],\n      \"pt\": [\n        \"Não repita o título do card na moldura.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Legend items are keyboard-navigable toggles whose state is announced.\",\n      \"pt\": \"Itens de legenda são toggles navegáveis por teclado, com estado anunciado.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_bar_chart\",\n      \"app_line_chart\"\n    ]\n  },\n  {\n    \"id\": \"app_expansion_tile\",\n    \"name\": \"AppExpansionTile\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Expandable tile: a clickable header + an animated body.\",\n      \"pt\": \"Tile expansível: cabeçalho clicável + corpo animado.\"\n    },\n    \"description\": {\n      \"en\": \"A header on FlocksInteraction (hover/press/focus/keyboard); the chevron rotates through AppAnimatedRotation and the body opens/closes through AppExpand — both driven by AppMotion (reduce-motion + the global toggle). Tooltip through AppTooltip. Colors from the theme; it takes part in the global style (filled/outlined/elevated) and shape (radius) axes, wrapping the whole card.\",\n      \"pt\": \"Cabeçalho sobre FlocksInteraction (hover/press/foco/teclado); o chevron gira via AppAnimatedRotation e o corpo abre/fecha via AppExpand — ambos por AppMotion (reduce-motion + toggle global). Tooltip via AppTooltip. Cores do tema; participa dos eixos globais de estilo (filled/outlined/elevated) e forma (radius), envolvendo o card inteiro.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"A collapsible section of content (details, FAQ, advanced filters).\"\n      ],\n      \"pt\": [\n        \"Seção colapsável de conteúdo (detalhes, FAQ, filtros avançados).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Navigation between sibling panels → tabs (organism).\",\n        \"A simple option row → AppListTile / AppActionItem.\"\n      ],\n      \"pt\": [\n        \"Navegação entre painéis irmãos → abas (organism).\",\n        \"Linha simples de opção → AppListTile / AppActionItem.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"title\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"children\",\n        \"type\": \"List<Widget>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"enabled\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"hoverEnabled\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"initiallyExpanded\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      },\n      {\n        \"name\": \"onExpansionChanged\",\n        \"type\": \"ValueChanged<bool>?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"collapsedIconTooltip\",\n        \"type\": \"String\",\n        \"required\": false,\n        \"default\": \"'Abrir'\"\n      },\n      {\n        \"name\": \"expandedIconTooltip\",\n        \"type\": \"String\",\n        \"required\": false,\n        \"default\": \"'Fechar'\"\n      }\n    ],\n    \"states\": [\n      \"collapsed\",\n      \"expanded\",\n      \"hovered\",\n      \"focused\",\n      \"disabled\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Collapsible section\",\n          \"pt\": \"Seção colapsável\"\n        },\n        \"code\": \"AppExpansionTile(title: 'Detalhes', children: [AppText('...')])\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use it for secondary content that can stay hidden by default.\"\n      ],\n      \"pt\": [\n        \"Use para conteúdo secundário que pode ficar oculto por padrão.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not nest many levels — it becomes a maze.\"\n      ],\n      \"pt\": [\n        \"Não aninhe muitos níveis — vira labirinto.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"A header with a button role (AppSemantics.button); activation with Enter/Space; title and chevron in onSurface over the surface (an AA pair); disabled dimmed by tone.\",\n      \"pt\": \"Cabeçalho com role de botão (AppSemantics.button); ativação por Enter/Space; título/chevron em onSurface sobre a superfície (par AA); desabilitado apagado por tom.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_list_tile\",\n      \"app_action_item\"\n    ]\n  },\n  {\n    \"id\": \"app_simple_header\",\n    \"name\": \"AppSimpleHeader\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Simple page header (a band over the surface holding one child).\",\n      \"pt\": \"Cabeçalho simples de página (faixa sobre surface com um child).\"\n    },\n    \"description\": {\n      \"en\": \"A band over `surface` wrapping one child, adding the top safe area. Color from the theme; marked as a header (AppSemantics.header).\",\n      \"pt\": \"Faixa sobre `surface` que envolve um child, somando a safe-area do topo. Cor do tema; marcado como cabeçalho (AppSemantics.header).\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"The top of a page with free content (a title, and so on).\"\n      ],\n      \"pt\": [\n        \"Topo de uma página com um conteúdo livre (título etc.).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A header with leading/child/trailing → AppPrimaryHeader.\"\n      ],\n      \"pt\": [\n        \"Cabeçalho com leading/child/trailing → AppPrimaryHeader.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"child\",\n        \"type\": \"Widget\",\n        \"required\": true\n      },\n      {\n        \"name\": \"decoration\",\n        \"type\": \"BoxDecoration?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"constraints\",\n        \"type\": \"BoxConstraints?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"padding\",\n        \"type\": \"EdgeInsets?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"default\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Title\",\n          \"pt\": \"Título\"\n        },\n        \"code\": \"AppSimpleHeader(child: AppText('Título'))\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use it for a lean page top.\"\n      ],\n      \"pt\": [\n        \"Use para um topo de página enxuto.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not put many elements in it — use AppPrimaryHeader.\"\n      ],\n      \"pt\": [\n        \"Não coloque muitos elementos — use AppPrimaryHeader.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Marked as a header (AppSemantics.header); the content comes from the child.\",\n      \"pt\": \"Marcado como header (AppSemantics.header); conteúdo vem do child.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_primary_header\"\n    ]\n  },\n  {\n    \"id\": \"app_primary_header\",\n    \"name\": \"AppPrimaryHeader\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Primary header: a centered child + optional leading/trailing.\",\n      \"pt\": \"Cabeçalho primário: child central + leading/trailing opcionais.\"\n    },\n    \"description\": {\n      \"en\": \"A centered child with optional leading/trailing slots, over `surface`, adding the top safe area. Color from the theme; marked as a header (AppSemantics.header). The legacy `style` (dead code) was removed.\",\n      \"pt\": \"Child centralizado com slots opcionais de leading/trailing, sobre `surface`, somando a safe-area do topo. Cor do tema; marcado como cabeçalho (AppSemantics.header). O `style` legado (dead code) foi removido.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"The top of a page with a centered title and actions at the sides.\"\n      ],\n      \"pt\": [\n        \"Topo de página com título centralizado e ações laterais.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Just one child, with no slots → AppSimpleHeader.\"\n      ],\n      \"pt\": [\n        \"Só um child, sem slots → AppSimpleHeader.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"child\",\n        \"type\": \"Widget\",\n        \"required\": true\n      },\n      {\n        \"name\": \"leading\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"trailing\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"centerChild\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"decoration\",\n        \"type\": \"BoxDecoration?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"constraints\",\n        \"type\": \"BoxConstraints?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"padding\",\n        \"type\": \"EdgeInsets?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"default\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"With back\",\n          \"pt\": \"Com voltar\"\n        },\n        \"code\": \"AppPrimaryHeader(leading: AppIconButton(...), child: AppText('Detalhes'))\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use leading for navigation and trailing for one action.\"\n      ],\n      \"pt\": [\n        \"Use leading para navegação e trailing para uma ação.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not pile many items into the trailing.\"\n      ],\n      \"pt\": [\n        \"Não empilhe muitos itens no trailing.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Marked as a header; content and actions come from the slots.\",\n      \"pt\": \"Marcado como header; conteúdo/ações vêm dos slots.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_simple_header\",\n      \"app_interaction\"\n    ]\n  },\n  {\n    \"id\": \"app_buttons_footer\",\n    \"name\": \"AppButtonsFooter\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Action footer: a primary button + an optional secondary one.\",\n      \"pt\": \"Rodapé de ações: botão primário + secundário opcional.\"\n    },\n    \"description\": {\n      \"en\": \"Primary and secondary in a row (default) or a column, over the `platform` surface (desktop=surfaceContainer, mobile=surface); rounding by `style` with the global radius. The bottom safe area is added. Colors from the theme.\",\n      \"pt\": \"Primário e secundário em linha (default) ou coluna, sobre a superfície de `platform` (desktop=surfaceContainer, mobile=surface); arredondamento por `style` com o radius global. Safe-area inferior somada. Cores do tema.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"The footer of a form, dialog or sheet with 1–2 actions.\"\n      ],\n      \"pt\": [\n        \"Rodapé de formulário/dialog/sheet com 1–2 ações.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A bottom navigation bar → AppNavigationFooter.\"\n      ],\n      \"pt\": [\n        \"Barra de navegação inferior → AppNavigationFooter.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"primary\",\n        \"type\": \"Widget\",\n        \"required\": true\n      },\n      {\n        \"name\": \"secondary\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"axis\",\n        \"type\": \"Axis?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"alignment\",\n        \"type\": \"AppButtonsFooterAlignment?\",\n        \"required\": false,\n        \"enumValues\": [\n          \"start\",\n          \"center\",\n          \"end\"\n        ]\n      },\n      {\n        \"name\": \"platform\",\n        \"type\": \"AppButtonsPlatformStyle\",\n        \"required\": false,\n        \"default\": \"AppButtonsPlatformStyle.desktop\",\n        \"enumValues\": [\n          \"desktop\",\n          \"mobile\"\n        ]\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppButtonsFooterStyle\",\n        \"required\": false,\n        \"default\": \"AppButtonsFooterStyle.page\",\n        \"enumValues\": [\n          \"card\",\n          \"dialog\",\n          \"page\",\n          \"sheet\"\n        ]\n      },\n      {\n        \"name\": \"constraints\",\n        \"type\": \"BoxConstraints?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"decoration\",\n        \"type\": \"BoxDecoration?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"padding\",\n        \"type\": \"EdgeInsets?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"default\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Save/Cancel\",\n          \"pt\": \"Salvar/Cancelar\"\n        },\n        \"code\": \"AppButtonsFooter(primary: AppButton(...), secondary: AppButton(style: AppStyle.outlined, ...))\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"One primary action; the secondary one at lower emphasis.\"\n      ],\n      \"pt\": [\n        \"1 ação primária; secundária de menor ênfase.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not put more than 2 buttons in it.\"\n      ],\n      \"pt\": [\n        \"Não coloque mais de 2 botões.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"The actions inherit the semantics of the child buttons.\",\n      \"pt\": \"As ações herdam a semântica dos botões filhos.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_fill_button\",\n      \"app_line_button\",\n      \"app_simple_footer\"\n    ]\n  },\n  {\n    \"id\": \"app_simple_footer\",\n    \"name\": \"AppSimpleFooter\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Simple footer: a band over the surface holding one child.\",\n      \"pt\": \"Rodapé simples: faixa sobre surface com um child.\"\n    },\n    \"description\": {\n      \"en\": \"A band over `surface` wrapping one child, adding the bottom safe area. Color from the theme.\",\n      \"pt\": \"Faixa sobre `surface` que envolve um child, somando a safe-area inferior. Cor do tema.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"A free-form footer (copyright, a note, a total).\"\n      ],\n      \"pt\": [\n        \"Rodapé livre (copyright, uma nota, um total).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Primary actions → AppButtonsFooter.\",\n        \"Navigation → AppNavigationFooter.\"\n      ],\n      \"pt\": [\n        \"Ações primárias → AppButtonsFooter.\",\n        \"Navegação → AppNavigationFooter.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"child\",\n        \"type\": \"Widget\",\n        \"required\": true\n      },\n      {\n        \"name\": \"constraints\",\n        \"type\": \"BoxConstraints?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"decoration\",\n        \"type\": \"BoxDecoration?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"padding\",\n        \"type\": \"EdgeInsets?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"default\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Note\",\n          \"pt\": \"Nota\"\n        },\n        \"code\": \"AppSimpleFooter(child: AppText('© 2026'))\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use it for a lean footer.\"\n      ],\n      \"pt\": [\n        \"Use para um rodapé enxuto.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not put actions in it — use AppButtonsFooter.\"\n      ],\n      \"pt\": [\n        \"Não coloque ações — use AppButtonsFooter.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"The meaning comes from the child.\",\n      \"pt\": \"O significado vem do child.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_buttons_footer\"\n    ]\n  },\n  {\n    \"id\": \"app_navigation_footer\",\n    \"name\": \"AppNavigationFooter\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Bottom navigation bar (icon+title items).\",\n      \"pt\": \"Barra de navegação inferior (itens ícone+título).\"\n    },\n    \"description\": {\n      \"en\": \"Icon+title items; the current route's item is highlighted in a legible accent (`secondary`), the rest in a legible neutral. Each item sits on FlocksInteraction (hover/press/focus). Colors from the theme; radius and animation global.\",\n      \"pt\": \"Itens ícone+título; o item da rota atual é destacado num acento legível (`secondary`), os demais num neutro legível. Cada item sobre FlocksInteraction (hover/press/foco). Cores do tema; raio/animação globais.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Primary navigation on mobile (3–5 destinations).\"\n      ],\n      \"pt\": [\n        \"Navegação primária no mobile (3–5 destinos).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Form actions → AppButtonsFooter.\"\n      ],\n      \"pt\": [\n        \"Ações de formulário → AppButtonsFooter.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"items\",\n        \"type\": \"List<AppNavigationFooterItemData>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"getCurrentRoute\",\n        \"type\": \"String Function(BuildContext)\",\n        \"required\": true\n      },\n      {\n        \"name\": \"constraints\",\n        \"type\": \"BoxConstraints?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"decoration\",\n        \"type\": \"BoxDecoration?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"padding\",\n        \"type\": \"EdgeInsets?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"selected\",\n      \"unselected\",\n      \"hovered\",\n      \"focused\",\n      \"pressed\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Bottom bar\",\n          \"pt\": \"Barra inferior\"\n        },\n        \"code\": \"AppNavigationFooter(items: [...], getCurrentRoute: (c) => currentRoute)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"3–5 destinations; a short title.\"\n      ],\n      \"pt\": [\n        \"3–5 destinos; título curto.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it for many items — use a menu.\"\n      ],\n      \"pt\": [\n        \"Não use para muitos itens — use um menu.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Each item carries a button role; active/inactive colors are ≥ 3:1 against the surface (validated across 2 brands × 2 brightnesses).\",\n      \"pt\": \"Cada item com role de botão; ativo/inativo em cores ≥ 3:1 sobre a superfície (validado nas 2 marcas × 2 brilhos).\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_buttons_footer\"\n    ]\n  },\n  {\n    \"id\": \"app_search_footer\",\n    \"name\": \"AppSearchFooter\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Floating search footer (Notes style), with the AppStyle axis + glass.\",\n      \"pt\": \"Rodapé de busca flutuante (estilo Notes), com eixo AppStyle + glass.\"\n    },\n    \"description\": {\n      \"en\": \"A floating search capsule: a bare AppInput over an AppBarSurface (which carries the style), with the bottom safe area and an optional detached trailing (e.g. a compose FAB). Supports `glass` (blur + gradient).\",\n      \"pt\": \"Cápsula de busca flutuante: um AppInput cru sobre uma AppBarSurface (carrega o estilo), com a safe-area inferior e um trailing isolado opcional (ex.: um FAB de compor). Suporta `glass` (blur + gradiente).\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Search fixed at the bottom (lists, a map).\",\n        \"The iOS Notes scenario (a capsule + a compose button).\"\n      ],\n      \"pt\": [\n        \"Busca fixa no rodapé (listas, mapa).\",\n        \"Cenário estilo iOS Notes (cápsula + botão de compor).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Message/chat composition → AppChatFooter.\",\n        \"A filter inside a dropdown → AppSearchableDropdown.\"\n      ],\n      \"pt\": [\n        \"Composição de mensagens/chat → AppChatFooter.\",\n        \"Filtro dentro de um dropdown → AppSearchableDropdown.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"controller\",\n        \"type\": \"TextEditingController?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"focusNode\",\n        \"type\": \"FocusNode?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"hintText\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onChanged\",\n        \"type\": \"ValueChanged<String>?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onSubmitted\",\n        \"type\": \"ValueChanged<String>?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"prefixIcon\",\n        \"type\": \"String\",\n        \"required\": false\n      },\n      {\n        \"name\": \"suffixIcon\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onSuffixIconTap\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"trailing\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppStyle\",\n        \"required\": false\n      },\n      {\n        \"name\": \"radiusMode\",\n        \"type\": \"AppRadiusMode?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"size\",\n        \"type\": \"AppFieldSize\",\n        \"required\": false\n      },\n      {\n        \"name\": \"enabled\",\n        \"type\": \"bool\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"default\",\n      \"glass\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Search\",\n          \"pt\": \"Busca\"\n        },\n        \"code\": \"AppSearchFooter(controller: c, hintText: 'Buscar')\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use `glass` over scrollable content (the Notes effect).\"\n      ],\n      \"pt\": [\n        \"Use `glass` sobre conteúdo rolável (efeito Notes).\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it for chat — prefer AppChatFooter.\"\n      ],\n      \"pt\": [\n        \"Não use para chat — prefira AppChatFooter.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"A text field with a search action; labelled icons.\",\n      \"pt\": \"Campo de texto com ação de busca; ícones rotulados.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_chat_footer\",\n      \"app_navigation_footer\"\n    ]\n  },\n  {\n    \"id\": \"app_chat_footer\",\n    \"name\": \"AppChatFooter\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Chat footer: wraps AppChatComposer with a safe area + AppStyle.\",\n      \"pt\": \"Rodapé de chat: envolve o AppChatComposer com safe-area + AppStyle.\"\n    },\n    \"description\": {\n      \"en\": \"Wraps AppChatComposer, adding the bottom safe area (which the composer does not handle) and the bar style axes (AppStyle) + glass. The composer is forced to `filled` (an opaque pill) — the bar carries the style, which avoids double styling. Docked by default; `floating` detaches it.\",\n      \"pt\": \"Envolve o AppChatComposer adicionando a safe-area inferior (que o composer não trata) e os eixos de estilo de barra (AppStyle) + glass. O composer é forçado a `filled` (pílula opaca) — a barra carrega o estilo, evitando duplo-styling. Docked por padrão; `floating` destaca.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Message composition fixed at the bottom (chat/AI).\",\n        \"You need a safe area + the style axis (glass) around the composer.\"\n      ],\n      \"pt\": [\n        \"Composição de mensagens fixa no rodapé (chat/IA).\",\n        \"Precisa de safe-area + eixo de estilo (glass) em volta do composer.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Composing with no bar and no safe area → AppChatComposer directly.\",\n        \"Search → AppSearchFooter.\"\n      ],\n      \"pt\": [\n        \"Compose sem barra/safe-area → AppChatComposer direto.\",\n        \"Busca → AppSearchFooter.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"controller\",\n        \"type\": \"TextEditingController\",\n        \"required\": true\n      },\n      {\n        \"name\": \"hintText\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"busy\",\n        \"type\": \"bool\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onSend\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onStop\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onAttach\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"attachments\",\n        \"type\": \"List<Widget>\",\n        \"required\": false\n      },\n      {\n        \"name\": \"modelLabel\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppStyle\",\n        \"required\": false\n      },\n      {\n        \"name\": \"radiusMode\",\n        \"type\": \"AppRadiusMode?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"floating\",\n        \"type\": \"bool\",\n        \"required\": false\n      },\n      {\n        \"name\": \"size\",\n        \"type\": \"AppFieldSize\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"default\",\n      \"busy\",\n      \"glass\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Chat\",\n          \"pt\": \"Chat\"\n        },\n        \"code\": \"AppChatFooter(controller: c, onSend: send, hintText: 'Pergunte…')\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Let the bar carry the style (the composer stays filled).\"\n      ],\n      \"pt\": [\n        \"Deixe a barra carregar o estilo (composer fica filled).\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not style the composer from outside — pass `style` on the footer.\"\n      ],\n      \"pt\": [\n        \"Não estilize o composer por fora — passe `style` no footer.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Inherits AppChatComposer's semantics (send/stop, attachments).\",\n      \"pt\": \"Herda a semântica do AppChatComposer (envio/parada, anexos).\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_search_footer\",\n      \"app_navigation_footer\"\n    ]\n  },\n  {\n    \"id\": \"app_list_empty\",\n    \"name\": \"AppListEmpty\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"List empty state: illustration + message + optional action.\",\n      \"pt\": \"Estado vazio de lista: ilustração + mensagem + ação opcional.\"\n    },\n    \"description\": {\n      \"en\": \"A centered illustration, a message (onSurface) and an optional clear-filter action (a secondary AppTextButton). Colors from the theme; the illustration adapts to light/dark.\",\n      \"pt\": \"Ilustração centralizada, mensagem (onSurface) e uma ação opcional de limpar filtro (AppTextButton secundário). Cores do tema; ilustração adapta-se a claro/escuro.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"A list or table with no items (empty, or no results for the filter).\"\n      ],\n      \"pt\": [\n        \"Lista/tabela sem itens (vazia ou sem resultados de filtro).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A load error → a dedicated error state.\",\n        \"Loading → AppShimmerLoading / AppCircularLoading.\"\n      ],\n      \"pt\": [\n        \"Erro de carregamento → estado de erro dedicado.\",\n        \"Carregando → AppShimmerLoading / AppCircularLoading.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"illustration\",\n        \"type\": \"String\",\n        \"required\": true,\n        \"description\": {\n          \"en\": \"Illustration URL (e.g. AppIllustrations.empty).\",\n          \"pt\": \"URL da ilustração (ex.: AppIllustrations.empty).\"\n        }\n      },\n      {\n        \"name\": \"text\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"onClearFilter\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"If != null, shows the \\\"Clear\\\" button.\",\n          \"pt\": \"Se != null, mostra o botão \\\"Limpar\\\".\"\n        }\n      }\n    ],\n    \"states\": [\n      \"default\",\n      \"with-action\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"No results\",\n          \"pt\": \"Sem resultados\"\n        },\n        \"code\": \"AppListEmpty(illustration: AppIllustrations.empty, text: 'Nenhum resultado.', onClearFilter: clear)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Offer the clear action whenever a filter is active.\"\n      ],\n      \"pt\": [\n        \"Ofereça a ação de limpar quando houver filtro ativo.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it for errors — use an error state.\"\n      ],\n      \"pt\": [\n        \"Não use para erros — use um estado de erro.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"The message in onSurface over the surface (an AA pair). The illustration is decorative; the message describes the state.\",\n      \"pt\": \"Mensagem em onSurface sobre a surface (par AA). A ilustração é decorativa; a mensagem descreve o estado.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_illustration\",\n      \"app_interaction\"\n    ]\n  },\n  {\n    \"id\": \"app_tile_info\",\n    \"name\": \"AppTileInfo\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Label/value pair (not clickable).\",\n      \"pt\": \"Par rótulo/valor (não clicável).\"\n    },\n    \"description\": {\n      \"en\": \"A label in a legible neutral + a value in onSurface, stacked. Colors from the theme (AA contrast). A reusable data block for detail views.\",\n      \"pt\": \"Rótulo em neutro legível + valor em onSurface, empilhados. Cores do tema (contraste AA). Bloco de dado reutilizável em detalhes.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Showing a label/value field on detail screens.\"\n      ],\n      \"pt\": [\n        \"Exibir um campo rótulo/valor em telas de detalhe.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A clickable row → AppListTile / AppListTileAction.\"\n      ],\n      \"pt\": [\n        \"Linha clicável → AppListTile / AppListTileAction.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"title\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"text\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"textAlign\",\n        \"type\": \"TextAlign\",\n        \"required\": false,\n        \"default\": \"TextAlign.start\"\n      }\n    ],\n    \"states\": [\n      \"default\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Field\",\n          \"pt\": \"Campo\"\n        },\n        \"code\": \"AppTileInfo(title: 'Identificador', text: 'TTS4G47')\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use it in detail grids (label/value).\"\n      ],\n      \"pt\": [\n        \"Use em grades de detalhe (label/valor).\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it for clickable rows.\"\n      ],\n      \"pt\": [\n        \"Não use para linhas clicáveis.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Label and value at AA contrast against the surface.\",\n      \"pt\": \"Rótulo e valor com contraste AA sobre a superfície.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_list_tile\"\n    ]\n  },\n  {\n    \"id\": \"app_list_tile\",\n    \"name\": \"AppListTile\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"List row in 2 styles, with orthogonal variations.\",\n      \"pt\": \"Linha de lista em 2 estilos, com variações ortogonais.\"\n    },\n    \"description\": {\n      \"en\": \"One tile in 2 styles (AppListTileStyle bordered/grouped) with variations through named constructors: navigation (chevron), checkbox, toggle (switch), badge, and a generic one (custom trailing). leading and subtitle are optional; reorderIndex adds a drag handle. Built on FlocksInteraction; colors, radius and animation from the theme, with an optional danger role. Group them with AppListTileGroup.\",\n      \"pt\": \"Um só tile em 2 estilos (AppListTileStyle bordered/grouped) e variações via construtores nomeados: navigation (chevron), checkbox, toggle (switch), badge, + genérico (trailing custom). leading e subtitle opcionais; reorderIndex adiciona drag handle. Sobre FlocksInteraction; cores/raio/animação do tema e papel danger opcional. Agrupe com AppListTileGroup.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Menu, selection or navigation rows (with or without a leading and a subtitle).\"\n      ],\n      \"pt\": [\n        \"Linhas de menu, seleção ou navegação (com/sem leading e subtitle).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Single selection (radio) → AppListTileRadio.\",\n        \"A static label/value pair in a grid → AppTileInfo.\"\n      ],\n      \"pt\": [\n        \"Seleção única (radio) → AppListTileRadio.\",\n        \"Par rótulo/valor estático em grid → AppTileInfo.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"danger\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      },\n      {\n        \"name\": \"title\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"subtitle\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"leading\",\n        \"type\": \"Widget?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"AppIcon/AppAvatar/custom.\",\n          \"pt\": \"AppIcon/AppAvatar/custom.\"\n        }\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppListTileStyle\",\n        \"required\": false,\n        \"default\": \"AppListTileStyle.grouped\",\n        \"enumValues\": [\n          \"bordered\",\n          \"grouped\"\n        ]\n      },\n      {\n        \"name\": \"onTap\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"trailing\",\n        \"type\": \"Widget?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Generic constructor only.\",\n          \"pt\": \"Só no construtor genérico.\"\n        }\n      },\n      {\n        \"name\": \"value\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \".checkbox/.toggle\",\n          \"pt\": \".checkbox/.toggle\"\n        }\n      },\n      {\n        \"name\": \"onChanged\",\n        \"type\": \"ValueChanged<bool>?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \".checkbox/.toggle\",\n          \"pt\": \".checkbox/.toggle\"\n        }\n      },\n      {\n        \"name\": \"badge\",\n        \"type\": \"String\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \".badge\",\n          \"pt\": \".badge\"\n        }\n      },\n      {\n        \"name\": \"badgeColor\",\n        \"type\": \"AppBadgeColor\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \".badge\",\n          \"pt\": \".badge\"\n        }\n      },\n      {\n        \"name\": \"enabled\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"reorderIndex\",\n        \"type\": \"int?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Draggable: adds a drag handle.\",\n          \"pt\": \"Draggable: adiciona drag handle.\"\n        }\n      },\n      {\n        \"name\": \"semanticLabel\",\n        \"type\": \"String?\",\n        \"required\": false\n      }\n    ],\n    \"variants\": [\n      \"generic\",\n      \"navigation\",\n      \"checkbox\",\n      \"toggle\",\n      \"badge\"\n    ],\n    \"states\": [\n      \"default\",\n      \"hovered\",\n      \"pressed\",\n      \"focused\",\n      \"disabled\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Navigation with a leading\",\n          \"pt\": \"Navegação com leading\"\n        },\n        \"code\": \"AppListTile.navigation(leading: AppIcon(AppIconToken.support), title: \\\"Suporte\\\", onTap: open)\"\n      },\n      {\n        \"title\": {\n          \"en\": \"Checkbox\",\n          \"pt\": \"Checkbox\"\n        },\n        \"code\": \"AppListTile.checkbox(title: \\\"Item\\\", value: v, onChanged: set)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Group related rows with AppListTileGroup.\",\n        \"Use grouped for actions, bordered for information.\"\n      ],\n      \"pt\": [\n        \"Agrupe linhas relacionadas com AppListTileGroup.\",\n        \"Use grouped p/ ações, bordered p/ informativo.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not mix a radio in here — use AppListTileRadio.\"\n      ],\n      \"pt\": [\n        \"Não misture radio aqui — use AppListTileRadio.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"navigation/badge carry a button role; checkbox/toggle merge the title with the control; title in onSurface and subtitle in neutral s700, both at AA contrast over either surface (grouped/bordered).\",\n      \"pt\": \"navigation/badge com role de botão; checkbox/toggle fazem merge do título com o controle; título onSurface e subtítulo neutro s700 com contraste AA sobre ambas as superfícies (grouped/bordered).\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_list_tile_group\",\n      \"app_list_tile_radio\",\n      \"app_tile_info\"\n    ]\n  },\n  {\n    \"id\": \"app_list_tile_action\",\n    \"name\": \"AppListTileAction\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Title/value row with a trailing action, clickable.\",\n      \"pt\": \"Linha título/valor com trailing de ação, clicável.\"\n    },\n    \"description\": {\n      \"en\": \"A discreet title (titleSmall) over a strong value (titleMedium), with a bottom border and a trailing action widget (e.g. AppIcon(swapArrow)). The whole row is clickable when onPressed != null.\",\n      \"pt\": \"Título discreto (titleSmall) sobre valor forte (titleMedium), com borda inferior e um widget trailing de ação (ex.: AppIcon(swapArrow)). A linha inteira é clicável quando onPressed != null.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Opening a picker or an action from a field row.\"\n      ],\n      \"pt\": [\n        \"Abrir um seletor/ação a partir de uma linha de campo.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Toggling a boolean → AppListTileCheckbox.\"\n      ],\n      \"pt\": [\n        \"Alternar um booleano → AppListTileCheckbox.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"title\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"text\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"trailing\",\n        \"type\": \"Widget\",\n        \"required\": true\n      },\n      {\n        \"name\": \"onPressed\",\n        \"type\": \"VoidCallback?\",\n        \"required\": true\n      }\n    ],\n    \"states\": [\n      \"default\",\n      \"pressed\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Action\",\n          \"pt\": \"Ação\"\n        },\n        \"code\": \"AppListTileAction(title: 'Veículos', text: 'TTS4G47', trailing: const AppIcon(AppIconToken.swapArrow), onPressed: pick)\"\n      }\n    ],\n    \"a11y\": {\n      \"en\": \"A clickable row; title and value at AA contrast against the surface.\",\n      \"pt\": \"Linha clicável; título e valor com contraste AA sobre a superfície.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_list_tile\",\n      \"app_tile_info\"\n    ]\n  },\n  {\n    \"id\": \"app_list_tile_checkbox\",\n    \"name\": \"AppListTileCheckbox\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Selection row with a checkbox; the whole row toggles.\",\n      \"pt\": \"Linha de seleção com checkbox; a linha inteira alterna.\"\n    },\n    \"description\": {\n      \"en\": \"An optional title (titleSmall) over an identifier (titleMedium; secondary when checked) and an AppCheckbox on the right. Tapping anywhere on the row toggles the state when enabled.\",\n      \"pt\": \"Título opcional (titleSmall) sobre identificador (titleMedium; secondary quando marcado) e um AppCheckbox à direita. Tocar em qualquer ponto da linha alterna o estado quando habilitada.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Selecting items from a list (multi-selection).\"\n      ],\n      \"pt\": [\n        \"Selecionar itens de uma lista (multi-seleção).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"An action or a picker → AppListTileAction.\"\n      ],\n      \"pt\": [\n        \"Ação/seletor → AppListTileAction.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"checked\",\n        \"type\": \"bool\",\n        \"required\": true\n      },\n      {\n        \"name\": \"text\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"title\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"enabled\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"onChanged\",\n        \"type\": \"ValueChanged<bool>?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"unchecked\",\n      \"checked\",\n      \"disabled\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Selection\",\n          \"pt\": \"Seleção\"\n        },\n        \"code\": \"AppListTileCheckbox(title: 'Polo Track 01', text: 'TTS4G47', checked: selected, onChanged: onToggle)\"\n      }\n    ],\n    \"a11y\": {\n      \"en\": \"The whole row is a touch target; AA contrast in both states.\",\n      \"pt\": \"Linha inteira é alvo de toque; contraste AA em ambos os estados.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_list_tile\",\n      \"app_list_tile_draggable_checkbox\"\n    ]\n  },\n  {\n    \"id\": \"app_list_tile_draggable_checkbox\",\n    \"name\": \"AppListTileDraggableCheckbox\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Reorderable selection row: a drag handle + a checkbox.\",\n      \"pt\": \"Linha de seleção reordenável: handle de arraste + checkbox.\"\n    },\n    \"description\": {\n      \"en\": \"Like AppListTileCheckbox, with a drag handle (dragArrow) on the left through ReorderableDragStartListener(index: reorderIndex). Use it inside a reorderable list.\",\n      \"pt\": \"Como AppListTileCheckbox, com um handle de arraste (dragArrow) à esquerda via ReorderableDragStartListener(index: reorderIndex). Use dentro de uma lista reordenável.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Selecting and reordering items (e.g. table columns).\"\n      ],\n      \"pt\": [\n        \"Selecionar e reordenar itens (ex.: colunas de tabela).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"No reordering → AppListTileCheckbox.\"\n      ],\n      \"pt\": [\n        \"Sem reordenação → AppListTileCheckbox.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"checked\",\n        \"type\": \"bool\",\n        \"required\": true\n      },\n      {\n        \"name\": \"reorderIndex\",\n        \"type\": \"int\",\n        \"required\": true\n      },\n      {\n        \"name\": \"title\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"text\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"enabled\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"onChanged\",\n        \"type\": \"ValueChanged<bool>?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"reorderEnabled\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      }\n    ],\n    \"states\": [\n      \"unchecked\",\n      \"checked\",\n      \"dragging\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Reorderable\",\n          \"pt\": \"Reordenável\"\n        },\n        \"code\": \"AppListTileDraggableCheckbox(reorderIndex: i, title: 'Coluna', text: 'Placa', checked: col.visible, onChanged: onToggle)\"\n      }\n    ],\n    \"a11y\": {\n      \"en\": \"A dedicated drag handle; the row toggles the selection.\",\n      \"pt\": \"Handle de arraste dedicado; a linha alterna a seleção.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_list_tile_checkbox\",\n      \"app_list_tile\"\n    ]\n  },\n  {\n    \"id\": \"app_list_tile_radio\",\n    \"name\": \"AppListTileRadio\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"List row with a radio (single selection).\",\n      \"pt\": \"Linha de lista com radio (seleção única).\"\n    },\n    \"description\": {\n      \"en\": \"Generic AppListTileRadio<T>. Tapping the row selects the value. Same styles and variations as AppListTile (leading/subtitle/draggable/style); trailing = AppRadio. Its own class because a named constructor cannot introduce a <T>.\",\n      \"pt\": \"Genérico AppListTileRadio<T>. Tocar a linha seleciona o value. Mesmos estilos/variações do AppListTile (leading/subtitle/draggable/style); trailing = AppRadio. Classe própria porque um construtor nomeado não pode introduzir <T>.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Choosing one option among several, in a list.\"\n      ],\n      \"pt\": [\n        \"Escolher uma opção entre várias, em lista.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Multiple selection → AppListTile.checkbox.\",\n        \"On/off → AppListTile.toggle.\"\n      ],\n      \"pt\": [\n        \"Múltipla seleção → AppListTile.checkbox.\",\n        \"Liga/desliga → AppListTile.toggle.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"title\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"value\",\n        \"type\": \"T\",\n        \"required\": true\n      },\n      {\n        \"name\": \"groupValue\",\n        \"type\": \"T?\",\n        \"required\": true\n      },\n      {\n        \"name\": \"onChanged\",\n        \"type\": \"ValueChanged<T?>?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"subtitle\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"leading\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppListTileStyle\",\n        \"required\": false,\n        \"default\": \"AppListTileStyle.grouped\",\n        \"enumValues\": [\n          \"bordered\",\n          \"grouped\"\n        ]\n      },\n      {\n        \"name\": \"enabled\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"reorderIndex\",\n        \"type\": \"int?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"semanticLabel\",\n        \"type\": \"String?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"unselected\",\n      \"selected\",\n      \"disabled\",\n      \"hovered\",\n      \"focused\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Choose\",\n          \"pt\": \"Escolher\"\n        },\n        \"code\": \"AppListTileRadio<String>(title: \\\"Polo\\\", value: id, groupValue: sel, onChanged: choose)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use it inside an AppListTileGroup sharing the same groupValue.\"\n      ],\n      \"pt\": [\n        \"Use dentro de um AppListTileGroup com o mesmo groupValue.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it for multiple selection.\"\n      ],\n      \"pt\": [\n        \"Não use para múltipla seleção.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"AppRadio exposes the exclusive-group semantics; merged with the title; title in onSurface at AA contrast.\",\n      \"pt\": \"AppRadio expõe a semântica de grupo exclusivo; merge com o título; título onSurface com contraste AA.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_list_tile\",\n      \"app_radio\"\n    ]\n  },\n  {\n    \"id\": \"app_list_tile_group\",\n    \"name\": \"AppListTileGroup\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Groups list tiles into a card with a background/border + dividers.\",\n      \"pt\": \"Agrupa list-tiles num card com fundo/borda + divisórias.\"\n    },\n    \"description\": {\n      \"en\": \"The container for AppListTiles: depending on style, a `surfaceContainer` background (grouped) or an `outline` border (bordered), corners from the global radius and `outline` dividers between rows. It tells the tiles (through a scope) that it draws the container, so each tile renders only the row.\",\n      \"pt\": \"Container dos AppListTile: por style, fundo `surfaceContainer` (grouped) ou borda `outline` (bordered), cantos do radius global e divisórias `outline` entre as linhas. Informa aos tiles (via escopo) que ele desenha o container, então cada tile renderiza só a linha.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Stacking several related list rows into one block.\"\n      ],\n      \"pt\": [\n        \"Empilhar várias linhas de lista relacionadas num bloco.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A single standalone row → use AppListTile directly.\"\n      ],\n      \"pt\": [\n        \"Uma única linha avulsa → use o AppListTile direto.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"children\",\n        \"type\": \"List<Widget>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppListTileStyle\",\n        \"required\": false,\n        \"default\": \"AppListTileStyle.grouped\",\n        \"enumValues\": [\n          \"bordered\",\n          \"grouped\"\n        ]\n      }\n    ],\n    \"variants\": [\n      \"grouped\",\n      \"bordered\"\n    ],\n    \"states\": [\n      \"default\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Menu\",\n          \"pt\": \"Menu\"\n        },\n        \"code\": \"AppListTileGroup(children: [AppListTile.navigation(title: \\\"Suporte\\\", onTap: s), AppListTile.navigation(title: \\\"Sair\\\", onTap: out)])\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use it for menus, selections and short related lists.\"\n      ],\n      \"pt\": [\n        \"Use para menus, seleções e listas curtas relacionadas.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not nest groups.\"\n      ],\n      \"pt\": [\n        \"Não aninhe grupos.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"A visual container; the semantics come from the child tiles. Background, border and divider meet the contract's contrast in light and dark across both brands.\",\n      \"pt\": \"Container visual; a semântica vem dos tiles filhos. Fundo/borda/divisória com contraste do contrato em claro/escuro nas duas marcas.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_list_tile\",\n      \"app_list_tile_radio\"\n    ]\n  },\n  {\n    \"id\": \"app_alert\",\n    \"name\": \"AppAlert\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Alert card with a title, a description and a semantic icon.\",\n      \"pt\": \"Card de alerta com título, descrição e ícone semântico.\"\n    },\n    \"description\": {\n      \"en\": \"The alert CARD only (surfaceContainer tinted by the semantic color) with a title, a description (up to 3 lines) and an icon in the semantic color (info/success/warning/danger). The container follows the global AppStyle axis (filled = tone only; outlined = tone + border; elevated = tone + shadow). To show it somewhere on screen use the `showAppOverlay` helper (3×3 position without the center, maximum width, enter/exit animation). Colors 100% from the theme → AA contrast; announced (liveRegion).\",\n      \"pt\": \"Apenas o CARD de alerta (surfaceContainer tingido pela cor semântica) com título, descrição (até 3 linhas) e ícone na cor semântica (info/success/warning/danger). O container segue o eixo AppStyle global (filled = só o tom; outlined = tom + borda; elevated = tom + sombra). Para exibi-lo num ponto da tela use o helper `showAppOverlay` (posição 3×3 sem o centro, largura máxima, animação de entrada/saída). Cores 100% do tema → contraste AA; anunciado (liveRegion).\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Contextual feedback (notice, error, success) — inline on the page.\",\n        \"Transient feedback (it disappears on its own) — through showAppOverlay with a duration.\"\n      ],\n      \"pt\": [\n        \"Feedback contextual (aviso, erro, sucesso) — inline na página.\",\n        \"Feedback transitório (some sozinho) — via showAppOverlay com duration.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A short status pill (no title or description) → AppBadge.\",\n        \"A generic floating surface (free content) → AppCard.\"\n      ],\n      \"pt\": [\n        \"Pílula curta de status (sem título/descrição) → AppBadge.\",\n        \"Superfície flutuante genérica (conteúdo livre) → AppCard.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"title\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"description\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"color\",\n        \"type\": \"AppAlertColor\",\n        \"required\": false,\n        \"default\": \"AppAlertColor.info\",\n        \"enumValues\": [\n          \"info\",\n          \"success\",\n          \"warning\",\n          \"danger\"\n        ]\n      },\n      {\n        \"name\": \"icon\",\n        \"type\": \"String?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Icon to the right of the title (defaults to the color's icon).\",\n          \"pt\": \"Ícone à direita do título (default = ícone do color).\"\n        }\n      }\n    ],\n    \"variants\": [\n      \"info\",\n      \"success\",\n      \"warning\",\n      \"danger\"\n    ],\n    \"states\": [\n      \"default\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Error alert\",\n          \"pt\": \"Alerta de erro\"\n        },\n        \"code\": \"AppAlert(title: 'Sem conexão', description: '...', color: AppAlertColor.danger)\"\n      },\n      {\n        \"title\": {\n          \"en\": \"Positioned on screen\",\n          \"pt\": \"Posicionado na tela\"\n        },\n        \"code\": \"showAppOverlay(context: context, position: AppOverlayPosition.topRight, animation: AppOverlayAnimation.slide, maxWidth: 360, child: AppAlert(title: 'Salvo', description: '...'))\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use the semantic color that matches the message (danger for an error, and so on).\",\n        \"Keep the title short (1 line).\"\n      ],\n      \"pt\": [\n        \"Use a cor semântica que casa com a mensagem (danger para erro etc.).\",\n        \"Mantenha o título curto (1 linha).\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not stack several overlays in the same corner at once.\"\n      ],\n      \"pt\": [\n        \"Não empilhe vários overlays no mesmo canto ao mesmo tempo.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Wrapped in AppSemantics.liveRegion → announced when it appears. Title in onSurface and description in neutral s700 over the tinted background both pass AA; the border (when present, in the outlined style) and the icon (semantic color) are ≥ 3:1 against the surface.\",\n      \"pt\": \"Embrulhado em AppSemantics.liveRegion → anunciado ao surgir. Título onSurface e descrição neutro s700 sobre o fundo tingido passam AA; borda (quando presente, no estilo outlined) e ícone (cor semântica) ≥ 3:1 sobre a superfície.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_badge\",\n      \"app_card\",\n      \"app_tooltip\"\n    ]\n  },\n  {\n    \"id\": \"app_menu\",\n    \"name\": \"AppMenu\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Anchored action menu (popup / context menu), through the Overlay.\",\n      \"pt\": \"Menu de ações ancorado (popup / context menu), via Overlay.\"\n    },\n    \"description\": {\n      \"en\": \"No Material. A list of actions (AppMenuItem) with an optional icon, sections, dividers and destructive items, anchored to the trigger by a LayerLink. Distinct from AppDropdown (which is a form select).\",\n      \"pt\": \"Sem Material. Lista de ações (AppMenuItem) com ícone opcional, seções, divisórias e itens destrutivos, ancorada ao trigger por LayerLink. Distinto do AppDropdown (que é um select de formulário).\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Contextual actions for an element (edit/duplicate/delete).\",\n        \"An overflow menu (⋯) or a right-click menu.\"\n      ],\n      \"pt\": [\n        \"Ações contextuais de um elemento (editar/duplicar/excluir).\",\n        \"Menu de overflow (⋯) ou menu de clique-direito.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Choosing a value in a form → use AppDropdown.\",\n        \"Rich content (text, fields) → use AppPopover.\"\n      ],\n      \"pt\": [\n        \"Escolher um valor de um formulário → use AppDropdown.\",\n        \"Conteúdo rico (texto/campos) → use AppPopover.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"trigger\",\n        \"type\": \"Widget\",\n        \"required\": true\n      },\n      {\n        \"name\": \"entries\",\n        \"type\": \"List<AppMenuEntry>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"placement\",\n        \"type\": \"AppOverlayPlacement\",\n        \"required\": false,\n        \"default\": \"bottomStart\"\n      },\n      {\n        \"name\": \"openOnSecondaryTap\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      },\n      {\n        \"name\": \"minWidth\",\n        \"type\": \"double\",\n        \"required\": false,\n        \"default\": \"176\"\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppStyle?\",\n        \"required\": false,\n        \"default\": \"elevated\",\n        \"description\": {\n          \"en\": \"The panel's container; defaults to elevated (it does not follow the global).\",\n          \"pt\": \"Container do painel; default elevated (não segue o global).\"\n        },\n        \"enumValues\": [\n          \"filled\",\n          \"outlined\",\n          \"elevated\"\n        ]\n      },\n      {\n        \"name\": \"radiusMode\",\n        \"type\": \"AppRadiusMode?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"radius\",\n        \"type\": \"BorderRadius?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"controller\",\n        \"type\": \"AppMenuController?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onOpenChanged\",\n        \"type\": \"ValueChanged<bool>?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"closed\",\n      \"open\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Action menu with a destructive item\",\n          \"pt\": \"Menu de ações com item destrutivo\"\n        },\n        \"code\": \"AppMenu(trigger: AppIcon(AppIconToken.settings), entries: <AppMenuEntry>[AppMenuItem(label: \\\"Editar\\\", onPressed: edit), AppMenuDivider(), AppMenuItem(label: \\\"Excluir\\\", danger: true, onPressed: remove)])\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use a passive trigger; mark destructive actions with danger.\"\n      ],\n      \"pt\": [\n        \"Use um trigger passivo; marque ações destrutivas com danger.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it as a form select (that is AppDropdown).\"\n      ],\n      \"pt\": [\n        \"Não use como select de formulário (isso é o AppDropdown).\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Each item is a button (AppSemantics.menuItem) that merges icon and text. Navigation with Tab and the ↑/↓ arrows; Esc closes it. The panel enters with a fade+pop that honors reduce-motion.\",\n      \"pt\": \"Cada item é um botão (AppSemantics.menuItem) com merge de ícone+texto. Navegação por Tab e setas ↑/↓; fecha no Esc. O painel entra com fade+pop respeitando reduce-motion.\"\n    },\n    \"crossPlatform\": false,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_dropdown\",\n      \"app_popover\",\n      \"app_split_button\"\n    ]\n  },\n  {\n    \"id\": \"app_number_stepper\",\n    \"name\": \"AppNumberStepper\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Numeric control − value + (min/max/step), with no text editing.\",\n      \"pt\": \"Controle numérico − valor + (min/max/step), sem edição de texto.\"\n    },\n    \"description\": {\n      \"en\": \"Decrements / displays / increments. The − disables at min and the + at max. No editable field (that would be an organism/AppInput).\",\n      \"pt\": \"Decrementa / exibe / incrementa. O − desabilita em min e o + em max. Sem campo editável (isso seria organism/AppInput).\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Small quantities with discrete steps (items, copies, minutes).\"\n      ],\n      \"pt\": [\n        \"Quantidades pequenas com passos discretos (itens, cópias, minutos).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Free or wide numeric input → a text field (AppInput, organism).\",\n        \"Choosing from fixed options → AppDropdown/AppSegmentedButton.\"\n      ],\n      \"pt\": [\n        \"Entrada numérica livre/ampla → campo de texto (AppInput, organism).\",\n        \"Escolher de opções fixas → AppDropdown/AppSegmentedButton.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"value\",\n        \"type\": \"num\",\n        \"required\": true\n      },\n      {\n        \"name\": \"onChanged\",\n        \"type\": \"ValueChanged<num>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"min\",\n        \"type\": \"num\",\n        \"required\": false,\n        \"default\": \"0\"\n      },\n      {\n        \"name\": \"max\",\n        \"type\": \"num\",\n        \"required\": false,\n        \"default\": \"double.infinity\"\n      },\n      {\n        \"name\": \"step\",\n        \"type\": \"num\",\n        \"required\": false,\n        \"default\": \"1\"\n      },\n      {\n        \"name\": \"enabled\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"size\",\n        \"type\": \"AppButtonSize\",\n        \"required\": false,\n        \"default\": \"m\"\n      },\n      {\n        \"name\": \"format\",\n        \"type\": \"String Function(num)?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"enabled\",\n      \"at-min\",\n      \"at-max\",\n      \"disabled\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Quantity 1–99\",\n          \"pt\": \"Quantidade 1–99\"\n        },\n        \"code\": \"AppNumberStepper(value: qty, min: 1, max: 99, onChanged: setQty)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Set min/max; use format for units or currency.\"\n      ],\n      \"pt\": [\n        \"Defina min/max; use format para unidades/moeda.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it for wide numeric input (use a field).\"\n      ],\n      \"pt\": [\n        \"Não use para entrada numérica ampla (use um campo).\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"The − and the + are labelled buttons (Decrease/Increase) and disable at the limits. The value is a status region (announced when it changes).\",\n      \"pt\": \"O − e o + são botões rotulados (Diminuir/Aumentar) e desabilitam nos limites. O valor é uma região de status (anunciada ao mudar).\"\n    },\n    \"crossPlatform\": false,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_interaction\"\n    ]\n  },\n  {\n    \"id\": \"app_card\",\n    \"name\": \"AppCard\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Structured card (header/child/footer) on the AppStyle axis.\",\n      \"pt\": \"Card estruturado (header/child/footer) no eixo AppStyle.\"\n    },\n    \"description\": {\n      \"en\": \"A surfaceContainer surface that takes part in the AppStyle axis: filled (flat), outlined (outline border) or elevated (shadow, theme-aware). Like the other containers in the design system, the default follows the global styleTheme; the shape follows the global radius. It structures content through optional slots: header (leading/title/trailing), child and footer, with optional dividers (showDividers). accentColor emphasizes the outlined border. It does not intercept the pointer (that is the caller's responsibility over platform views).\",\n      \"pt\": \"Superfície surfaceContainer que participa do eixo AppStyle: filled (chapado), outlined (borda outline) ou elevated (sombra, theme-aware). Como os demais containers do DS, o default segue o global styleTheme; a forma segue o radius global. Estrutura o conteúdo via slots opcionais: header (leading/title/trailing), child e footer, com divisórias opcionais (showDividers). accentColor destaca a borda do outlined. Não intercepta ponteiro (responsabilidade do chamador sobre platform views).\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"A structured content panel (title, body, actions).\",\n        \"A generic popover or floating panel over the UI (pin style: elevated).\"\n      ],\n      \"pt\": [\n        \"Painel de conteúdo estruturado (título, corpo, ações).\",\n        \"Popover/painel flutuante genérico sobre a UI (fixe style: elevated).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"An alert with a title and a semantic icon → AppAlert.\",\n        \"A full-page modal → AppDialog (organism).\"\n      ],\n      \"pt\": [\n        \"Alerta com título/ícone semântico → AppAlert.\",\n        \"Modal de página inteira → AppDialog (organism).\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"child\",\n        \"type\": \"Widget?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Main content (optional).\",\n          \"pt\": \"Conteúdo principal (opcional).\"\n        }\n      },\n      {\n        \"name\": \"headerTitle\",\n        \"type\": \"String?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Header title (titleMedium/onSurface, 1 line).\",\n          \"pt\": \"Título do header (titleMedium/onSurface, 1 linha).\"\n        }\n      },\n      {\n        \"name\": \"headerLeading\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"headerTrailing\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"footer\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"showDividers\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\",\n        \"description\": {\n          \"en\": \"Divider between the sections present.\",\n          \"pt\": \"Divisória entre as seções presentes.\"\n        }\n      },\n      {\n        \"name\": \"accentColor\",\n        \"type\": \"Color?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Border color (defaults to the outline token).\",\n          \"pt\": \"Cor da borda (default = token outline).\"\n        }\n      },\n      {\n        \"name\": \"padding\",\n        \"type\": \"EdgeInsetsGeometry?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Padding per section (defaults to all s16).\",\n          \"pt\": \"Padding por seção (default all s16).\"\n        }\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppStyle?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Container; null follows the global styleTheme.\",\n          \"pt\": \"Container; null segue o global styleTheme.\"\n        },\n        \"enumValues\": [\n          \"filled\",\n          \"outlined\",\n          \"elevated\"\n        ]\n      },\n      {\n        \"name\": \"radiusMode\",\n        \"type\": \"AppRadiusMode?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"radius\",\n        \"type\": \"BorderRadius?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"filled\",\n      \"outlined\",\n      \"elevated\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Card with a header\",\n          \"pt\": \"Card com header\"\n        },\n        \"code\": \"AppCard(headerTitle: 'Localização', child: mapPreview)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use the slots (headerTitle/leading/trailing, footer) to structure it; turn showDividers on to separate sections.\",\n        \"Pin style: elevated on floating panels (menu/dropdown).\"\n      ],\n      \"pt\": [\n        \"Use os slots (headerTitle/leading/trailing, footer) para estruturar; ligue showDividers para separar seções.\",\n        \"Fixe style: elevated em painéis flutuantes (menu/dropdown).\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not count on built-in pointer interception over maps.\"\n      ],\n      \"pt\": [\n        \"Não conte com interceptação de ponteiro embutida sobre mapas.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"A visual container; the semantics come from the child. The outline border is ≥ 3:1 against the surface; the content inherits onSurface over surfaceContainer (an AA pair).\",\n      \"pt\": \"Container visual; a semântica vem do child. Borda outline ≥ 3:1 sobre a superfície; conteúdo herda onSurface sobre surfaceContainer (par AA).\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_alert\",\n      \"app_surface\",\n      \"app_expansion_tile\"\n    ]\n  },\n  {\n    \"id\": \"app_pagination\",\n    \"name\": \"AppPagination\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Page navigation (prev/next + numbers with an ellipsis).\",\n      \"pt\": \"Navegação de páginas (prev/next + números com reticências).\"\n    },\n    \"description\": {\n      \"en\": \"Standalone (decoupled from any table). The current page is a filled pill; the rest are ghosts. An optional \\\"per page\\\" selector (it reuses AppDropdown).\",\n      \"pt\": \"Standalone (desacoplada de tabela). Página atual = pílula preenchida; demais = fantasmas. Seletor de \\\"por página\\\" opcional (reusa AppDropdown).\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Paginating a large list or table from the footer.\"\n      ],\n      \"pt\": [\n        \"Paginar uma lista/tabela grande no rodapé.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Infinite scrolling / load-more → a different pattern.\",\n        \"A few items on a single page → do not paginate.\"\n      ],\n      \"pt\": [\n        \"Rolagem infinita / carregar-mais → outro padrão.\",\n        \"Poucos itens numa página só → não pagine.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"currentPage\",\n        \"type\": \"int\",\n        \"required\": true\n      },\n      {\n        \"name\": \"pageCount\",\n        \"type\": \"int\",\n        \"required\": true\n      },\n      {\n        \"name\": \"onPageChanged\",\n        \"type\": \"ValueChanged<int>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"siblingCount\",\n        \"type\": \"int\",\n        \"required\": false,\n        \"default\": \"1\"\n      },\n      {\n        \"name\": \"boundaryCount\",\n        \"type\": \"int\",\n        \"required\": false,\n        \"default\": \"1\"\n      },\n      {\n        \"name\": \"showPrevNext\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"perPage\",\n        \"type\": \"AppPaginationPerPage?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"current\",\n      \"other\",\n      \"hovered\",\n      \"ellipsis\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"List footer\",\n          \"pt\": \"Rodapé de lista\"\n        },\n        \"code\": \"AppPagination(currentPage: page, pageCount: total, onPageChanged: (p) => goTo(p))\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Tune siblingCount/boundaryCount for the space available.\"\n      ],\n      \"pt\": [\n        \"Ajuste siblingCount/boundaryCount para o espaço disponível.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it with infinite scrolling.\"\n      ],\n      \"pt\": [\n        \"Não use com rolagem infinita.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Each number is a \\\"Page N\\\" button; the current one is marked as selected. Previous/Next disable at the ends. The truncation is a pure function (paginationRange).\",\n      \"pt\": \"Cada número é um botão \\\"Página N\\\"; a atual é marcada como selecionada. Anterior/Próxima desabilitam nos extremos. O truncamento é uma função pura (paginationRange).\"\n    },\n    \"crossPlatform\": false,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_dropdown\",\n      \"app_interaction\"\n    ]\n  },\n  {\n    \"id\": \"app_picker_anchor\",\n    \"name\": \"AppPickerAnchor\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Generic picker anchor: a trigger that opens an anchored floating panel (date/time/color…) in an AppCard.\",\n      \"pt\": \"Âncora genérica de picker: um trigger que abre um painel flutuante ancorado (date/time/color…) num AppCard.\"\n    },\n    \"description\": {\n      \"en\": \"No Material. The pickers' overlay machine, decoupled from the input: it takes a trigger builder and a panel builder (both with an AppPickerHandle for open/close/toggle/rebuild), anchors through a LayerLink (transform-safe), closes on an outside click or on Esc, and re-provides the theme, the text scale and the DefaultTextStyle inside the entry. Use it in AppInput (as the picker inputs do) or on any other trigger.\",\n      \"pt\": \"Sem Material. Máquina de overlay dos pickers, desacoplada do input: recebe um builder de trigger e um builder de painel (ambos com um AppPickerHandle p/ open/close/toggle/rebuild), ancora via LayerLink (transform-safe), fecha ao clicar fora ou no Esc, e reprovê tema, text scale e DefaultTextStyle dentro da entry. Use no AppInput (como os picker inputs) ou em qualquer outro trigger.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Opening an AppDatePicker/AppTimePicker/AppColorPickerPanel from any widget (a field, a button, a chip…).\",\n        \"Building a new \\\"picker input\\\" by reusing the overlay machine.\"\n      ],\n      \"pt\": [\n        \"Abrir um AppDatePicker/AppTimePicker/AppColorPickerPanel a partir de qualquer widget (campo, botão, chip…).\",\n        \"Construir um novo \\\"picker input\\\" reaproveitando a máquina de overlay.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A rich-content balloon with an arrow → use AppPopover.\",\n        \"A list of selectable options → use AppDropdown.\",\n        \"A list of actions → use AppMenu.\"\n      ],\n      \"pt\": [\n        \"Balão de conteúdo rico com seta → use AppPopover.\",\n        \"Lista de opções selecionáveis → use AppDropdown.\",\n        \"Lista de ações → use AppMenu.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"trigger\",\n        \"type\": \"Widget Function(BuildContext, AppPickerHandle)\",\n        \"required\": true,\n        \"description\": {\n          \"en\": \"Builds the trigger; call handle.open/close/toggle.\",\n          \"pt\": \"Constrói o trigger; chame handle.open/close/toggle.\"\n        }\n      },\n      {\n        \"name\": \"panel\",\n        \"type\": \"Widget Function(BuildContext, AppPickerHandle)\",\n        \"required\": true,\n        \"description\": {\n          \"en\": \"The panel's content inside the AppCard.\",\n          \"pt\": \"Conteúdo do painel dentro do AppCard.\"\n        }\n      },\n      {\n        \"name\": \"width\",\n        \"type\": \"AppPickerWidth\",\n        \"required\": false,\n        \"default\": \"matchTrigger()\",\n        \"description\": {\n          \"en\": \"matchTrigger({min}) matches the trigger; fixed(w) pins it.\",\n          \"pt\": \"matchTrigger({min}) casa com o trigger; fixed(w) fixa.\"\n        }\n      },\n      {\n        \"name\": \"placement\",\n        \"type\": \"AppOverlayPlacement\",\n        \"required\": false,\n        \"default\": \"bottomStart\",\n        \"enumValues\": [\n          \"bottomStart\",\n          \"bottomCenter\",\n          \"bottomEnd\",\n          \"topStart\",\n          \"topCenter\",\n          \"topEnd\"\n        ]\n      },\n      {\n        \"name\": \"panelStyle\",\n        \"type\": \"AppStyle\",\n        \"required\": false,\n        \"default\": \"elevated\",\n        \"enumValues\": [\n          \"filled\",\n          \"outlined\",\n          \"elevated\"\n        ]\n      },\n      {\n        \"name\": \"panelGlass\",\n        \"type\": \"bool?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"The panel's glass axis (real glass through AppOverlayPanel). null follows the global glassTheme.\",\n          \"pt\": \"Eixo glass do painel (vidro real via AppOverlayPanel). null segue o global glassTheme.\"\n        }\n      },\n      {\n        \"name\": \"panelAccentColor\",\n        \"type\": \"Color?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"panelPadding\",\n        \"type\": \"EdgeInsetsGeometry\",\n        \"required\": false,\n        \"default\": \"EdgeInsets.all(s8)\"\n      }\n    ],\n    \"states\": [\n      \"closed\",\n      \"open\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Date picker from a button\",\n          \"pt\": \"Date picker a partir de um botão\"\n        },\n        \"code\": \"AppPickerAnchor(trigger: (c, h) => AppButton(label: \\\"Data\\\", onPressed: h.open), panel: (c, h) => AppDatePicker(onDateSelected: (d) { setState(() => _date = d); h.close(); }))\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Call handle.close() in the panel's callback when the choice is one-shot (e.g. a date); leave it open for continuous adjustment (e.g. the time wheels).\",\n        \"Use width.matchTrigger(min:) for fields and width.fixed() for panels with a width of their own (e.g. the color picker).\"\n      ],\n      \"pt\": [\n        \"Chame handle.close() no callback do painel quando a escolha for pontual (ex.: data); deixe aberto p/ ajustes contínuos (ex.: rodas de hora).\",\n        \"Use width.matchTrigger(min:) p/ campos e width.fixed() p/ painéis de largura própria (ex.: color picker).\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not rebuild OverlayEntry/CompositedTransformFollower by hand — that is what this component encapsulates.\"\n      ],\n      \"pt\": [\n        \"Não recrie OverlayEntry/CompositedTransformFollower à mão — é o que este componente encapsula.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Closes on Esc and on an outside click (a TapRegion with a groupId — touching the trigger does not close it). The trigger must carry its own semantics.\",\n      \"pt\": \"Fecha no Esc e ao clicar fora (TapRegion com groupId — tocar o trigger não fecha). O trigger deve ter semântica própria.\"\n    },\n    \"crossPlatform\": false,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_popover\",\n      \"app_menu\",\n      \"app_card\",\n      \"app_date_picker\",\n      \"app_time_picker\"\n    ]\n  },\n  {\n    \"id\": \"app_popover\",\n    \"name\": \"AppPopover\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Rich-content overlay anchored to a trigger (click or hover).\",\n      \"pt\": \"Overlay de conteúdo rico ancorado a um trigger (clique ou hover).\"\n    },\n    \"description\": {\n      \"en\": \"No Material. Opens a panel (with a title, content and optional actions) anchored to the trigger through a LayerLink (transform-safe), with an arrow pointing at the target. Closes on an outside click or on Esc. Re-provides the theme inside the Overlay.\",\n      \"pt\": \"Sem Material. Abre um painel (com título, conteúdo e ações opcionais) ancorado ao trigger via LayerLink (transform-safe), com seta apontando para o alvo. Fecha ao clicar fora ou no Esc. Reprovê o tema dentro do Overlay.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Rich details or help that appear on demand (more than a tooltip).\",\n        \"Small forms or light confirmations anchored to a control.\"\n      ],\n      \"pt\": [\n        \"Detalhes/ajuda ricos que aparecem sob demanda (mais que um tooltip).\",\n        \"Pequenos formulários ou confirmações leves ancorados a um controle.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Just a short piece of hover text → use AppTooltip.\",\n        \"Selecting from a list of options → use AppDropdown.\",\n        \"A menu's list of actions → use AppMenu.\"\n      ],\n      \"pt\": [\n        \"Só um texto curto de hover → use AppTooltip.\",\n        \"Seleção de uma lista de opções → use AppDropdown.\",\n        \"Lista de ações de um menu → use AppMenu.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"trigger\",\n        \"type\": \"Widget\",\n        \"required\": true\n      },\n      {\n        \"name\": \"child\",\n        \"type\": \"Widget\",\n        \"required\": true\n      },\n      {\n        \"name\": \"title\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"actions\",\n        \"type\": \"List<Widget>?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"placement\",\n        \"type\": \"AppOverlayPlacement\",\n        \"required\": false,\n        \"default\": \"bottomCenter\",\n        \"enumValues\": [\n          \"bottomStart\",\n          \"bottomCenter\",\n          \"bottomEnd\",\n          \"topStart\",\n          \"topCenter\",\n          \"topEnd\"\n        ]\n      },\n      {\n        \"name\": \"showArrow\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppStyle?\",\n        \"required\": false,\n        \"default\": \"elevated\",\n        \"description\": {\n          \"en\": \"The balloon's container; defaults to elevated (it does not follow the global).\",\n          \"pt\": \"Container do balão; default elevated (não segue o global).\"\n        },\n        \"enumValues\": [\n          \"filled\",\n          \"outlined\",\n          \"elevated\"\n        ]\n      },\n      {\n        \"name\": \"radiusMode\",\n        \"type\": \"AppRadiusMode?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"radius\",\n        \"type\": \"BorderRadius?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"triggerMode\",\n        \"type\": \"AppPopoverTrigger\",\n        \"required\": false,\n        \"default\": \"click\",\n        \"enumValues\": [\n          \"click\",\n          \"hover\"\n        ]\n      },\n      {\n        \"name\": \"maxWidth\",\n        \"type\": \"double?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"controller\",\n        \"type\": \"AppPopoverController?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"closed\",\n      \"open\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Help anchored to an icon\",\n          \"pt\": \"Ajuda ancorada a um ícone\"\n        },\n        \"code\": \"AppPopover(trigger: AppIcon(AppIconToken.info), title: \\\"Score\\\", child: AppText(\\\"Combina frenagens, curvas e velocidade.\\\"))\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use a passive trigger (an icon, some text); the popover is what makes it actionable.\"\n      ],\n      \"pt\": [\n        \"Use um trigger passivo (ícone/texto); o popover é quem o torna acionável.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not put essential content only in a hover-mode popover (touch has no hover).\"\n      ],\n      \"pt\": [\n        \"Não coloque conteúdo essencial só no popover no modo hover (toque não tem hover).\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"The panel opens with a fade+pop and honors reduce-motion. Esc closes it. The trigger must carry its own semantics (e.g. an AppIcon with a semanticLabel).\",\n      \"pt\": \"O painel abre com fade+pop e respeita reduce-motion. Fecha no Esc. O trigger deve ter semântica própria (ex.: AppIcon com semanticLabel).\"\n    },\n    \"crossPlatform\": false,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_tooltip\",\n      \"app_card\",\n      \"app_menu\"\n    ]\n  },\n  {\n    \"id\": \"app_rating\",\n    \"name\": \"AppRating\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Star rating (display and input), with an optional half step.\",\n      \"pt\": \"Avaliação por estrelas (display e input), com meio-passo opcional.\"\n    },\n    \"description\": {\n      \"en\": \"The star is painted (CustomPainter) — deterministic, with no network icon. Read-only when onChanged is null; otherwise click and keyboard set the value.\",\n      \"pt\": \"A estrela é pintada (CustomPainter) — determinística, sem ícone de rede. Somente-leitura quando onChanged é nulo; senão clique/teclado definem o valor.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Showing or capturing a score (satisfaction, quality, a 0–5 rating).\"\n      ],\n      \"pt\": [\n        \"Mostrar ou capturar uma nota (satisfação, qualidade, score de 0–5).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A wide numeric scale → use a slider or a numeric field.\",\n        \"Progress or measurement → use a determinate AppLinearLoading.\"\n      ],\n      \"pt\": [\n        \"Escala numérica ampla → use um slider ou campo numérico.\",\n        \"Progresso/medição → use AppLinearLoading determinado.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"value\",\n        \"type\": \"double\",\n        \"required\": true\n      },\n      {\n        \"name\": \"onChanged\",\n        \"type\": \"ValueChanged<double>?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"count\",\n        \"type\": \"int\",\n        \"required\": false,\n        \"default\": \"5\"\n      },\n      {\n        \"name\": \"allowHalf\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      },\n      {\n        \"name\": \"iconSize\",\n        \"type\": \"double\",\n        \"required\": false,\n        \"default\": \"AppSizes.s24\"\n      },\n      {\n        \"name\": \"spacing\",\n        \"type\": \"double\",\n        \"required\": false,\n        \"default\": \"AppSpacings.s2\"\n      },\n      {\n        \"name\": \"color\",\n        \"type\": \"Color?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"empty\",\n      \"partial\",\n      \"full\",\n      \"read-only\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Input with half stars\",\n          \"pt\": \"Input com meia-estrela\"\n        },\n        \"code\": \"AppRating(value: 3.5, allowHalf: true, onChanged: (v) => setRating(v))\"\n      },\n      {\n        \"title\": {\n          \"en\": \"Read-only\",\n          \"pt\": \"Somente-leitura\"\n        },\n        \"code\": \"AppRating(value: 4)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use it for short scores (0–5); turn allowHalf on for granularity.\"\n      ],\n      \"pt\": [\n        \"Use para notas curtas (0–5); ative allowHalf p/ granularidade.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it for large scales or for progress.\"\n      ],\n      \"pt\": [\n        \"Não use para escalas grandes nem progresso.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Read-only exposes the value as a label. Interactive, it is a slider (onIncrease/onDecrease) driven by the arrow keys. The star is painted, with no network dependency.\",\n      \"pt\": \"Somente-leitura expõe o valor como rótulo. Interativo é um slider (onIncrease/onDecrease) com setas do teclado. Estrela pintada, sem dependência de rede.\"\n    },\n    \"crossPlatform\": false,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_linear_loading\"\n    ]\n  },\n  {\n    \"id\": \"app_segmented_button\",\n    \"name\": \"AppSegmentedButton\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Segmented button for single selection (2–4 options in a pill).\",\n      \"pt\": \"Botão segmentado de seleção única (2–4 opções numa pílula).\"\n    },\n    \"description\": {\n      \"en\": \"Mutually exclusive options of equal width: the selected one is a sliding pill (filled primary) that slides underneath the text when it changes. Inset style; in filled the track is a recessed well that stands out from the host surface.\",\n      \"pt\": \"Opções mutuamente exclusivas de largura igual: a selecionada é uma pílula deslizante (filled primary) que desliza por baixo do texto ao trocar. Estilo inset; no filled o trilho é um poço recuado que destaca da superfície-hospedeira.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Switching between a few views or modes (Day/Week/Month, Streets/Satellite).\",\n        \"A binary or ternary filter that stays visible.\"\n      ],\n      \"pt\": [\n        \"Alternar entre poucas visões/modos (Dia/Semana/Mês, Ruas/Satélite).\",\n        \"Filtro binário/ternário sempre visível.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Many options (>4) → use AppDropdown.\",\n        \"Multiple selection → use AppMultiSelect or checkboxes.\"\n      ],\n      \"pt\": [\n        \"Muitas opções (>4) → use AppDropdown.\",\n        \"Seleção múltipla → use AppMultiSelect ou checkboxes.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"segments\",\n        \"type\": \"List<AppSegment<T>>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"value\",\n        \"type\": \"T\",\n        \"required\": true\n      },\n      {\n        \"name\": \"onChanged\",\n        \"type\": \"ValueChanged<T>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"size\",\n        \"type\": \"AppButtonSize\",\n        \"required\": false,\n        \"default\": \"m\"\n      },\n      {\n        \"name\": \"enabled\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"expanded\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      }\n    ],\n    \"states\": [\n      \"selected\",\n      \"unselected\",\n      \"hovered\",\n      \"focused\",\n      \"disabled\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Map mode\",\n          \"pt\": \"Modo do mapa\"\n        },\n        \"code\": \"AppSegmentedButton<MapMode>(value: mode, onChanged: setMode, segments: [AppSegment(value: MapMode.street, label: \\\"Ruas\\\"), AppSegment(value: MapMode.satellite, label: \\\"Satélite\\\")])\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use 2–4 short options; a label and/or an icon per segment.\"\n      ],\n      \"pt\": [\n        \"Use 2–4 opções curtas; rótulo e/ou ícone por segmento.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it for multiple selection or for long lists.\"\n      ],\n      \"pt\": [\n        \"Não use para seleção múltipla nem listas longas.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Each segment is a mutually exclusive toggle (AppSemantics.toggle). Keyboard: Tab and the ←/→ arrows navigate; Enter/Space selects. The pill slides while honoring reduce-motion.\",\n      \"pt\": \"Cada segmento é um toggle mutuamente exclusivo (AppSemantics.toggle). Teclado: Tab e setas ←/→ navegam; Enter/Espaço seleciona. A pílula desliza respeitando reduce-motion.\"\n    },\n    \"crossPlatform\": false,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_button\",\n      \"app_radio\",\n      \"app_dropdown\"\n    ]\n  },\n  {\n    \"id\": \"app_split_button\",\n    \"name\": \"AppSplitButton\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Primary action + a caret that opens an AppMenu of secondary actions.\",\n      \"pt\": \"Ação primária + caret que abre um AppMenu de ações secundárias.\"\n    },\n    \"description\": {\n      \"en\": \"Follows AppButton's global rules: it varies along the AppStyle axis (filled/outlined/elevated) and reuses the design system's button color model. The primary segment fires the default action; the caret opens the alternatives in an AppMenu.\",\n      \"pt\": \"Segue as regras globais do AppButton: varia pelo eixo AppStyle (filled/outlined/elevated) e reusa o modelo de cor dos botões do DS. O segmento primário dispara a ação padrão; o caret abre as ações alternativas num AppMenu.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"One default action with related variations (Save / Save and exit).\",\n        \"Cutting the visual noise of several actions from the same group.\"\n      ],\n      \"pt\": [\n        \"Uma ação padrão com variações relacionadas (Salvar / Salvar e sair).\",\n        \"Reduzir a poluição visual de várias ações de mesmo grupo.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Unrelated actions → use separate buttons or an AppMenu.\",\n        \"A single action → use AppButton.\"\n      ],\n      \"pt\": [\n        \"Ações não relacionadas → use botões separados ou um AppMenu.\",\n        \"Uma única ação → use AppButton.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"label\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"onPressed\",\n        \"type\": \"VoidCallback?\",\n        \"required\": true\n      },\n      {\n        \"name\": \"menuEntries\",\n        \"type\": \"List<AppMenuEntry>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppStyle?\",\n        \"required\": false,\n        \"enumValues\": [\n          \"filled\",\n          \"outlined\",\n          \"elevated\"\n        ]\n      },\n      {\n        \"name\": \"color\",\n        \"type\": \"AppButtonColor\",\n        \"required\": false,\n        \"default\": \"primary\"\n      },\n      {\n        \"name\": \"size\",\n        \"type\": \"AppButtonSize\",\n        \"required\": false,\n        \"default\": \"l\"\n      },\n      {\n        \"name\": \"icon\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"enabled\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"loading\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      },\n      {\n        \"name\": \"radiusMode\",\n        \"type\": \"AppRadiusMode?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"radius\",\n        \"type\": \"BorderRadius?\",\n        \"required\": false\n      }\n    ],\n    \"variants\": [\n      \"filled\",\n      \"outlined\",\n      \"elevated\"\n    ],\n    \"states\": [\n      \"enabled\",\n      \"hovered\",\n      \"pressed\",\n      \"focused\",\n      \"disabled\",\n      \"loading\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Save with variations\",\n          \"pt\": \"Salvar com variações\"\n        },\n        \"code\": \"AppSplitButton(label: \\\"Salvar\\\", onPressed: save, menuEntries: [AppMenuItem(label: \\\"Salvar e sair\\\", onPressed: saveAndExit)])\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use the caret for variations of the SAME primary action.\"\n      ],\n      \"pt\": [\n        \"Use o caret para variações da MESMA ação primária.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not put unrelated actions in the caret.\"\n      ],\n      \"pt\": [\n        \"Não junte ações não relacionadas no caret.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Two button nodes (primary + a \\\"More actions\\\" caret), both real FlocksInteraction: Tab focus with a dedicated ring, Enter/Space activate. The caret opens an AppMenu with keyboard navigation and Esc. Press-scale and highlight honor reduce-motion.\",\n      \"pt\": \"Dois nós de botão (primário + caret \\\"Mais ações\\\"), ambos FlocksInteraction reais: foco por Tab com anel dedicado, Enter/Space acionam. O caret abre um AppMenu com navegação por teclado e Esc. Press-scale/realce respeitam reduce-motion.\"\n    },\n    \"crossPlatform\": false,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_button\",\n      \"app_menu\"\n    ]\n  },\n  {\n    \"id\": \"app_snackbar\",\n    \"name\": \"AppSnackbar\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Temporary feedback card (success/error/info).\",\n      \"pt\": \"Card de feedback temporário (sucesso/erro/info).\"\n    },\n    \"description\": {\n      \"en\": \"A card with a title, a description and a semantic icon (error/info/success) over a surfaceContainer tinted by the kind's color. The container follows the AppStyle axis (`elevated` by default); the shape follows the radius axis. Show it through `showAppSnackbar` (bottom-right corner, auto-dismiss, single instance, slide-in). Colors 100% from the theme; announced (liveRegion).\",\n      \"pt\": \"Card com título, descrição e ícone semântico (error/info/success) sobre surfaceContainer tingido pela cor do tipo. Container segue o eixo AppStyle (default `elevated`); forma pelo eixo de raio. Exiba via `showAppSnackbar` (canto inferior direito, auto-dismiss, instância única, slide-in). Cores 100% do tema; anunciado (liveRegion).\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Confirming a quick action (saved, deleted) without blocking the flow.\",\n        \"Warning about a transient operation error.\"\n      ],\n      \"pt\": [\n        \"Confirmar uma ação rápida (salvo, excluído) sem bloquear o fluxo.\",\n        \"Avisar de um erro transitório de operação.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Feedback that requires acknowledgement or an action → AppDialog.\",\n        \"A persistent inline notice on the page → AppAlert.\"\n      ],\n      \"pt\": [\n        \"Feedback que exige reconhecimento/ação → AppDialog.\",\n        \"Aviso inline persistente na página → AppAlert.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"title\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"description\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"type\",\n        \"type\": \"AppSnackbarType\",\n        \"required\": true,\n        \"enumValues\": [\n          \"error\",\n          \"info\",\n          \"success\"\n        ]\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppStyle?\",\n        \"required\": false,\n        \"default\": \"AppStyle.elevated\",\n        \"enumValues\": [\n          \"filled\",\n          \"outlined\",\n          \"elevated\"\n        ]\n      },\n      {\n        \"name\": \"radiusMode\",\n        \"type\": \"AppRadiusMode?\",\n        \"required\": false\n      }\n    ],\n    \"variants\": [\n      \"error\",\n      \"info\",\n      \"success\"\n    ],\n    \"states\": [\n      \"default\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Success\",\n          \"pt\": \"Sucesso\"\n        },\n        \"code\": \"showAppSnackbar(context: context, title: 'Salvo', description: '...', type: AppSnackbarType.success)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Short messages; the card disappears on its own after the duration.\",\n        \"Use the kind that matches the message (error/info/success).\"\n      ],\n      \"pt\": [\n        \"Mensagens curtas; o card some sozinho após a duração.\",\n        \"Use o tipo que casa com a mensagem (error/info/success).\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not stack several snackbars (a new one replaces the previous).\"\n      ],\n      \"pt\": [\n        \"Não empilhe várias snackbars (a nova substitui a anterior).\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Wrapped in AppSemantics.liveRegion → announced when it appears. Title in onSurface and description in neutral s700 over the tinted background both pass AA; border and icon (semantic color) ≥ 3:1.\",\n      \"pt\": \"Embrulhado em AppSemantics.liveRegion → anunciado ao surgir. Título onSurface e descrição neutro s700 sobre o fundo tingido passam AA; borda e ícone (cor semântica) ≥ 3:1.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_alert\",\n      \"app_dialog\"\n    ]\n  },\n  {\n    \"id\": \"app_surface\",\n    \"name\": \"AppSurface\",\n    \"category\": \"atom\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Themeable base container (surface) with elevation by tone.\",\n      \"pt\": \"Container-base temável (superfície) com elevação por tom.\"\n    },\n    \"description\": {\n      \"en\": \"Standardizes the container pattern with surface color + radius + border, read from the theme. Elevation comes from the variant's tone (surface → surfaceContainer), not from a shadow.\",\n      \"pt\": \"Padroniza o padrão de container com cor de superfície + raio + borda, lido do tema. A elevação vem do variant por tom (surface → surfaceContainer), não por sombra.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"A card, a panel, a menu item, the body of a sheet or dialog.\"\n      ],\n      \"pt\": [\n        \"Card, painel, item de menu, corpo de sheet/dialog.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Spacing alone with no background → Padding/Column.\",\n        \"A clickable target → compose it with AppInteraction.\"\n      ],\n      \"pt\": [\n        \"Só espaçamento sem fundo → Padding/Column.\",\n        \"Alvo clicável → componha com AppInteraction.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"child\",\n        \"type\": \"Widget\",\n        \"required\": true,\n        \"description\": {\n          \"en\": \"Surface content.\",\n          \"pt\": \"Conteúdo da superfície.\"\n        }\n      },\n      {\n        \"name\": \"variant\",\n        \"type\": \"AppSurfaceVariant\",\n        \"required\": false,\n        \"default\": \"AppSurfaceVariant.flat\",\n        \"description\": {\n          \"en\": \"Elevation level by tone.\",\n          \"pt\": \"Nível de elevação por tom.\"\n        },\n        \"enumValues\": [\n          \"flat\",\n          \"raised\",\n          \"bordered\"\n        ]\n      },\n      {\n        \"name\": \"padding\",\n        \"type\": \"EdgeInsetsGeometry\",\n        \"required\": false,\n        \"default\": \"EdgeInsets.zero\"\n      },\n      {\n        \"name\": \"radius\",\n        \"type\": \"BorderRadius?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Default: the global radius (round mode), content-sized.\",\n          \"pt\": \"Default: radius global (modo redondo), content-sized.\"\n        }\n      },\n      {\n        \"name\": \"color\",\n        \"type\": \"Color?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"border\",\n        \"type\": \"BoxBorder?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"clip\",\n        \"type\": \"Clip\",\n        \"required\": false,\n        \"default\": \"Clip.antiAlias\"\n      }\n    ],\n    \"variants\": [\n      \"flat\",\n      \"raised\",\n      \"bordered\"\n    ],\n    \"states\": [\n      \"default\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Elevated card\",\n          \"pt\": \"Card elevado\"\n        },\n        \"code\": \"AppSurface(variant: AppSurfaceVariant.raised, padding: const EdgeInsets.all(AppSpacings.s16), child: content)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use raised to elevate; let the color come from the theme.\",\n        \"Compose cards, menus and sheets on top of AppSurface.\"\n      ],\n      \"pt\": [\n        \"Use raised para elevar; deixe a cor vir do tema.\",\n        \"Componha cards/menus/sheets sobre AppSurface.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not add a boxShadow to elevate — raise the variant instead.\"\n      ],\n      \"pt\": [\n        \"Não adicione boxShadow para elevar — suba o variant.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Semantically neutral: it passes the child through. The tone separation of raised/bordered satisfies UI contrast.\",\n      \"pt\": \"Neutro em semântica: repassa o child. A separação de tom do raised/bordered satisfaz o contraste de UI.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_interaction\",\n      \"app_divider\"\n    ]\n  },\n  {\n    \"id\": \"app_scroll_edge_fade\",\n    \"name\": \"AppScrollEdgeFade\",\n    \"category\": \"atom\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Fades the edge of scrolling content, so the cut against a fixed bar is not a hard line.\",\n      \"pt\": \"Esmaece a borda do conteúdo que rola, para o corte contra uma barra fixa não ser uma linha seca.\"\n    },\n    \"description\": {\n      \"en\": \"The veil runs from the surface color (100%) to transparent (0%), and only on the side where hidden content actually exists: when no scrolling is possible nothing is painted — a permanent gradient would suggest content that is not there, which is the opposite of what the affordance is for. It is passive (IgnorePointer over the veil), so touches still reach the content underneath. A descendant that already handles its own veil announces itself with AppScrollEdgeFadeOwner and switches this one off.\",\n      \"pt\": \"O véu vai da cor da superfície (100%) até transparente (0%), e só do lado em que existe conteúdo escondido: quando não há rolagem possível, nada é pintado — um degradê permanente sugeriria conteúdo que não existe, que é o oposto do que a affordance serve para dizer. É passivo (IgnorePointer sobre o véu), então o toque continua chegando ao conteúdo por baixo. Um descendente que já cuide do próprio véu se anuncia com AppScrollEdgeFadeOwner e desliga este.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Scrollable content cut off by a fixed header/footer (sheets, panels).\",\n        \"Horizontal lists that continue past the visible edge.\"\n      ],\n      \"pt\": [\n        \"Conteúdo rolável cortado por um header/footer fixo (sheets, painéis).\",\n        \"Listas horizontais que continuam além da borda visível.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"An explicit separation between regions → AppDivider.\",\n        \"Content that does not scroll: the veil never appears, but the wrapper is dead weight.\"\n      ],\n      \"pt\": [\n        \"Separação explícita entre regiões → AppDivider.\",\n        \"Conteúdo que não rola: o véu não nasce, mas o wrapper é peso morto.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"child\",\n        \"type\": \"Widget\",\n        \"required\": true,\n        \"description\": {\n          \"en\": \"The scrollable content.\",\n          \"pt\": \"O conteúdo rolável.\"\n        }\n      },\n      {\n        \"name\": \"color\",\n        \"type\": \"Color?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"The color the gradient starts from. Defaults to surfaceContainer (cards, sheets, panels) — pass the real one when the surface differs, or the veil fades to the wrong color.\",\n          \"pt\": \"Cor de onde o degradê parte. Default surfaceContainer (cartões, sheets, painéis) — passe a real quando a superfície for outra, senão o véu desbota para a cor errada.\"\n        }\n      },\n      {\n        \"name\": \"extent\",\n        \"type\": \"double\",\n        \"required\": false,\n        \"default\": \"AppSpacings.s24\",\n        \"description\": {\n          \"en\": \"Height (or width) of the veil.\",\n          \"pt\": \"Altura (ou largura) do véu.\"\n        }\n      },\n      {\n        \"name\": \"axis\",\n        \"type\": \"Axis\",\n        \"required\": false,\n        \"default\": \"Axis.vertical\",\n        \"description\": {\n          \"en\": \"Axis of the observed scroll.\",\n          \"pt\": \"Eixo da rolagem observada.\"\n        }\n      }\n    ],\n    \"states\": [\n      \"no-scroll (nothing painted)\",\n      \"top-hidden\",\n      \"bottom-hidden\",\n      \"both\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Body of a sheet\",\n          \"pt\": \"Corpo de uma sheet\"\n        },\n        \"code\": \"AppScrollEdgeFade(child: SingleChildScrollView(child: body))\"\n      },\n      {\n        \"title\": {\n          \"en\": \"Over the surface, not over the card\",\n          \"pt\": \"Sobre a surface, não sobre o cartão\"\n        },\n        \"code\": \"AppScrollEdgeFade(\\n  color: theme.colorTheme.surface,\\n  child: list,\\n)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Pass `color` when the surface is not surfaceContainer.\",\n        \"Use AppScrollEdgeFadeOwner when something deeper already fades.\"\n      ],\n      \"pt\": [\n        \"Informe `color` quando a superfície não for surfaceContainer.\",\n        \"Use AppScrollEdgeFadeOwner quando algo mais fundo já esmaece.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not stack two veils on the same scroll — the outer one lands in the wrong place.\"\n      ],\n      \"pt\": [\n        \"Não empilhe dois véus no mesmo scroll — o de fora cai no lugar errado.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Purely visual and non-interactive (IgnorePointer): it neither enters the semantics tree nor intercepts touches, so keyboard and screen-reader scrolling behave exactly as before.\",\n      \"pt\": \"Puramente visual e não interativo (IgnorePointer): não entra na árvore semântica nem intercepta toque, então a rolagem por teclado e por leitor de tela continua igual.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_scroll_edge_fade_owner\",\n      \"app_divider\"\n    ]\n  },\n  {\n    \"id\": \"app_scroll_edge_fade_owner\",\n    \"name\": \"AppScrollEdgeFadeOwner\",\n    \"category\": \"atom\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Takes over the veil for its own area: switches off the ancestor AppScrollEdgeFade while it is mounted.\",\n      \"pt\": \"Assume o véu da própria área: desliga o AppScrollEdgeFade ancestral enquanto estiver montado.\"\n    },\n    \"description\": {\n      \"en\": \"A component that scrolls internally (tabs, stacked panels) already fades its own content — but the outer AppScrollEdgeFade keeps listening to the SAME scroll and paints its veil at the edge of the whole area, which is not the edge of the content there: in a sheet with tabs, the gradient fell over the tab bar. This marker says \\\"from here inward the veil is mine\\\". With no AppScrollEdgeFade above, it is a pass-through — mounting it on its own is not an error.\",\n      \"pt\": \"Um componente que rola por dentro (abas, painéis empilhados) já esmaece o próprio conteúdo — mas o AppScrollEdgeFade de fora continua ouvindo a MESMA rolagem e pinta o véu dele na borda da área inteira, que ali não é a borda do conteúdo: numa sheet com abas, o degradê caía por cima da barra de abas. Este marcador diz \\\"daqui para dentro o véu é meu\\\". Sem um AppScrollEdgeFade acima, é um passa-through — montá-lo solto não é erro.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Inside an AppScrollEdgeFade, when the subtree has a veil of its own.\",\n        \"Components with tabs or stacked panels that scroll independently.\"\n      ],\n      \"pt\": [\n        \"Dentro de um AppScrollEdgeFade, quando a subárvore tem o próprio véu.\",\n        \"Componentes com abas ou painéis empilhados que rolam por conta própria.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"To hide the veil because you dislike it: if it is in the wrong place, the problem is where the AppScrollEdgeFade was mounted.\"\n      ],\n      \"pt\": [\n        \"Para esconder o véu por gosto: se ele está no lugar errado, o problema é onde o AppScrollEdgeFade foi montado.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"child\",\n        \"type\": \"Widget\",\n        \"required\": true,\n        \"description\": {\n          \"en\": \"Content that handles its own fading.\",\n          \"pt\": \"Conteúdo que cuida do próprio esmaecimento.\"\n        }\n      }\n    ],\n    \"states\": [\n      \"with-ancestor (switches off)\",\n      \"without-ancestor (pass-through)\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Tabs inside a sheet\",\n          \"pt\": \"Abas dentro de uma sheet\"\n        },\n        \"code\": \"AppScrollEdgeFadeOwner(\\n  child: Column(\\n    children: <Widget>[\\n      tabBar,\\n      Expanded(child: AppScrollEdgeFade(child: content)),\\n    ],\\n  ),\\n)\",\n        \"description\": {\n          \"en\": \"Switches off the outer veil (which would fall over the tab bar) and lets the inner one handle the real content.\",\n          \"pt\": \"Desliga o véu de fora (que cairia sobre a barra de abas) e deixa o de dentro cuidar do conteúdo real.\"\n        }\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Mount it as high as possible inside the region it covers.\"\n      ],\n      \"pt\": [\n        \"Monte-o o mais alto possível dentro da região que ele cobre.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it as a way to switch the veil off without replacing it.\"\n      ],\n      \"pt\": [\n        \"Não use como forma de desligar o véu sem substituí-lo.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Renders nothing: it is pure coordination between two veils, so it does not alter the semantics tree.\",\n      \"pt\": \"Não renderiza nada: é só coordenação entre dois véus, então não altera a árvore semântica.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_scroll_edge_fade\"\n    ]\n  },\n  {\n    \"id\": \"app_side_inset\",\n    \"name\": \"AppSideInset\",\n    \"category\": \"atom\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Applies — and consumes — the side inset the host surface published in MediaQuery.padding.\",\n      \"pt\": \"Aplica — e consome — o respiro lateral que a superfície hospedeira publicou em MediaQuery.padding.\"\n    },\n    \"description\": {\n      \"en\": \"A side sheet reserves a lateral strip (the drag gutter lives there). It PUBLISHES that reservation in MediaQuery.padding instead of insetting the content with a Padding, because insetting the whole strip would also inset the VIEWPORT of any scroll inside it — and the scrollbar, which lives at the viewport's edge, ended up floating far from the sheet's side. Published, whatever scrolls adds the inset to its own scrollable padding: the content breathes, the viewport reaches the edge, the scrollbar sits against it. This widget is the shortcut for content that does NOT scroll — it applies the same inset as ordinary padding and REMOVES it from the MediaQuery, so nothing below applies it twice.\",\n      \"pt\": \"O side sheet reserva uma faixa lateral (a gutter de arraste mora ali). Ele PUBLICA essa reserva em MediaQuery.padding em vez de recuar o conteúdo com um Padding, porque recuar a faixa inteira recuaria junto o VIEWPORT de qualquer rolagem lá dentro — e a barra de rolagem, que mora na borda do viewport, aparecia flutuando longe da lateral da sheet. Publicado, quem rola soma o recuo ao padding do próprio scrollable: o conteúdo respira, o viewport vai até a borda, a barra encosta. Este widget é o atalho para o conteúdo que NÃO rola — aplica o mesmo recuo como padding comum e o REMOVE do MediaQuery, para ninguém abaixo aplicar de novo.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Non-scrolling content inside a side sheet (header, footer, short form).\"\n      ],\n      \"pt\": [\n        \"Conteúdo não-rolável dentro de um side sheet (cabeçalho, rodapé, form curto).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Content that SCROLLS → add MediaQuery.paddingOf(context) to the scrollable's padding; otherwise the scrollbar detaches from the side.\",\n        \"Fixed layout breathing room → a Padding with an AppSpacings token.\"\n      ],\n      \"pt\": [\n        \"Conteúdo que ROLA → some MediaQuery.paddingOf(context) ao padding do scrollable; senão a barra de rolagem descola da lateral.\",\n        \"Respiro fixo de layout → Padding com token de AppSpacings.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"child\",\n        \"type\": \"Widget\",\n        \"required\": true,\n        \"description\": {\n          \"en\": \"Non-scrollable content that takes the side inset.\",\n          \"pt\": \"Conteúdo não-rolável que recebe o recuo lateral.\"\n        }\n      }\n    ],\n    \"states\": [\n      \"no-published-inset (pass-through)\",\n      \"with-inset (applies and consumes)\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Footer of a side sheet\",\n          \"pt\": \"Rodapé de um side sheet\"\n        },\n        \"code\": \"AppSideInset(child: AppButtonsFooter(primary: saveButton))\"\n      },\n      {\n        \"title\": {\n          \"en\": \"What to do when the content scrolls\",\n          \"pt\": \"O que fazer quando o conteúdo rola\"\n        },\n        \"code\": \"// NÃO use AppSideInset aqui:\\nListView(\\n  padding: EdgeInsets.symmetric(\\n    horizontal: MediaQuery.paddingOf(context).left,\\n  ),\\n  children: rows,\\n)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use it on content that does not scroll; let the scrollable add the padding itself.\"\n      ],\n      \"pt\": [\n        \"Use em conteúdo que não rola; deixe o scrollable somar o padding sozinho.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not nest two: the outer one consumes the inset and the inner one becomes a no-op — silent, but a sign the layout is duplicating a responsibility.\"\n      ],\n      \"pt\": [\n        \"Não aninhe dois: o de fora consome o recuo e o de dentro vira no-op — silencioso, mas sinal de que o layout está duplicando responsabilidade.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Does not change the semantics tree: it is only padding. Because it consumes the MediaQuery value, it avoids the doubled inset that would push touch targets outside the comfortable area.\",\n      \"pt\": \"Não muda a árvore semântica: é só padding. Como consome o valor do MediaQuery, evita o recuo dobrado que empurraria alvos de toque para fora da área confortável.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_side_sheet\",\n      \"app_scroll_edge_fade\"\n    ]\n  },\n  {\n    \"id\": \"app_shortcut_hint\",\n    \"name\": \"AppShortcutHint\",\n    \"category\": \"atom\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Badge that SHOWS a keyboard shortcut, resolved per platform.\",\n      \"pt\": \"Selo que MOSTRA um atalho de teclado, resolvido por plataforma.\"\n    },\n    \"description\": {\n      \"en\": \"A shortcut nobody sees goes unused: the badge is what makes it discoverable without requiring documentation. It takes an AppShortcut (a platform-independent description) and resolves it at paint time — `usesPrimaryModifier` becomes ⌘ on macOS and Ctrl everywhere else, because teaching the wrong key is worse than showing nothing. It is DECORATIVE: it takes no pointer input; whoever wants the action clickable puts the badge inside the control itself. The color comes from a legible `secondary` stop against the surface it was told about — and, inside a painted control, from the AppShortcutHintColor that control installs with its own foreground.\",\n      \"pt\": \"Um atalho que ninguém vê não é usado: o selo é o que o torna descoberto sem exigir documentação. Recebe um AppShortcut (descrição independente de plataforma) e o resolve na hora de desenhar — `usesPrimaryModifier` vira ⌘ no macOS e Ctrl no resto, porque ensinar a tecla errada é pior do que não mostrar nada. É DECORATIVO: não recebe toque; quem quer a ação clicável põe o selo dentro do próprio controle. A cor sai de um stop legível de `secondary` contra a superfície informada — e, dentro de um controle pintado, do AppShortcutHintColor que o controle instala com o próprio foreground.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Showing the shortcut at the right edge of a field, button, tab or menu item.\",\n        \"Teaching a new shortcut without needing a tour or documentation.\"\n      ],\n      \"pt\": [\n        \"Mostrar o atalho no canto direito de um campo, botão, aba ou item de menu.\",\n        \"Ensinar um atalho novo sem precisar de tour ou documentação.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Registering the actual shortcut → AppShortcutsScope/Shortcuts. The badge only draws.\",\n        \"A generic label in a pill → AppBadge.\"\n      ],\n      \"pt\": [\n        \"Registrar o atalho de verdade → AppShortcutsScope/Shortcuts. O selo só desenha.\",\n        \"Rótulo genérico em pílula → AppBadge.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"shortcut\",\n        \"type\": \"AppShortcut\",\n        \"required\": true,\n        \"description\": {\n          \"en\": \"Shortcut description (key + modifiers), independent of the OS.\",\n          \"pt\": \"Descrição do atalho (tecla + modificadores), independente de SO.\"\n        }\n      },\n      {\n        \"name\": \"size\",\n        \"type\": \"AppShortcutHintSize\",\n        \"required\": false,\n        \"default\": \"AppShortcutHintSize.s\",\n        \"description\": {\n          \"en\": \"s inside fields and chips; m in headers and bars.\",\n          \"pt\": \"s dentro de campos e chips; m em cabeçalhos e barras.\"\n        },\n        \"enumValues\": [\n          \"s\",\n          \"m\"\n        ]\n      },\n      {\n        \"name\": \"color\",\n        \"type\": \"Color?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Overrides the text and the badge. Default: a legible secondary stop.\",\n          \"pt\": \"Override do texto e do selo. Default: stop legível de secondary.\"\n        }\n      },\n      {\n        \"name\": \"background\",\n        \"type\": \"Color?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"The surface the badge is set on — it is what picks the stop. Defaults to surfaceContainer; pass `surface` in the header and in the rail.\",\n          \"pt\": \"A superfície em que o selo é pousado — é ela que escolhe o stop. Default surfaceContainer; passe `surface` no header e no rail.\"\n        }\n      }\n    ],\n    \"variants\": [\n      \"s\",\n      \"m\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Platform shortcut in a search field\",\n          \"pt\": \"Atalho de plataforma num campo de busca\"\n        },\n        \"code\": \"AppOmniSearch(\\n  hintText: 'Buscar',\\n  shortcut: const AppShortcut.primary('K'),\\n  onSearch: search,\\n)\",\n        \"description\": {\n          \"en\": \"Shows ⌘K on macOS and Ctrl+K everywhere else.\",\n          \"pt\": \"Mostra ⌘K no macOS e Ctrl+K no resto.\"\n        }\n      },\n      {\n        \"title\": {\n          \"en\": \"Badge over the surface (header/rail)\",\n          \"pt\": \"Selo sobre a surface (header/rail)\"\n        },\n        \"code\": \"AppShortcutHint(\\n  const AppShortcut('/'),\\n  size: AppShortcutHintSize.m,\\n  background: theme.colorTheme.surface,\\n)\",\n        \"description\": {\n          \"en\": \"Naming the real surface matters: the stop computed against surfaceContainer disappears when the badge sits on surface.\",\n          \"pt\": \"Informar a superfície real importa: o stop calculado contra a surfaceContainer some quando o selo está sobre a surface.\"\n        }\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Pass `background` when the badge does not sit on surfaceContainer.\",\n        \"Use AppShortcut.primary for the platform's modifier.\"\n      ],\n      \"pt\": [\n        \"Passe `background` quando o selo não estiver sobre surfaceContainer.\",\n        \"Use AppShortcut.primary para o modificador da plataforma.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not write \\\"Ctrl+K\\\" in a String: on a Mac it teaches the wrong key.\",\n        \"Do not make the badge clickable — the action belongs to the control hosting it.\"\n      ],\n      \"pt\": [\n        \"Não escreva \\\"Ctrl+K\\\" numa String: no Mac ensina a tecla errada.\",\n        \"Não torne o selo clicável — a ação é do controle que o hospeda.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"A single node labelled \\\"Shortcut: Command K\\\" (excludeSemantics), with the modifier spelled out — a screen reader does not read the ⌘ glyph. The height is fixed per size, so the badge does not deform under text-scale.\",\n      \"pt\": \"Nó único rotulado \\\"Atalho: Comando K\\\" (excludeSemantics), com o modificador por extenso — o leitor de tela não lê o glifo ⌘. A altura é fixa por tamanho, então o selo não deforma com text-scale.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_omni_search\",\n      \"app_badge\"\n    ]\n  },\n  {\n    \"id\": \"app_image\",\n    \"name\": \"AppImage\",\n    \"category\": \"atom\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Raster image (network/asset) with standardized loading and fallback.\",\n      \"pt\": \"Imagem raster (rede/asset) com loading e fallback padronizados.\"\n    },\n    \"description\": {\n      \"en\": \"Complements AppIllustration (SVG) and AppAvatar (circular). Clips to the theme radius, cross-fades from the placeholder to the network image and falls back to a theme-aware box on error.\",\n      \"pt\": \"Complementa AppIllustration (SVG) e AppAvatar (circular). Recorta ao radius do tema, faz cross-fade do placeholder para a imagem na rede e cai num fallback theme-aware em erro.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Raster photo/thumbnail/banner (camera event, preview, portrait).\"\n      ],\n      \"pt\": [\n        \"Foto/thumbnail/banner raster (evento de câmera, preview, portrait).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Vector (SVG) → AppIcon/AppIllustration.\",\n        \"Circular profile photo → AppAvatar.\"\n      ],\n      \"pt\": [\n        \"Vetor (SVG) → AppIcon/AppIllustration.\",\n        \"Foto de perfil circular → AppAvatar.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"src\",\n        \"type\": \"String\",\n        \"required\": true,\n        \"description\": {\n          \"en\": \"Network URL or asset path.\",\n          \"pt\": \"URL de rede ou caminho de asset.\"\n        }\n      },\n      {\n        \"name\": \"fit\",\n        \"type\": \"BoxFit\",\n        \"required\": false,\n        \"default\": \"BoxFit.cover\"\n      },\n      {\n        \"name\": \"width\",\n        \"type\": \"double?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"height\",\n        \"type\": \"double?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"radius\",\n        \"type\": \"BorderRadius?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Default: the global radius (round mode), proportional to the box.\",\n          \"pt\": \"Default: radius global (modo redondo), proporcional à caixa.\"\n        }\n      },\n      {\n        \"name\": \"semanticLabel\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"fallback\",\n        \"type\": \"Widget?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Shown on error (default: a surfaceContainer box).\",\n          \"pt\": \"Exibido em erro (default: caixa surfaceContainer).\"\n        }\n      },\n      {\n        \"name\": \"loading\",\n        \"type\": \"AppImageLoading\",\n        \"required\": false,\n        \"default\": \"AppImageLoading.spinner\",\n        \"description\": {\n          \"en\": \"Placeholder while the network image loads.\",\n          \"pt\": \"Placeholder de carregamento de rede.\"\n        },\n        \"enumValues\": [\n          \"spinner\",\n          \"skeleton\"\n        ]\n      }\n    ],\n    \"variants\": [\n      \"network\",\n      \"asset\"\n    ],\n    \"states\": [\n      \"loading\",\n      \"loaded\",\n      \"error\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Network thumbnail\",\n          \"pt\": \"Thumbnail de rede\"\n        },\n        \"code\": \"AppImage.network(event.thumbnailUrl, width: 96, height: 64)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Give it width/height (most uses have a fixed box).\",\n        \"Pass semanticLabel when the image carries meaning.\"\n      ],\n      \"pt\": [\n        \"Informe width/height (a maioria dos usos tem caixa fixa).\",\n        \"Passe semanticLabel quando a imagem tiver significado.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it for vectors (SVG) — that is AppIllustration.\"\n      ],\n      \"pt\": [\n        \"Não use para vetor (SVG) — é AppIllustration.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"semanticLabel==null → decorative; otherwise Semantics(image:true, label). The .network variant falls back when the network fails.\",\n      \"pt\": \"semanticLabel==null → decorativa; senão Semantics(image:true, label). A variante .network cai no fallback quando a rede falha.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_illustration\",\n      \"app_avatar\",\n      \"app_icon\"\n    ]\n  },\n  {\n    \"id\": \"app_swatch\",\n    \"name\": \"AppSwatch\",\n    \"category\": \"atom\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Color swatch (rounded square or circle).\",\n      \"pt\": \"Amostra de cor (quadrado arredondado ou círculo).\"\n    },\n    \"description\": {\n      \"en\": \"Reusable leaf for showing a color in lists, grids and the color picker. A subtle border (outline) keeps light colors readable; square uses the global radius.\",\n      \"pt\": \"Folha reusável para exibir uma cor em listas, grids e no color picker. Borda sutil (outline) destaca cores claras; square usa o radius global.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Showing a color: a picker, a chart legend, a vehicle color, a palette.\"\n      ],\n      \"pt\": [\n        \"Mostrar uma cor: seletor, legenda de gráfico, cor de veículo, paleta.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A status label → AppBadge.\",\n        \"An icon → AppIcon.\"\n      ],\n      \"pt\": [\n        \"Rótulo de status → AppBadge.\",\n        \"Ícone → AppIcon.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"color\",\n        \"type\": \"Color\",\n        \"required\": true,\n        \"description\": {\n          \"en\": \"The color shown.\",\n          \"pt\": \"Cor exibida.\"\n        }\n      },\n      {\n        \"name\": \"size\",\n        \"type\": \"double\",\n        \"required\": false,\n        \"default\": \"20\"\n      },\n      {\n        \"name\": \"shape\",\n        \"type\": \"AppSwatchShape\",\n        \"required\": false,\n        \"default\": \"AppSwatchShape.square\",\n        \"enumValues\": [\n          \"square\",\n          \"circle\"\n        ]\n      },\n      {\n        \"name\": \"borderColor\",\n        \"type\": \"Color?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Defaults to theme.colorTheme.outline.\",\n          \"pt\": \"Default theme.colorTheme.outline.\"\n        }\n      },\n      {\n        \"name\": \"semanticLabel\",\n        \"type\": \"String?\",\n        \"required\": false\n      }\n    ],\n    \"variants\": [\n      \"square\",\n      \"circle\"\n    ],\n    \"states\": [\n      \"default\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"With label\",\n          \"pt\": \"Com rótulo\"\n        },\n        \"code\": \"AppSwatch(color: Color(0xFF1E88E5), semanticLabel: 'Azul')\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Pass semanticLabel with the name/hex when the color carries meaning.\"\n      ],\n      \"pt\": [\n        \"Passe semanticLabel com o nome/hex quando a cor tiver sentido.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it for textual status — that is AppBadge.\"\n      ],\n      \"pt\": [\n        \"Não use para status textual — é AppBadge.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"semanticLabel==null → decorative; otherwise AppSemantics.label. Color must not be the only channel carrying information.\",\n      \"pt\": \"semanticLabel==null → decorativo; senão AppSemantics.label. Cor não deve ser o único canal de informação.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_badge\",\n      \"app_icon\"\n    ]\n  },\n  {\n    \"id\": \"app_chat_bubble\",\n    \"name\": \"AppChatBubble\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Content-agnostic message bubble (LLM + WhatsApp style).\",\n      \"pt\": \"Bolha de mensagem agnóstica de conteúdo (LLM + estilo WhatsApp).\"\n    },\n    \"description\": {\n      \"en\": \"The visual shell of a message: alignment by author (me/other), tint or surface, corners with an asymmetric tail, a maximum width and header/footer slots. It takes an arbitrary child (text, markdown, image). It takes part in the style and shape axes and reads 100% from the theme.\",\n      \"pt\": \"A casca visual de uma mensagem: alinhamento por autor (me/other), tint ou superfície, cantos com tail assimétrico, largura máxima e slots header/footer. Recebe um child arbitrário (texto, markdown, imagem). Participa dos eixos style/forma e lê 100% do tema.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Rendering any message in a conversation.\",\n        \"The user's bubble in an LLM chat, or both sides in a WhatsApp-style chat.\"\n      ],\n      \"pt\": [\n        \"Renderizar qualquer mensagem de uma conversa.\",\n        \"Bolha do usuário num chat com LLM ou ambos os lados num chat WhatsApp.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A \\\"flat\\\" assistant reply (full width, no bubble) → render the content directly + AppChatActionBar.\"\n      ],\n      \"pt\": [\n        \"Resposta do assistente \\\"plana\\\" (largura cheia, sem bolha) → renderize o conteúdo direto + AppChatActionBar.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"child\",\n        \"type\": \"Widget\",\n        \"required\": true,\n        \"description\": {\n          \"en\": \"The bubble's agnostic content.\",\n          \"pt\": \"Conteúdo agnóstico da bolha.\"\n        }\n      },\n      {\n        \"name\": \"author\",\n        \"type\": \"AppChatAuthor\",\n        \"required\": false,\n        \"default\": \"AppChatAuthor.other\",\n        \"enumValues\": [\n          \"me\",\n          \"other\"\n        ]\n      },\n      {\n        \"name\": \"color\",\n        \"type\": \"AppChatBubbleColor\",\n        \"required\": false,\n        \"default\": \"AppChatBubbleColor.primary\",\n        \"enumValues\": [\n          \"primary\",\n          \"secondary\",\n          \"tertiary\",\n          \"neutral\"\n        ]\n      },\n      {\n        \"name\": \"tail\",\n        \"type\": \"AppChatBubbleTail\",\n        \"required\": false,\n        \"default\": \"AppChatBubbleTail.top\",\n        \"enumValues\": [\n          \"none\",\n          \"top\",\n          \"bottom\"\n        ]\n      },\n      {\n        \"name\": \"header\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"footer\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppStyle?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"maxWidthFraction\",\n        \"type\": \"double\",\n        \"required\": false,\n        \"default\": \"0.78\"\n      }\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"User message\",\n          \"pt\": \"Mensagem do usuário\"\n        },\n        \"code\": \"AppChatBubble(\\n  author: AppChatAuthor.me,\\n  child: AppText('Quantos veículos estão parados agora?'),\\n)\",\n        \"description\": {\n          \"en\": \"Aligns right and tints with the author's color. The child is agnostic — text, markdown or image.\",\n          \"pt\": \"Alinha à direita e tinge com a cor do autor. O child é agnóstico — texto, markdown ou imagem.\"\n        }\n      },\n      {\n        \"title\": {\n          \"en\": \"Bubble from the other side with meta in the footer\",\n          \"pt\": \"Bolha do outro lado com meta no rodapé\"\n        },\n        \"code\": \"AppChatBubble(\\n  author: AppChatAuthor.other,\\n  color: AppChatBubbleColor.neutral,\\n  tail: AppChatBubbleTail.bottom,\\n  footer: AppMessageMeta(time: sentAt, status: AppMessageStatus.read),\\n  child: AppMarkdown(answer),\\n)\"\n      }\n    ],\n    \"a11y\": {\n      \"en\": \"Takes a semanticLabel to group the message into one labelled node.\",\n      \"pt\": \"Aceita semanticLabel para agrupar a mensagem num nó rotulado.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_message_meta\",\n      \"app_chat_message_list\"\n    ]\n  },\n  {\n    \"id\": \"app_message_meta\",\n    \"name\": \"AppMessageMeta\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Time + delivery ticks in a bubble's footer.\",\n      \"pt\": \"Horário + ticks de entrega no rodapé de uma bolha.\"\n    },\n    \"description\": {\n      \"en\": \"A message's compact meta: the time (already formatted by the app) and, optionally, delivery status as ticks (sending/sent/delivered/read/failed). \\\"Read\\\" tints with info; \\\"failed\\\" with danger.\",\n      \"pt\": \"Meta compacta de uma mensagem: horário (já formatado pelo app) e, opcionalmente, o status de entrega como ticks (enviando/enviada/entregue/lida/falhou). \\\"Lida\\\" tinge com info; \\\"falhou\\\" com danger.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"The footer of an AppChatBubble.\"\n      ],\n      \"pt\": [\n        \"Rodapé (footer) de uma AppChatBubble.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A system or alert status → use AppBadge/AppAlert.\"\n      ],\n      \"pt\": [\n        \"Status de sistema/alerta → use AppBadge/AppAlert.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"time\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"status\",\n        \"type\": \"AppMessageStatus\",\n        \"required\": false,\n        \"default\": \"AppMessageStatus.none\",\n        \"enumValues\": [\n          \"none\",\n          \"sending\",\n          \"sent\",\n          \"delivered\",\n          \"read\",\n          \"failed\"\n        ]\n      },\n      {\n        \"name\": \"edited\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      }\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Time + delivery status\",\n          \"pt\": \"Hora + status de entrega\"\n        },\n        \"code\": \"AppMessageMeta(\\n  time: message.sentAt,\\n  status: AppMessageStatus.delivered,\\n  edited: message.wasEdited,\\n)\",\n        \"description\": {\n          \"en\": \"Goes in AppChatBubble's footer slot. The status is labelled, not only colored.\",\n          \"pt\": \"Vai no slot footer da AppChatBubble. O status é rotulado, não só colorido.\"\n        }\n      }\n    ],\n    \"a11y\": {\n      \"en\": \"The status is exposed as a label too (it does not depend on color alone).\",\n      \"pt\": \"O status também é exposto como rótulo (não depende só da cor).\"\n    },\n    \"crossPlatform\": false,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_chat_bubble\"\n    ]\n  },\n  {\n    \"id\": \"app_chat_composer\",\n    \"name\": \"AppChatComposer\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Multimodal field with a toolbar (attachment/model/info/context).\",\n      \"pt\": \"Campo multimodal com toolbar (anexo/modelo/info/contexto).\"\n    },\n    \"description\": {\n      \"en\": \"The surface wraps ONLY the compose area (a \\\"bare\\\" multiline AppInput + a bare send/stop button). OUTSIDE it (as in Claude): attachments ABOVE the input and the toolbar BELOW (left: attachment + model; right: info popover + context ring). Neutral items (onSurface) with hover/focus/click + tooltip; the only colored one is the context ring. Attachments follow the composer's style. It resolves the global style axis (filled/outlined/elevated, with an opaque fill — so the shadow does not bleed) and the shape axis (circular becomes round with attachments OR multiline). Enter sends; Shift+Enter breaks the line. Replaces Material's TextField.\",\n      \"pt\": \"A superfície envolve SÓ o compose (AppInput multiline \\\"nu\\\" + botão enviar/parar bare). FORA dela (como no Claude): anexos ACIMA do input e a toolbar ABAIXO (esquerda: anexo + modelo; direita: info popover + anel de contexto). Itens neutros (onSurface) com hover/foco/clique + tooltip; o único colorido é o anel de contexto. Anexos seguem o estilo do composer. Resolve os eixos globais de estilo (filled/outlined/elevated, fundo opaco — sombra não vaza) e de forma (circular vira redondo com anexos OU multiline). Enter envia; Shift+Enter quebra. Substitui o TextField do Material.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Message input for any chat.\"\n      ],\n      \"pt\": [\n        \"Entrada de mensagens de qualquer chat.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"An ordinary form field → use AppInput directly.\"\n      ],\n      \"pt\": [\n        \"Campo de formulário comum → use AppInput direto.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"controller\",\n        \"type\": \"TextEditingController\",\n        \"required\": true\n      },\n      {\n        \"name\": \"onSend\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onStop\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onAttach\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"attachments\",\n        \"type\": \"List<Widget>\",\n        \"required\": false,\n        \"default\": \"const []\"\n      },\n      {\n        \"name\": \"attachmentLimit\",\n        \"type\": \"int\",\n        \"required\": false,\n        \"default\": \"2\"\n      },\n      {\n        \"name\": \"modelLabel\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onModelTap\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"info\",\n        \"type\": \"Widget?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"info popover\",\n          \"pt\": \"popover de info\"\n        }\n      },\n      {\n        \"name\": \"contextProgress\",\n        \"type\": \"double?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"0..1\",\n          \"pt\": \"0..1\"\n        }\n      },\n      {\n        \"name\": \"contextPopover\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"busy\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      },\n      {\n        \"name\": \"size\",\n        \"type\": \"AppFieldSize\",\n        \"required\": false,\n        \"default\": \"AppFieldSize.s\",\n        \"enumValues\": [\n          \"s\",\n          \"m\",\n          \"l\"\n        ]\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppStyle?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"radiusMode\",\n        \"type\": \"AppRadiusMode?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"with attachments, circular → round\",\n          \"pt\": \"com anexos, circular → redondo\"\n        }\n      }\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Basic composer\",\n          \"pt\": \"Composer básico\"\n        },\n        \"code\": \"AppChatComposer(\\n  controller: _controller,\\n  hintText: 'Pergunte alguma coisa…',\\n  onSend: _send,\\n)\"\n      },\n      {\n        \"title\": {\n          \"en\": \"While the assistant is answering\",\n          \"pt\": \"Enquanto o assistente responde\"\n        },\n        \"code\": \"AppChatComposer(\\n  controller: _controller,\\n  busy: true,\\n  onStop: _cancel,\\n  attachments: files.map(AppChatAttachmentChip.new).toList(),\\n)\",\n        \"description\": {\n          \"en\": \"With busy, the send button becomes stop; attachments sit above the field.\",\n          \"pt\": \"Com busy o botão de enviar vira parar; os anexos ficam acima do campo.\"\n        }\n      }\n    ],\n    \"a11y\": {\n      \"en\": \"Attachment/model/info/send/stop with labelled semantics; a tooltip on the attachment limit.\",\n      \"pt\": \"Anexo/modelo/info/enviar/parar com semântica rotulada; tooltip no limite de anexos.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_chat_attachment_chip\"\n    ]\n  },\n  {\n    \"id\": \"app_chat_attachment_chip\",\n    \"name\": \"AppChatAttachmentChip\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Image thumbnail or file pill, with a remove control.\",\n      \"pt\": \"Thumbnail de imagem ou pílula de arquivo, com remover.\"\n    },\n    \"description\": {\n      \"en\": \"Preview of a composer attachment: a thumbnail (through an ImageProvider) or an icon+name pill for files. The remove button reuses AppInteraction.\",\n      \"pt\": \"Preview de um anexo do composer: thumbnail (via ImageProvider) ou uma pílula ícone+nome para arquivos. O botão de remover reusa AppInteraction.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"The attachment strip of an AppChatComposer.\"\n      ],\n      \"pt\": [\n        \"Faixa de anexos de um AppChatComposer.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"image\",\n        \"type\": \"ImageProvider?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"label\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onRemove\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"size\",\n        \"type\": \"double\",\n        \"required\": false,\n        \"default\": \"48\"\n      }\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Removable attachment in the send queue\",\n          \"pt\": \"Anexo removível na fila de envio\"\n        },\n        \"code\": \"AppChatAttachmentChip(\\n  label: 'relatorio.pdf',\\n  kind: AppAttachmentKind.pdf,\\n  onRemove: () => _remove(file),\\n)\",\n        \"description\": {\n          \"en\": \"With no kind, the icon comes from the label's extension.\",\n          \"pt\": \"Sem kind o ícone sai da extensão do label.\"\n        }\n      }\n    ],\n    \"a11y\": {\n      \"en\": \"Remove button with a label (\\\"Remove attachment\\\").\",\n      \"pt\": \"Botão de remover rotulado (\\\"Remover anexo\\\").\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_chat_composer\"\n    ]\n  },\n  {\n    \"id\": \"app_chat_attachment_card\",\n    \"name\": \"AppChatAttachmentCard\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Square attachment card (thumbnail or large icon).\",\n      \"pt\": \"Card quadrado de anexo (thumbnail ou ícone grande).\"\n    },\n    \"description\": {\n      \"en\": \"The \\\"card\\\" alternative to the chip: an image thumbnail with the name over it, or a large icon tinted by category (resolved from the extension) with the name below. onTap previews it; onRemove puts the remove control in the corner.\",\n      \"pt\": \"Alternativa \\\"cartão\\\" ao chip: thumbnail da imagem com o nome sobreposto, ou um ícone grande tingido pela categoria (resolvida da extensão) com o nome abaixo. onTap visualiza; onRemove mostra o remover no canto.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"The composer's attachment strip in card form (Claude style).\"\n      ],\n      \"pt\": [\n        \"Faixa de anexos do composer em formato cartão (estilo Claude).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"The compact form → use AppChatAttachmentChip.\"\n      ],\n      \"pt\": [\n        \"Formato compacto → use AppChatAttachmentChip.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"image\",\n        \"type\": \"ImageProvider?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"label\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"kind\",\n        \"type\": \"AppAttachmentKind?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"subtitle\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onTap\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onRemove\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"size\",\n        \"type\": \"double\",\n        \"required\": false,\n        \"default\": \"104\"\n      }\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Attachment already sent, as a card\",\n          \"pt\": \"Anexo já enviado, em cartão\"\n        },\n        \"code\": \"AppChatAttachmentCard(\\n  label: 'rota-2026-07.xlsx',\\n  subtitle: '240 KB',\\n  kind: AppAttachmentKind.spreadsheet,\\n  onTap: () => _open(file),\\n)\",\n        \"description\": {\n          \"en\": \"The chip's large form: it has room for a subtitle and a thumbnail.\",\n          \"pt\": \"A versão grande do chip: cabe subtítulo e miniatura.\"\n        }\n      }\n    ],\n    \"a11y\": {\n      \"en\": \"onTap/onRemove are labelled buttons.\",\n      \"pt\": \"onTap/onRemove são botões rotulados.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_chat_attachment_chip\",\n      \"app_chat_composer\"\n    ]\n  },\n  {\n    \"id\": \"app_typing_indicator\",\n    \"name\": \"AppTypingIndicator\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Three \\\"typing…\\\" dots, motion-aware.\",\n      \"pt\": \"Três pontinhos \\\"digitando…\\\", motion-aware.\"\n    },\n    \"description\": {\n      \"en\": \"Dots that rise and fall in sequence, for \\\"is typing\\\" (WhatsApp) or \\\"assistant thinking\\\". Under reduce-motion they stay still; the label is always exposed.\",\n      \"pt\": \"Pontos que sobem/descem em sequência, para \\\"está digitando\\\" (WhatsApp) ou \\\"assistente pensando\\\". Sob reduce-motion ficam estáticos; o rótulo é sempre exposto.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Signalling that the other party or the assistant is composing.\"\n      ],\n      \"pt\": [\n        \"Sinalizar que o interlocutor/assistente está compondo.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"color\",\n        \"type\": \"Color?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"dotSize\",\n        \"type\": \"double\",\n        \"required\": false,\n        \"default\": \"7\"\n      },\n      {\n        \"name\": \"semanticLabel\",\n        \"type\": \"String\",\n        \"required\": false,\n        \"default\": \"'Digitando'\"\n      }\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Assistant typing\",\n          \"pt\": \"Assistente digitando\"\n        },\n        \"code\": \"AppTypingIndicator()\",\n        \"description\": {\n          \"en\": \"With reduce-motion on, the dots stop — the live region's label keeps announcing.\",\n          \"pt\": \"Com reduce-motion ligado os pontos param — o rótulo da região viva continua anunciando.\"\n        }\n      }\n    ],\n    \"a11y\": {\n      \"en\": \"A labelled live region — the reader does not wait for the animation.\",\n      \"pt\": \"Região viva rotulada — o leitor não espera a animação.\"\n    },\n    \"crossPlatform\": false,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_assistant_status\"\n    ]\n  },\n  {\n    \"id\": \"app_assistant_status\",\n    \"name\": \"AppAssistantStatus\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Assistant step label, with a smooth transition.\",\n      \"pt\": \"Rótulo de etapa do assistente, com transição suave.\"\n    },\n    \"description\": {\n      \"en\": \"Shows the current step (\\\"Fetching data\\\"…) and animates the swap (fade + rise) on every label change. Optionally prefixes an AppTypingIndicator. Announces as a status region; honors reduce-motion.\",\n      \"pt\": \"Mostra a etapa atual (\\\"Buscando dados\\\"…) e anima o swap (fade + subida) a cada troca de label. Opcionalmente prefixa um AppTypingIndicator. Anuncia como região de status; respeita reduce-motion.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"\\\"Thinking/working\\\" feedback for an AI reply.\"\n      ],\n      \"pt\": [\n        \"Feedback \\\"pensando/trabalhando\\\" de uma resposta de IA.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"label\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"showIndicator\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"TextStyle?\",\n        \"required\": false\n      }\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Assistant's current step\",\n          \"pt\": \"Passo corrente do assistente\"\n        },\n        \"code\": \"AppAssistantStatus(label: 'Consultando os veículos…')\",\n        \"description\": {\n          \"en\": \"A label change is announced; the typing effect honors reduce-motion.\",\n          \"pt\": \"Troca de rótulo é anunciada; o efeito de digitação respeita reduce-motion.\"\n        }\n      }\n    ],\n    \"a11y\": {\n      \"en\": \"Status region (liveRegion) — a change announces the new label.\",\n      \"pt\": \"Região de status (liveRegion) — muda anuncia o novo rótulo.\"\n    },\n    \"crossPlatform\": false,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_typing_indicator\"\n    ]\n  },\n  {\n    \"id\": \"app_chat_action_bar\",\n    \"name\": \"AppChatActionBar\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Row of icon actions for a message (copy/like/…).\",\n      \"pt\": \"Linha de ações-ícone de uma mensagem (copiar/like/…).\"\n    },\n    \"description\": {\n      \"en\": \"Actions under a reply: each AppChatAction becomes an AppInteraction (hover/press/focus, tooltip, button semantics). The active state tints the icon with the secondary role.\",\n      \"pt\": \"Ações abaixo de uma resposta: cada AppChatAction vira um AppInteraction (hover/press/foco, tooltip, semântica de botão). O estado ativo tinge o ícone pelo papel secondary.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Actions on the assistant's reply (copy, regenerate, feedback).\"\n      ],\n      \"pt\": [\n        \"Ações da resposta do assistente (copiar, regenerar, feedback).\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"actions\",\n        \"type\": \"List<AppChatAction>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"color\",\n        \"type\": \"Color?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"iconSize\",\n        \"type\": \"AppIconSize\",\n        \"required\": false,\n        \"default\": \"AppIconSize.s\"\n      }\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Actions under the reply\",\n          \"pt\": \"Ações abaixo da resposta\"\n        },\n        \"code\": \"AppChatActionBar(\\n  actions: <AppChatAction>[\\n    AppChatAction(icon: AppIconToken.copy, label: 'Copiar', onPressed: _copy),\\n    AppChatAction(icon: AppIconToken.refresh, label: 'Regenerar', onPressed: _retry),\\n  ],\\n)\"\n      }\n    ],\n    \"a11y\": {\n      \"en\": \"Each action is a labelled button with a tooltip.\",\n      \"pt\": \"Cada ação é um botão rotulado com tooltip.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true\n  },\n  {\n    \"id\": \"app_filter_chip\",\n    \"name\": \"AppFilterChip\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Applied-filter chip with a remove affordance.\",\n      \"pt\": \"Chip de filtro aplicado, com afordância de remover.\"\n    },\n    \"description\": {\n      \"en\": \"Filled chip showing \\\"field: value\\\" for a filter currently applied, with its own \\\"×\\\" target to clear it. The sibling of AppSuggestionChip: that one invites, this one reports and undoes.\",\n      \"pt\": \"Chip preenchido com \\\"campo: valor\\\" de um filtro em vigor, e um alvo de toque PRÓPRIO para removê-lo. Irmão do AppSuggestionChip: aquele convida a aplicar, este mostra o que está aplicado e oferece tirar.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Filters applied above a list or a timeline.\",\n        \"Any narrowing the reader needs to see and be able to undo.\"\n      ],\n      \"pt\": [\n        \"Filtros aplicados acima de uma lista ou timeline.\",\n        \"Todo recorte que quem lê precisa enxergar e poder desfazer.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A suggestion to be applied → AppSuggestionChip.\",\n        \"A status label → AppBadge.\"\n      ],\n      \"pt\": [\n        \"Sugestão a aplicar → AppSuggestionChip.\",\n        \"Rótulo de status → AppBadge.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"value\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"field\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onRemove\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onTap\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppStyle?\",\n        \"required\": false,\n        \"default\": \"AppStyle.filled\"\n      }\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Filters applied over an audit feed\",\n          \"pt\": \"Filtros aplicados sobre um feed de auditoria\"\n        },\n        \"code\": \"Wrap(spacing: 8, children: <Widget>[\\n  AppFilterChip(field: 'Tipo', value: 'client.created', onRemove: _clearType),\\n  AppFilterChip(field: 'Resultado', value: 'Negado', onRemove: _clearResult),\\n])\"\n      }\n    ],\n    \"a11y\": {\n      \"en\": \"Two separate targets: the body opens the filter, the \\\"×\\\" removes it — announced as \\\"Remove filter <label>\\\".\",\n      \"pt\": \"Dois alvos separados: o corpo abre o filtro, o \\\"×\\\" remove — anunciado como \\\"Remover filtro <rótulo>\\\".\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true\n  },\n  {\n    \"id\": \"app_timeline\",\n    \"name\": \"AppTimeline\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Chronological list of events that happened, newest first.\",\n      \"pt\": \"Lista cronológica de eventos que aconteceram, do mais recente ao mais antigo.\"\n    },\n    \"description\": {\n      \"en\": \"A vertical rail with a marker per event and a content slot beside it. It is a semantic LIST, navigable item by item; the rail is decoration and leaves the accessibility tree.\",\n      \"pt\": \"Trilho vertical com um marcador por evento e um slot de conteúdo ao lado. É uma LISTA semântica, navegável item a item; o trilho é decoração e sai da árvore de acessibilidade.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"An audit trail or an activity feed.\",\n        \"Any open-ended chronology of things that already happened.\"\n      ],\n      \"pt\": [\n        \"Trilha de auditoria ou feed de atividade.\",\n        \"Toda cronologia sem fim de coisas que já aconteceram.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Progress through a known process → AppStepper. A stepper has a current step, future steps and the promise of a last one; a trail has none of those, and using one for the other makes the screen promise a sequence that does not exist.\",\n        \"Tabular data with sortable columns → AppDataTable.\"\n      ],\n      \"pt\": [\n        \"Progresso num processo conhecido → AppStepper. O stepper tem passo atual, passos futuros e a promessa de um último; uma trilha não tem nada disso, e trocar um pelo outro faz a tela prometer uma sequência que não existe.\",\n        \"Dado tabular com colunas ordenáveis → AppDataTable.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"itemBuilder\",\n        \"type\": \"NullableIndexedWidgetBuilder\",\n        \"required\": true\n      },\n      {\n        \"name\": \"itemCount\",\n        \"type\": \"int\",\n        \"required\": true\n      },\n      {\n        \"name\": \"controller\",\n        \"type\": \"ScrollController?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"footer\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"markerBuilder\",\n        \"type\": \"IndexedWidgetBuilder?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"shrinkWrap\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      }\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Audit feed\",\n          \"pt\": \"Feed de auditoria\"\n        },\n        \"code\": \"AppTimeline(\\n  itemCount: eventos.length,\\n  itemBuilder: (BuildContext c, int i) => AuditEventTile(eventos[i]),\\n  footer: carregando ? const AppCircularLoading() : null,\\n)\"\n      }\n    ],\n    \"a11y\": {\n      \"en\": \"A semantic list with explicit child nodes; the rail is excluded from semantics so a screen reader hears events, not lines.\",\n      \"pt\": \"Lista semântica com nós filhos explícitos; o trilho sai da semântica para que o leitor de tela ouça eventos, e não linhas.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true\n  },\n  {\n    \"id\": \"app_suggestion_chip\",\n    \"name\": \"AppSuggestionChip\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Tappable chip for a starter prompt or a quick reply.\",\n      \"pt\": \"Chip tocável de prompt inicial / resposta rápida.\"\n    },\n    \"description\": {\n      \"en\": \"Outlined chip (by default) with an optional icon + text, meant for a Wrap of suggestions. Reuses AppSurface (the shell) + AppInteraction (the touch).\",\n      \"pt\": \"Chip delineado (por padrão) com ícone opcional + texto, para entrar num Wrap de sugestões. Reusa AppSurface (casca) + AppInteraction (toque).\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Prompt suggestions in an LLM chat.\",\n        \"WhatsApp-style quick replies.\"\n      ],\n      \"pt\": [\n        \"Sugestões de prompt de um chat com LLM.\",\n        \"Respostas rápidas estilo WhatsApp.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A status label → use AppBadge.\"\n      ],\n      \"pt\": [\n        \"Rótulo de status → use AppBadge.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"label\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"icon\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onTap\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppStyle?\",\n        \"required\": false,\n        \"default\": \"AppStyle.outlined\"\n      },\n      {\n        \"name\": \"maxLines\",\n        \"type\": \"int\",\n        \"required\": false,\n        \"default\": \"2\"\n      }\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Suggested opening question\",\n          \"pt\": \"Sugestão de primeira pergunta\"\n        },\n        \"code\": \"AppSuggestionChip(\\n  label: 'Quais veículos estão sem sinal?',\\n  onTap: () => _ask(suggestion),\\n)\"\n      }\n    ],\n    \"a11y\": {\n      \"en\": \"A button labelled by its label.\",\n      \"pt\": \"Botão rotulado pelo label.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true\n  },\n  {\n    \"id\": \"app_chat_day_divider\",\n    \"name\": \"AppChatDayDivider\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Centered \\\"Today/Yesterday/date\\\" pill that separates days.\",\n      \"pt\": \"Pílula central \\\"Hoje/Ontem/data\\\" que separa dias.\"\n    },\n    \"description\": {\n      \"en\": \"Day divider for a conversation (WhatsApp's signature). The design system does not format dates: it takes the label ready-made. With withRules, it draws a rule on both sides.\",\n      \"pt\": \"Divisor de dia de uma conversa (assinatura do WhatsApp). O DS não formata datas: recebe o label pronto. Com withRules, desenha filetes dos dois lados.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Separating messages by day in an AppChatMessageList.\"\n      ],\n      \"pt\": [\n        \"Separar mensagens por dia numa AppChatMessageList.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"label\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"withRules\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      }\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Day separator in the conversation\",\n          \"pt\": \"Separador de dia na conversa\"\n        },\n        \"code\": \"AppChatDayDivider(label: 'Hoje')\"\n      }\n    ],\n    \"a11y\": {\n      \"en\": \"A reading landmark, not content: the label is read in order, between the previous day's last message and the new day's first. The withRules rules are decorative and stay out of the semantics tree.\",\n      \"pt\": \"Marco de leitura, não conteúdo: o label é lido em ordem, entre a última mensagem do dia anterior e a primeira do novo. Os filetes do withRules são decorativos e não entram na árvore semântica.\"\n    },\n    \"crossPlatform\": false,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_chat_message_list\"\n    ]\n  },\n  {\n    \"id\": \"app_question_card\",\n    \"name\": \"AppQuestionCard\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Inline question card: confirmation, single choice or multiple choice.\",\n      \"pt\": \"Card de pergunta inline: confirmação, escolha única ou múltipla.\"\n    },\n    \"description\": {\n      \"en\": \"The AI asks the user for something and gets the answer inline. Three kinds: confirmation (detail + confirm/cancel — it generalizes the pending-action card), singleChoice (up to 3 radio options + a free answer) and multipleChoice (up to 3 checkbox options + a free answer). Tinted by role (info/warning/danger/success).\",\n      \"pt\": \"A IA pede algo ao usuário e recebe a resposta inline. Três tipos: confirmation (detalhe + confirmar/cancelar — generaliza o card de ação pendente), singleChoice (até 3 opções em radio + resposta livre) e multipleChoice (até 3 opções em checkbox + resposta livre). Tingido por papel (info/warning/danger/success).\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Confirming an action or tool call from the AI.\",\n        \"Asking the user for a choice (one or several) inside the chat flow.\"\n      ],\n      \"pt\": [\n        \"Confirmar uma ação/tool-call da IA.\",\n        \"Pedir uma escolha (uma ou várias) ao usuário no fluxo do chat.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A notice with no answer → use AppAlert.\"\n      ],\n      \"pt\": [\n        \"Aviso sem resposta → use AppAlert.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"title\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"subtitle\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"role\",\n        \"type\": \"AppQuestionCardRole\",\n        \"required\": false,\n        \"enumValues\": [\n          \"info\",\n          \"warning\",\n          \"danger\",\n          \"success\"\n        ]\n      },\n      {\n        \"name\": \"detail\",\n        \"type\": \"Widget?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"confirmation\",\n          \"pt\": \"confirmation\"\n        }\n      },\n      {\n        \"name\": \"onConfirm\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"confirmation\",\n          \"pt\": \"confirmation\"\n        }\n      },\n      {\n        \"name\": \"onCancel\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"confirmation\",\n          \"pt\": \"confirmation\"\n        }\n      },\n      {\n        \"name\": \"options\",\n        \"type\": \"List<String>\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"choice (max 3)\",\n          \"pt\": \"choice (máx 3)\"\n        }\n      },\n      {\n        \"name\": \"allowCustom\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"onSingleSelected\",\n        \"type\": \"ValueChanged<String>?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onMultipleSubmit\",\n        \"type\": \"ValueChanged<List<String>>?\",\n        \"required\": false\n      }\n    ],\n    \"variants\": [\n      \"confirmation\",\n      \"singleChoice\",\n      \"multipleChoice\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Confirming a destructive action\",\n          \"pt\": \"Confirmar uma ação destrutiva\"\n        },\n        \"code\": \"AppQuestionCard.confirmation(\\n  title: 'Apagar a rota?',\\n  role: AppQuestionCardRole.danger,\\n  onConfirm: _delete,\\n)\"\n      },\n      {\n        \"title\": {\n          \"en\": \"Single choice\",\n          \"pt\": \"Escolha única\"\n        },\n        \"code\": \"AppQuestionCard.singleChoice(\\n  title: 'Qual conta usar?',\\n  options: accounts,\\n  onSubmit: _pick,\\n)\"\n      }\n    ],\n    \"a11y\": {\n      \"en\": \"Design system radios/checkboxes and buttons (labelled, keyboard-ready).\",\n      \"pt\": \"Radios/checkboxes e botões do DS (rotulados, teclado).\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true\n  },\n  {\n    \"id\": \"app_chat_message_list\",\n    \"name\": \"AppChatMessageList\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Scrollable list that sticks to the bottom + auto-scroll + spacing.\",\n      \"pt\": \"Lista rolável que gruda no fim + auto-scroll + espaçamento.\"\n    },\n    \"description\": {\n      \"en\": \"The conversation's \\\"floor\\\": it anchors content to the bottom when short, scrolls to the end when a new message arrives and spaces the items. Agnostic: it neither groups nor inserts dividers — that comes from the consumer's itemBuilder.\",\n      \"pt\": \"O \\\"chão\\\" da conversa: ancora o conteúdo na base quando curto, rola para o fim ao chegar mensagem nova e espaça os itens. Agnóstica: não agrupa nem insere divisores — isso vem do itemBuilder do consumidor.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"The scroll container of a chat screen.\"\n      ],\n      \"pt\": [\n        \"Container de rolagem de uma tela de chat.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"itemCount\",\n        \"type\": \"int\",\n        \"required\": true\n      },\n      {\n        \"name\": \"itemBuilder\",\n        \"type\": \"IndexedWidgetBuilder\",\n        \"required\": true\n      },\n      {\n        \"name\": \"controller\",\n        \"type\": \"ScrollController?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"stickToBottom\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"autoScroll\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"spacing\",\n        \"type\": \"double\",\n        \"required\": false,\n        \"default\": \"AppSpacings.s16\"\n      },\n      {\n        \"name\": \"padding\",\n        \"type\": \"EdgeInsets\",\n        \"required\": false,\n        \"default\": \"EdgeInsets.zero\"\n      }\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"List that sticks to the bottom\",\n          \"pt\": \"Lista que gruda no fim\"\n        },\n        \"code\": \"AppChatMessageList(\\n  itemCount: messages.length,\\n  itemBuilder: (BuildContext context, int i) => AppChatBubble(\\n    author: messages[i].author,\\n    child: AppText(messages[i].text),\\n  ),\\n)\",\n        \"description\": {\n          \"en\": \"With stickToBottom the list starts at the end and follows each new message, except while the user has scrolled back.\",\n          \"pt\": \"Com stickToBottom a lista nasce no fim e acompanha a mensagem nova, menos quando o usuário rolou para trás.\"\n        }\n      }\n    ],\n    \"a11y\": {\n      \"en\": \"It is only the scroll container: the conversation's semantics live in the items (AppChatBubble groups a message into one labelled node). Auto-scroll does not steal focus — whoever was reading further up stays where they were.\",\n      \"pt\": \"É só o container de rolagem: a semântica da conversa mora nos itens (AppChatBubble agrupa a mensagem num nó rotulado). O auto-scroll não rouba o foco — quem estava lendo mais acima continua onde parou.\"\n    },\n    \"crossPlatform\": false,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_chat_bubble\",\n      \"app_chat_day_divider\"\n    ]\n  },\n  {\n    \"id\": \"app_markdown\",\n    \"name\": \"AppMarkdown\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Renders Markdown (GFM) with the theme's tokens, without Material.\",\n      \"pt\": \"Renderiza Markdown (GFM) com os tokens do tema, sem Material.\"\n    },\n    \"description\": {\n      \"en\": \"It reads package:markdown's AST and draws with Text.rich over widgets.dart — no Material and no flutter_html. Headings come from the type scale, tables from AppSimpleDataTable and images from AppImage. The whole document sits in a single AppSelectionRegion, so selection crosses blocks. Embedded raw HTML is rendered as literal text, never interpreted.\",\n      \"pt\": \"Lê a AST do package:markdown e desenha com Text.rich sobre widgets.dart — sem Material e sem flutter_html. Headings saem da escala tipográfica, tabelas do AppSimpleDataTable e imagens do AppImage. O documento inteiro fica numa única AppSelectionRegion, então a seleção atravessa blocos. HTML cru embutido é renderizado como texto literal, nunca interpretado.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"AI assistant replies (prose, code, tables) in the chat.\",\n        \"Any rich content the application already produces as Markdown.\"\n      ],\n      \"pt\": [\n        \"Respostas do assistente de IA (prosa, código, tabelas) no chat.\",\n        \"Qualquer conteúdo rico que a aplicação já produza em Markdown.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Content that arrives as HTML from the backend → AppHtml.\",\n        \"Single-style text → AppText; a few inline fragments → AppRichText.\"\n      ],\n      \"pt\": [\n        \"Conteúdo que chega em HTML do backend → AppHtml.\",\n        \"Texto de um único estilo → AppText; poucos trechos inline → AppRichText.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"data\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"TextStyle?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"textColor\",\n        \"type\": \"Color?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"styleSheet\",\n        \"type\": \"AppContentStyle?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onTapLink\",\n        \"type\": \"void Function(String)?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"selectable\",\n        \"type\": \"bool\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"default\",\n      \"empty\",\n      \"streaming\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Assistant message\",\n          \"pt\": \"Mensagem do assistente\"\n        },\n        \"code\": \"AppMarkdown(data: message.text, textColor: theme.colorTheme.onSurface)\"\n      },\n      {\n        \"title\": {\n          \"en\": \"Link routed by the application\",\n          \"pt\": \"Link roteado pela aplicação\"\n        },\n        \"code\": \"AppMarkdown(data: doc, onTapLink: (String href) => context.go(href))\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Leave the horizontal scroll to the call site when there is a wide table or code block — the component does not scroll on its own.\",\n        \"Pass onTapLink to route internally; without it the link opens in the external browser.\"\n      ],\n      \"pt\": [\n        \"Deixe o scroll horizontal no call site quando houver tabela ou código largo — o componente não rola sozinho.\",\n        \"Passe onTapLink para rotear internamente; sem ele o link abre no navegador externo.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not convert Markdown to HTML before rendering: the component reads the AST directly, and the detour through HTML loses structure.\"\n      ],\n      \"pt\": [\n        \"Não converta Markdown para HTML antes de renderizar: o componente lê a AST direto, e o desvio por HTML perde estrutura.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Text is selectable through AppSelectionRegion; images use the alt as their semantic label. Links are tappable but not yet Tab-focusable (Gate 7 debt). Colors come from the theme and pass AA in light and dark.\",\n      \"pt\": \"Texto selecionável via AppSelectionRegion; imagens usam o alt como rótulo semântico. Links são tocáveis mas ainda não focáveis por Tab (pendência Gate 7). Cores saem do tema e passam AA em claro/escuro.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_html\",\n      \"app_rich_text\",\n      \"app_simple_data_table\"\n    ]\n  },\n  {\n    \"id\": \"app_html\",\n    \"name\": \"AppHtml\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Renders a safe subset of HTML with the theme's tokens.\",\n      \"pt\": \"Renderiza um subconjunto seguro de HTML com os tokens do tema.\"\n    },\n    \"description\": {\n      \"en\": \"It parses with package:html (pure Dart) and shares AppMarkdown's renderer, so the same document looks identical through either path. It is not a browser: it covers a deliberate subset of tags and does not interpret CSS. It treats the input as untrusted — it drops script/style/iframe/form along with their subtrees, validates the href/src scheme (javascript: and data: are blocked) and degrades an unknown tag to its own children, preserving the text.\",\n      \"pt\": \"Parseia com o package:html (Dart puro) e compartilha o renderer do AppMarkdown, de modo que o mesmo documento fica visualmente idêntico nos dois caminhos. Não é um navegador: cobre um subconjunto deliberado de tags e não interpreta CSS. Trata a entrada como não confiável — descarta script/style/iframe/form com a subárvore, valida o esquema de href/src (javascript: e data: são bloqueados) e degrada tag desconhecida para os próprios filhos, preservando o texto.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Terms of use, privacy policies and legal notices coming from the backend.\"\n      ],\n      \"pt\": [\n        \"Termos de uso, política de privacidade e avisos legais vindos do backend.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Content the application already produces as Markdown → AppMarkdown.\",\n        \"Arbitrary web pages with their own CSS and layout — use a WebView.\"\n      ],\n      \"pt\": [\n        \"Conteúdo que a aplicação já produz em Markdown → AppMarkdown.\",\n        \"Páginas web arbitrárias com CSS e layout próprios — use um WebView.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"data\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"TextStyle?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"textColor\",\n        \"type\": \"Color?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"styleSheet\",\n        \"type\": \"AppContentStyle?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onTapLink\",\n        \"type\": \"void Function(String)?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"selectable\",\n        \"type\": \"bool\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"default\",\n      \"empty\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Legal document\",\n          \"pt\": \"Documento legal\"\n        },\n        \"code\": \"AppHtml(data: state.privacyPolicy)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"It accepts a full document or a fragment — no need to normalize first.\",\n        \"Wrap it in a scroll: legal documents are long.\"\n      ],\n      \"pt\": [\n        \"Aceita documento completo ou fragmento — não precisa normalizar antes.\",\n        \"Envolva num scroll: documentos legais são longos.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not expect CSS fidelity: only the semantic structure is interpreted.\"\n      ],\n      \"pt\": [\n        \"Não espere fidelidade de CSS: só a estrutura semântica é interpretada.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Same contract as AppMarkdown: native selection, image alt as the label, tappable links (Tab focus pending).\",\n      \"pt\": \"Mesmo contrato do AppMarkdown: seleção nativa, alt de imagem como rótulo, links tocáveis (foco por Tab pendente).\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_markdown\",\n      \"app_simple_data_table\"\n    ]\n  },\n  {\n    \"id\": \"app_code_block\",\n    \"name\": \"AppCodeBlock\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Monospaced code block with a language label and a copy control.\",\n      \"pt\": \"Bloco de código monoespaçado com rótulo de linguagem e copiar.\"\n    },\n    \"description\": {\n      \"en\": \"It shares the AppContentStyle leaf with AppMarkdown/AppHtml — same mono family, same background, same padding and same radius — so a standalone payload looks identical to the same snippet inside a document. By default it scrolls horizontally instead of wrapping, which preserves the indentation of JSON and of shell commands. Copy writes to the clipboard and swaps the icon for a temporary check.\",\n      \"pt\": \"Divide a folha AppContentStyle com AppMarkdown/AppHtml — mesma família mono, mesmo fundo, mesmo padding e mesmo raio —, então um payload avulso fica idêntico ao mesmo trecho dentro de um documento. Por padrão rola na horizontal em vez de quebrar linha, o que preserva a indentação de JSON e de comandos de shell. Copiar escreve na área de transferência e troca o ícone por um check temporário.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"A request/response payload, a cURL command, a configuration snippet.\",\n        \"Any text that has to be copied whole, without reflowing.\"\n      ],\n      \"pt\": [\n        \"Payload de request/response, comando cURL, trecho de configuração.\",\n        \"Qualquer texto que precise ser copiado inteiro, sem reflow.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A whole document mixing prose and code → AppMarkdown.\",\n        \"A short identifier in the middle of a sentence → AppRichText's inline code.\"\n      ],\n      \"pt\": [\n        \"Documento inteiro com prosa + código → AppMarkdown.\",\n        \"Um identificador curto no meio de uma frase → código inline do AppRichText.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"code\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"language\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"showCopy\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"wrap\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      },\n      {\n        \"name\": \"selectable\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"copyTooltip\",\n        \"type\": \"String\",\n        \"required\": false,\n        \"default\": \"'Copiar'\"\n      },\n      {\n        \"name\": \"copiedTooltip\",\n        \"type\": \"String\",\n        \"required\": false,\n        \"default\": \"'Copiado'\"\n      },\n      {\n        \"name\": \"onCopy\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppStyle?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"radiusMode\",\n        \"type\": \"AppRadiusMode?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"default\",\n      \"copied\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"JSON payload\",\n          \"pt\": \"Payload JSON\"\n        },\n        \"code\": \"AppCodeBlock(code: requestJson, language: 'json')\"\n      },\n      {\n        \"title\": {\n          \"en\": \"A command, wrapping\",\n          \"pt\": \"Comando, quebrando linha\"\n        },\n        \"code\": \"AppCodeBlock(code: curl, language: 'bash', wrap: true)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Label the language — it is what tells the reader what they are about to paste.\",\n        \"Leave wrap: false for JSON; the indentation is part of the information.\"\n      ],\n      \"pt\": [\n        \"Rotule a linguagem — é o que diz ao leitor o que ele vai colar.\",\n        \"Deixe wrap: false para JSON; a indentação é parte da informação.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not put prose here; mono penalizes running text.\"\n      ],\n      \"pt\": [\n        \"Não coloque prosa aqui; o mono penaliza a leitura corrida.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"The copy button is an AppInteraction with a tooltip and a semantic label that follows the state (Copy/Copied), activatable by keyboard. The code is selectable by default; the header is excluded from the selection so it does not pollute text copied by hand.\",\n      \"pt\": \"O botão de copiar é um AppInteraction com tooltip e rótulo semântico que acompanha o estado (Copiar/Copiado), ativável por teclado. O código fica selecionável por padrão; o cabeçalho é excluído da seleção para não poluir o texto copiado à mão.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_markdown\",\n      \"app_html\",\n      \"app_api_endpoint_tile\"\n    ]\n  },\n  {\n    \"id\": \"app_data_table\",\n    \"name\": \"AppDataTable\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Paginated table with per-column sorting (the backoffice grids).\",\n      \"pt\": \"Tabela paginada com ordenação por coluna (grids do backoffice).\"\n    },\n    \"description\": {\n      \"en\": \"A generic grid: labelled columns, rows of widgets, pagination (page/perPage/total) and per-column sorting (none→desc→asc). It supports click, right-click and row selection. No Material — the sort header's tooltip uses AppTooltip. Colors 100% from the theme.\",\n      \"pt\": \"Grid genérico: colunas rotuladas, linhas de widgets, paginação (page/perPage/total) e ordenação por coluna (none→desc→asc). Suporta clique/clique-direito/seleção de linha. Sem Material — o tooltip do header de ordenação usa AppTooltip. Cores 100% do tema.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Paginated backoffice listings (CRUDs) with sorting and row actions.\"\n      ],\n      \"pt\": [\n        \"Listagens paginadas do backoffice (CRUDs) com ordenação e ações de linha.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A short static table, with no pagination or sorting → AppSimpleDataTable.\"\n      ],\n      \"pt\": [\n        \"Tabela estática curta, sem paginação/ordenação → AppSimpleDataTable.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"columnLabels\",\n        \"type\": \"List<String>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"rows\",\n        \"type\": \"List<List<Widget>>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"page\",\n        \"type\": \"int\",\n        \"required\": true\n      },\n      {\n        \"name\": \"perPage\",\n        \"type\": \"int\",\n        \"required\": true\n      },\n      {\n        \"name\": \"total\",\n        \"type\": \"int\",\n        \"required\": true\n      },\n      {\n        \"name\": \"totalPages\",\n        \"type\": \"int\",\n        \"required\": true\n      },\n      {\n        \"name\": \"columnSortOrders\",\n        \"type\": \"List<AppDataTableSortOrder>?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onColumnSortTap\",\n        \"type\": \"void Function(int)?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onRowTap\",\n        \"type\": \"void Function(int)?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"selectedRowIndex\",\n        \"type\": \"int?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"default\",\n      \"sorted\",\n      \"row-selected\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Paginated grid\",\n          \"pt\": \"Grid paginado\"\n        },\n        \"code\": \"AppDataTable(columnLabels: cols, rows: rows, page: page, perPage: 16, total: total, totalPages: pages, onPageChange: cubit.setPage, onPerPageChange: cubit.setPerPage)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Pagination is server-side; pass the counters coming from the backend.\"\n      ],\n      \"pt\": [\n        \"Paginação é server-side; passe os contadores vindos do backend.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it for a few fixed rows (AppSimpleDataTable).\"\n      ],\n      \"pt\": [\n        \"Não use para poucas linhas fixas (AppSimpleDataTable).\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Sort headers with an AppTooltip describe the next state. The colors (surface/onSurface/outline) pass AA in light and dark.\",\n      \"pt\": \"Headers de ordenação com AppTooltip descrevem o próximo estado. Cores (surface/onSurface/outline) passam AA em claro/escuro.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_simple_data_table\",\n      \"app_pagination\"\n    ]\n  },\n  {\n    \"id\": \"app_simple_data_table\",\n    \"name\": \"AppSimpleDataTable\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Static table (header + rows), with no sorting or pagination.\",\n      \"pt\": \"Tabela estática (header + linhas), sem ordenação/paginação.\"\n    },\n    \"description\": {\n      \"en\": \"A simple grid: labelled columns and rows of widgets, with no pagination and no sorting. Ideal for short blocks (e.g. assistant replies). Colors 100% from the theme; selectable text (AppSelectionRegion).\",\n      \"pt\": \"Grid simples: colunas rotuladas e linhas de widgets, sem paginação nem ordenação. Ideal para blocos curtos (ex.: respostas do assistente). Cores 100% do tema; texto selecionável (AppSelectionRegion).\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Showing a few fixed rows with a header.\"\n      ],\n      \"pt\": [\n        \"Mostrar poucas linhas fixas com cabeçalho.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A large paginated listing with sorting → AppDataTable.\"\n      ],\n      \"pt\": [\n        \"Listagem grande/paginada com ordenação → AppDataTable.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"columnLabels\",\n        \"type\": \"List<String>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"rows\",\n        \"type\": \"List<List<Widget>>\",\n        \"required\": true\n      }\n    ],\n    \"states\": [\n      \"default\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Short table\",\n          \"pt\": \"Tabela curta\"\n        },\n        \"code\": \"AppSimpleDataTable(columnLabels: ['Chave', 'Valor'], rows: rows)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use it for short, static blocks.\"\n      ],\n      \"pt\": [\n        \"Use para blocos curtos e estáticos.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it when you need pagination or sorting.\"\n      ],\n      \"pt\": [\n        \"Não use quando precisar paginar/ordenar.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Text selectable through AppSelectionRegion. The theme's colors pass AA in light and dark.\",\n      \"pt\": \"Texto selecionável via AppSelectionRegion. Cores do tema passam AA em claro/escuro.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_data_table\"\n    ]\n  },\n  {\n    \"id\": \"app_navigation_rail\",\n    \"name\": \"AppNavigationRail\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Collapsible side menu with items and sub-items (the app's navigation).\",\n      \"pt\": \"Menu lateral colapsável com itens e subitens (navegação do app).\"\n    },\n    \"description\": {\n      \"en\": \"A vertical navigation rail: logo, items (icon + title), expandable parent items and a generic footer slot (e.g. Support + profile), collapsible between a narrow mode (icons only) and a wide one. Collapse/expand is triggered by a floating circular chevron on the right edge (with no outline). A collapsed item shows its title through AppTooltip (no Material). Colors 100% from the theme; hover and selection use the primary accent and the global radius; the transition uses motion tokens (reduce-motion).\",\n      \"pt\": \"Rail de navegação vertical: logo, itens (ícone + título), itens-pai expansíveis e um slot de footer genérico (ex.: Suporte + perfil), colapsável entre modo estreito (só ícones) e largo. O colapso/expansão é acionado por um chevron circular flutuante na borda direita (sem borda de contorno). Item colapsado mostra o título via AppTooltip (sem Material). Cores 100% do tema; hover/seleção usam o accent primário e o raio global; a transição usa tokens de motion (reduce-motion).\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Primary side navigation for the backoffice/desktop.\"\n      ],\n      \"pt\": [\n        \"Navegação primária lateral do backoffice/desktop.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Horizontal tabs within a section → AppTabView.\",\n        \"Bottom navigation on mobile → AppNavigationFooter.\"\n      ],\n      \"pt\": [\n        \"Abas horizontais de uma seção → AppTabView.\",\n        \"Navegação inferior no mobile → AppNavigationFooter.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"items\",\n        \"type\": \"List<AppNavigationRailItemData>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"getCurrentRoute\",\n        \"type\": \"String Function(BuildContext)\",\n        \"required\": true\n      },\n      {\n        \"name\": \"logoCollapsed\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"logoExpanded\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"footer\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"showFooterDivider\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"decoration\",\n        \"type\": \"BoxDecoration?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"collapsed\",\n      \"expanded\",\n      \"item-selected\",\n      \"item-hovered\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Side menu\",\n          \"pt\": \"Menu lateral\"\n        },\n        \"code\": \"AppNavigationRail(items: items, logoCollapsed: logo, getCurrentRoute: (c) => router.location)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use the same icon in both modes (collapsed/expanded).\"\n      ],\n      \"pt\": [\n        \"Use o mesmo ícone nos dois modos (colapsado/expandido).\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not nest more than one level of sub-items.\"\n      ],\n      \"pt\": [\n        \"Não aninhe mais de um nível de subitens.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Collapsed items expose their title through AppTooltip; clickable items carry Semantics(button:true, label:). The primary accent over the surface passes AA; the floating chevron has a tooltip + semanticLabel.\",\n      \"pt\": \"Itens colapsados expõem o título por AppTooltip; itens clicáveis têm Semantics(button:true, label:). O accent primário sobre a superfície passa AA; o chevron flutuante tem tooltip + semanticLabel.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_navigation_rail_item\",\n      \"app_navigation_rail_profile\",\n      \"app_tab_view\"\n    ]\n  },\n  {\n    \"id\": \"app_navigation_rail_item\",\n    \"name\": \"AppNavigationRailItem\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"An AppNavigationRail item (icon + title, with states).\",\n      \"pt\": \"Item de um AppNavigationRail (ícone + título, com estados).\"\n    },\n    \"description\": {\n      \"en\": \"A clickable rail row: icon + title (hidden in collapsed mode), with selection and hover states (a pill tinted by the primary accent, radius following the global axis). Collapsed, it exposes the title through AppTooltip. If isCollapsed is null, it reads the state from AppNavigationRailScope (useful in the footer slot). Colors from the theme; transition on motion tokens.\",\n      \"pt\": \"Linha clicável do rail: ícone + título (oculto no modo colapsado), com estados de seleção e hover (pill tingido pelo accent primário, raio seguindo o eixo global). Colapsado, expõe o título via AppTooltip. Se isCollapsed for null, lê o estado do AppNavigationRailScope (útil no slot de footer). Cores do tema; transição por tokens de motion.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Composing an AppNavigationRail (usually through AppNavigationRailItemData).\"\n      ],\n      \"pt\": [\n        \"Compor um AppNavigationRail (normalmente via AppNavigationRailItemData).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A generic list row → AppListTile.\"\n      ],\n      \"pt\": [\n        \"Linha de lista genérica → AppListTile.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"icon\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"isCollapsed\",\n        \"type\": \"bool?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onPressed\",\n        \"type\": \"VoidCallback\",\n        \"required\": true\n      },\n      {\n        \"name\": \"isSelected\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      },\n      {\n        \"name\": \"showSelectedBackground\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"title\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"trailing\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"default\",\n      \"selected\",\n      \"hovered\",\n      \"collapsed\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Selected item\",\n          \"pt\": \"Item selecionado\"\n        },\n        \"code\": \"AppNavigationRailItem(icon: home, title: 'Início', isCollapsed: false, isSelected: true, onPressed: go)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Pass a title for the tooltip in collapsed mode.\"\n      ],\n      \"pt\": [\n        \"Passe title para o tooltip no modo colapsado.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it outside an AppNavigationRail.\"\n      ],\n      \"pt\": [\n        \"Não use fora de um AppNavigationRail.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Semantics(button:true, label:) + a tooltip when collapsed. Icon and text colors reflect the selection and pass AA.\",\n      \"pt\": \"Semantics(button:true, label:) + tooltip no colapsado. Cores de ícone/texto refletem seleção e passam AA.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_navigation_rail\"\n    ]\n  },\n  {\n    \"id\": \"app_navigation_rail_profile\",\n    \"name\": \"AppNavigationRailProfile\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Profile row (avatar + name/role + trailing) for the footer.\",\n      \"pt\": \"Linha de perfil (avatar + nome/papel + trailing) para o footer.\"\n    },\n    \"description\": {\n      \"en\": \"A clickable row for AppNavigationRail's footer slot: avatar + title/subtitle + trailing (a chevron by default). Clickable through AppInteraction (radius follows the global axis). Collapsed, it shows only the avatar — reading the state from AppNavigationRailScope (or from isCollapsed).\",\n      \"pt\": \"Linha clicável para o slot de footer do AppNavigationRail: avatar + título/subtítulo + trailing (chevron por padrão). Clicável via AppInteraction (raio segue o eixo global). Colapsado, mostra só o avatar — lê o estado do AppNavigationRailScope (ou de isCollapsed).\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"The signed-in user's identity in the rail's footer (it opens the profile).\"\n      ],\n      \"pt\": [\n        \"Identidade do usuário logado no rodapé do rail (abre o perfil).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A generic list row with an avatar → AppListTile.navigation.\"\n      ],\n      \"pt\": [\n        \"Linha de lista genérica com avatar → AppListTile.navigation.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"title\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"subtitle\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"imageUrl\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"initials\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"trailing\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onTap\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"isCollapsed\",\n        \"type\": \"bool?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"default\",\n      \"collapsed\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Profile in the footer\",\n          \"pt\": \"Perfil no footer\"\n        },\n        \"code\": \"AppNavigationRailProfile(title: 'João M.', subtitle: 'Operador', initials: 'JM', onTap: openProfile)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use it inside AppNavigationRail's footer slot.\"\n      ],\n      \"pt\": [\n        \"Use dentro do slot footer do AppNavigationRail.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not force isCollapsed — let the scope resolve it.\"\n      ],\n      \"pt\": [\n        \"Não force isCollapsed — deixe o scope resolver.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"AppInteraction exposes Semantics(button:true) with the label \\\"name, role\\\"; the avatar has a semanticLabel carrying the name.\",\n      \"pt\": \"AppInteraction expõe Semantics(button:true) com label \\\"nome, papel\\\"; avatar tem semanticLabel com o nome.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_navigation_rail\",\n      \"app_avatar\"\n    ]\n  },\n  {\n    \"id\": \"app_navigation_rail_filter\",\n    \"name\": \"AppNavigationRailFilter\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Filter row for the rail's footer: icon, filter name and selected value.\",\n      \"pt\": \"Linha de filtro para o rodapé do rail: ícone, nome do filtro e valor selecionado.\"\n    },\n    \"description\": {\n      \"en\": \"It keeps a global scope (account, group, client) visible at all times without taking up the top bar. Use the SAME icon the entity has in the menu — that is what makes the current slice recognizable at a glance. With no value selected it shows \\\"All\\\", making it explicit that no slice is in force, instead of leaving an ambiguous empty space. Collapsed, only the icon remains, with the slice in the tooltip. It reads the collapsed state from AppNavigationRailScope.\",\n      \"pt\": \"Deixa um escopo global (conta, grupo, cliente) visível o tempo todo sem ocupar a barra superior. Use o MESMO ícone que a entidade tem no menu — é o que faz reconhecer o recorte de relance. Sem valor selecionado mostra \\\"Todos\\\", deixando explícito que não há recorte em vigor, em vez de um espaço vazio ambíguo. Colapsado sobra só o ícone, com o recorte no tooltip. Lê o estado colapsado do AppNavigationRailScope.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"A scope filter that applies to the whole app and has to stay in sight.\"\n      ],\n      \"pt\": [\n        \"Filtro de escopo que vale para o app inteiro e precisa estar sempre à vista.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A filter for a single screen → a field in that screen's own toolbar.\",\n        \"A selection with many options and no search → AppSearchableDropdown.\"\n      ],\n      \"pt\": [\n        \"Filtro de uma tela só → um campo na toolbar da própria tela.\",\n        \"Seleção com muitas opções sem busca → AppSearchableDropdown.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"icon\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"label\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"value\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"emptyLabel\",\n        \"type\": \"String\",\n        \"required\": false,\n        \"default\": \"kAppNavigationRailFilterAllLabel\"\n      },\n      {\n        \"name\": \"onTap\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"enabled\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\",\n        \"description\": {\n          \"en\": \"false dims it and blocks touch, but keeps the value legible — the user needs to understand why the filter does not apply.\",\n          \"pt\": \"false esmaece e bloqueia o toque, mas mantém o valor legível — o usuário precisa entender por que o filtro não se aplica.\"\n        }\n      },\n      {\n        \"name\": \"isCollapsed\",\n        \"type\": \"bool?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"default\",\n      \"empty\",\n      \"disabled\",\n      \"collapsed\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Group in the footer\",\n          \"pt\": \"Grupo no rodapé\"\n        },\n        \"code\": \"AppNavigationRailFilter(icon: AppIconToken.group, label: 'Grupo', value: selectedGroupName, onTap: openGroupPicker)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Repeat the icon the entity has in the menu.\",\n        \"Let \\\"All\\\" show — it is information, not emptiness.\"\n      ],\n      \"pt\": [\n        \"Repita o ícone que a entidade tem no menu.\",\n        \"Deixe \\\"Todos\\\" aparecer — é informação, não vazio.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not hide the row when nothing is selected.\",\n        \"Do not force isCollapsed — let the scope resolve it.\"\n      ],\n      \"pt\": [\n        \"Não esconda a linha quando não há seleção.\",\n        \"Não force isCollapsed — deixe o scope resolver.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"AppInteraction exposes Semantics(button:true) with the label \\\"filter: value\\\"; collapsed, that same text goes to the AppTooltip.\",\n      \"pt\": \"AppInteraction expõe Semantics(button:true) com label \\\"filtro: valor\\\"; colapsado, o mesmo texto vai para o AppTooltip.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_navigation_rail\",\n      \"app_navigation_rail_profile\"\n    ]\n  },\n  {\n    \"id\": \"app_form_wizard\",\n    \"name\": \"AppFormWizard\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Multi-step form with an indicator (at the side on desktop, on top on mobile).\",\n      \"pt\": \"Formulário multi-passo com indicador (lateral no desktop, topo no mobile).\"\n    },\n    \"description\": {\n      \"en\": \"A step wizard: a progress indicator (at the side on desktop, on top on mobile, through AppDevice) + the current step's panel (lazy). Each step (AppFormWizardStep) has a title, an optional subtitle/icon, a content builder and a validator. Colors 100% from the theme; the panel transition runs on motion tokens.\",\n      \"pt\": \"Wizard de passos: indicador de progresso (lateral no desktop, topo no mobile, via AppDevice) + o painel do passo atual (lazy). Cada passo (AppFormWizardStep) tem título, subtítulo/ícone opcionais, builder do conteúdo e validador. Cores 100% do tema; transição do painel via tokens de motion.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"A registration or flow split into steps with visible progress.\"\n      ],\n      \"pt\": [\n        \"Cadastro/fluxo dividido em etapas com progresso visível.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Parallel tabs with no order or progress → AppTabView.\"\n      ],\n      \"pt\": [\n        \"Abas paralelas sem ordem/progresso → AppTabView.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"currentStep\",\n        \"type\": \"int\",\n        \"required\": true\n      },\n      {\n        \"name\": \"steps\",\n        \"type\": \"List<AppFormWizardStep>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"onStepTapped\",\n        \"type\": \"ValueChanged<int>?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"showIndicator\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      }\n    ],\n    \"states\": [\n      \"step-active\",\n      \"step-done\",\n      \"step-pending\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"3-step wizard\",\n          \"pt\": \"Wizard de 3 passos\"\n        },\n        \"code\": \"AppFormWizard(currentStep: step, steps: steps, onStepTapped: cubit.goTo)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Validate each step before advancing (step.validator).\"\n      ],\n      \"pt\": [\n        \"Valide cada passo antes de avançar (step.validator).\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it for navigation with no order (AppTabView).\"\n      ],\n      \"pt\": [\n        \"Não use para navegação sem ordem (AppTabView).\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"The indicator reflects the active/completed/pending step by color (all from the theme, AA). The step's panel is focusable in reading order.\",\n      \"pt\": \"O indicador reflete o passo ativo/concluído/pendente por cor (todas do tema, AA). O painel do passo é focável na ordem de leitura.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_tab_view\",\n      \"app_stepper\"\n    ]\n  },\n  {\n    \"id\": \"app_tab_view\",\n    \"name\": \"AppTabView\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Horizontal tabs with a sliding indicator and lazy loading.\",\n      \"pt\": \"Abas horizontais com indicador deslizante e carga preguiçosa.\"\n    },\n    \"description\": {\n      \"en\": \"A tab bar (AppTabViewItem: label + builder) with an indicator that slides to the active tab and content loaded on demand (lazyLoadOnFirstOpen). Colors 100% from the theme; the indicator animates on motion tokens, honoring reduce-motion.\",\n      \"pt\": \"Barra de abas (AppTabViewItem: label + builder) com um indicador que desliza para a aba ativa e conteúdo carregado sob demanda (lazyLoadOnFirstOpen). Cores 100% do tema; o indicador anima via tokens de motion, respeitando reduce-motion.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Switching between parallel sections of one context.\"\n      ],\n      \"pt\": [\n        \"Alternar entre seções paralelas de um mesmo contexto.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A flow with an order or progress → AppFormWizard.\",\n        \"The app's primary navigation → AppNavigationRail.\"\n      ],\n      \"pt\": [\n        \"Fluxo com ordem/progresso → AppFormWizard.\",\n        \"Navegação primária do app → AppNavigationRail.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"items\",\n        \"type\": \"List<AppTabViewItem>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"initialIndex\",\n        \"type\": \"int\",\n        \"required\": false,\n        \"default\": \"0\"\n      },\n      {\n        \"name\": \"lazyLoadOnFirstOpen\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"onTabChanged\",\n        \"type\": \"ValueChanged<int>?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"contentPadding\",\n        \"type\": \"EdgeInsetsGeometry\",\n        \"required\": false,\n        \"default\": \"EdgeInsets.symmetric(horizontal: AppSpacings.s8)\"\n      }\n    ],\n    \"states\": [\n      \"tab-active\",\n      \"tab-inactive\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Two tabs\",\n          \"pt\": \"Duas abas\"\n        },\n        \"code\": \"AppTabView(items: [AppTabViewItem(label: \\\"Resumo\\\", builder: ...), AppTabViewItem(label: \\\"Detalhes\\\", builder: ...)])\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Short labels; the active tab is marked by the indicator.\"\n      ],\n      \"pt\": [\n        \"Rótulos curtos; a aba ativa é destacada pelo indicador.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it for a sequential flow (AppFormWizard).\"\n      ],\n      \"pt\": [\n        \"Não use para fluxo sequencial (AppFormWizard).\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"The active tab is highlighted by color (from the theme, AA). The content enters the reading focus order.\",\n      \"pt\": \"A aba ativa é destacada por cor (do tema, AA). O conteúdo entra na ordem de foco de leitura.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_form_wizard\",\n      \"app_navigation_rail\"\n    ]\n  },\n  {\n    \"id\": \"app_resizable_panel\",\n    \"name\": \"AppResizablePanel\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Panel whose width is dragged (in px) from one of its edges.\",\n      \"pt\": \"Painel com largura arrastável (px) por uma das bordas.\"\n    },\n    \"description\": {\n      \"en\": \"The sibling of a lone AppResizableSplit panel: when there are not two panels to divide — the case of AppShell's aside slot, which needs full height beside the header — the split does not serve, but the affordance is the same (both share the gutter internally). The measure is absolute (px), not a fraction: it expresses \\\"a floor of 380px and the user chooses upward from there\\\". **maxWidth is required and comes from the caller**: as a non-flexible child of a Row the panel receives an unbounded constraint, so the ceiling cannot be inferred through a LayoutBuilder. The width is re-clamped on every build, accommodating a restored value larger than the current ceiling. **Persistence belongs to the caller** (DI): restore into initialWidth and save from onWidthChanged. Double-tapping the handle resets it.\",\n      \"pt\": \"O irmão de um painel só do AppResizableSplit: quando não há dois painéis para dividir — o caso do slot aside do AppShell, que precisa de altura total ao lado do header — o split não serve, mas a afordância é a mesma (as duas compartilham a calha internamente). A medida é absoluta (px), não fração: expressa \\\"piso de 380px e o usuário escolhe daí para cima\\\". **maxWidth é obrigatório e vem do chamador**: como filho não flexível de um Row o painel recebe constraint unbounded, então não dá para inferir o teto por LayoutBuilder. A largura é reclampada a cada build, acomodando um valor restaurado maior que o teto atual. **Persistência é do chamador** (DI): restaure em initialWidth e salve em onWidthChanged. Duplo-toque na alça reseta.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"A side panel whose width the user sets, with no sibling to divide (e.g. the assistant in AppShell's aside).\",\n        \"When the rule is an absolute floor in px, not a proportion of the window.\"\n      ],\n      \"pt\": [\n        \"Painel lateral com largura definida pelo usuário e sem irmão para dividir (ex.: o assistente no aside do AppShell).\",\n        \"Quando a regra é um piso absoluto em px, não uma proporção da janela.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Two sibling panels sharing the space → AppResizableSplit.\",\n        \"A fixed width with no adjustment → SizedBox.\"\n      ],\n      \"pt\": [\n        \"Dois painéis irmãos dividindo o espaço → AppResizableSplit.\",\n        \"Largura fixa sem ajuste → SizedBox.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"child\",\n        \"type\": \"Widget\",\n        \"required\": true\n      },\n      {\n        \"name\": \"initialWidth\",\n        \"type\": \"double\",\n        \"required\": true,\n        \"description\": {\n          \"en\": \"Initial width, and the double-tap target (reset).\",\n          \"pt\": \"Largura inicial e alvo do duplo-toque (reset).\"\n        }\n      },\n      {\n        \"name\": \"maxWidth\",\n        \"type\": \"double\",\n        \"required\": true,\n        \"description\": {\n          \"en\": \"Ceiling — compute it at the source (e.g. MediaQuery); it cannot be inferred.\",\n          \"pt\": \"Teto — calcule na origem (ex.: MediaQuery), não é inferível.\"\n        }\n      },\n      {\n        \"name\": \"minWidth\",\n        \"type\": \"double\",\n        \"required\": false,\n        \"default\": \"0\"\n      },\n      {\n        \"name\": \"edge\",\n        \"type\": \"AppResizeEdge\",\n        \"required\": false,\n        \"default\": \"AppResizeEdge.start\",\n        \"description\": {\n          \"en\": \"Edge the handle sits on: start = left in LTR.\",\n          \"pt\": \"Borda da alça: start = esquerda no LTR.\"\n        }\n      },\n      {\n        \"name\": \"onWidthChanged\",\n        \"type\": \"ValueChanged<double>?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Save the value here to persist it (persistence is yours).\",\n          \"pt\": \"Salve o valor aqui para persistir (a persistência é sua).\"\n        }\n      },\n      {\n        \"name\": \"thickness\",\n        \"type\": \"double\",\n        \"required\": false,\n        \"default\": \"AppSpacings.s16\"\n      },\n      {\n        \"name\": \"tooltip\",\n        \"type\": \"String?\",\n        \"required\": false,\n        \"default\": \"'Redimensionar'\"\n      }\n    ],\n    \"variants\": [\n      \"edge.start\",\n      \"edge.end\"\n    ],\n    \"states\": [\n      \"idle\",\n      \"hovered\",\n      \"dragging\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Assistant in the shell's aside\",\n          \"pt\": \"Assistente no aside do shell\"\n        },\n        \"code\": \"AppResizablePanel(initialWidth: restored ?? 380, minWidth: 380, maxWidth: MediaQuery.sizeOf(context).width / 2, onWidthChanged: (w) => storage.write(key, w), child: assistant)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Restore the width in the caller and pass it in initialWidth.\",\n        \"Compute maxWidth from the window — the panel cannot infer it.\",\n        \"Give it a bounded height: the content is stretched on the cross axis.\"\n      ],\n      \"pt\": [\n        \"Restaure a largura no chamador e passe em initialWidth.\",\n        \"Calcule maxWidth a partir da janela — o painel não consegue inferir.\",\n        \"Dê altura limitada: o conteúdo é esticado no eixo cruzado.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not expect the component to persist anything by itself (that is the app's job).\",\n        \"Do not use it to divide two panels — that is AppResizableSplit.\"\n      ],\n      \"pt\": [\n        \"Não espere que o componente persista sozinho (é do app).\",\n        \"Não use para dividir dois painéis — isso é AppResizableSplit.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"The gutter has a tooltip (AppTooltip), a resizeColumn cursor and its own drag target; the handle's color comes from the theme (AA in light and dark).\",\n      \"pt\": \"A calha tem tooltip (AppTooltip), cursor resizeColumn e alvo de arraste próprio; a cor da alça vem do tema (AA em claro/escuro).\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_resizable_split\",\n      \"app_shell\",\n      \"app_assistant_panel\"\n    ]\n  },\n  {\n    \"id\": \"app_resizable_split\",\n    \"name\": \"AppResizableSplit\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Two panels with a draggable divider (horizontal or vertical).\",\n      \"pt\": \"Dois painéis com divisor arrastável (horizontal ou vertical).\"\n    },\n    \"description\": {\n      \"en\": \"A resizable-panel layout with a draggable divider between [first] and [second]. The split is a fraction (0..1) that scales with the window. **Persistence belongs to the caller** (DI): pass the restored value in initialFirstFraction and save new ones from onFractionChanged — the design system does not depend on storage. Double-tapping the divider resets it. Colors from the theme; the handle's hover runs on motion tokens (reduce-motion).\",\n      \"pt\": \"Layout de painéis redimensionáveis com um divisor arrastável entre [first] e [second]. O split é uma fração (0..1) que escala com a janela. **Persistência é do chamador** (DI): passe o valor restaurado em initialFirstFraction e salve os novos em onFractionChanged — o DS não depende de storage. Duplo-toque no divisor reseta. Cores do tema; hover do handle via tokens de motion (reduce-motion).\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Sidebar + content (e.g. a list + a map) with an adjustable width.\"\n      ],\n      \"pt\": [\n        \"Sidebar + conteúdo (ex.: lista + mapa) com largura ajustável.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A fixed division with no adjustment → a Row/Column with Expanded.\",\n        \"A single panel with no sibling to divide → AppResizablePanel.\"\n      ],\n      \"pt\": [\n        \"Divisão fixa sem ajuste → um Row/Column com Expanded.\",\n        \"Um painel só, sem irmão para dividir → AppResizablePanel.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"first\",\n        \"type\": \"Widget\",\n        \"required\": true\n      },\n      {\n        \"name\": \"second\",\n        \"type\": \"Widget\",\n        \"required\": true\n      },\n      {\n        \"name\": \"direction\",\n        \"type\": \"Axis\",\n        \"required\": false,\n        \"default\": \"Axis.horizontal\"\n      },\n      {\n        \"name\": \"initialFirstFraction\",\n        \"type\": \"double\",\n        \"required\": false,\n        \"default\": \"0.5\"\n      },\n      {\n        \"name\": \"onFractionChanged\",\n        \"type\": \"ValueChanged<double>?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Save the value here to persist it (persistence is yours).\",\n          \"pt\": \"Salve o valor aqui para persistir (a persistência é sua).\"\n        }\n      },\n      {\n        \"name\": \"minFirstSize\",\n        \"type\": \"double?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"minSecondSize\",\n        \"type\": \"double?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"idle\",\n      \"hovered\",\n      \"dragging\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Sidebar + map\",\n          \"pt\": \"Sidebar + mapa\"\n        },\n        \"code\": \"AppResizableSplit(initialFirstFraction: restored ?? 0.22, onFractionChanged: (f) => storage.write(key, f), first: sidebar, second: map)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Restore the fraction in the caller and pass it in initialFirstFraction.\",\n        \"Use minFirstSize/minSecondSize so a panel cannot collapse.\"\n      ],\n      \"pt\": [\n        \"Restaure a fração no chamador e passe em initialFirstFraction.\",\n        \"Use minFirstSize/minSecondSize para não colapsar um painel.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not expect the component to persist anything by itself (that is the app's job).\"\n      ],\n      \"pt\": [\n        \"Não espere que o componente persista sozinho (é do app).\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"The divider has a tooltip (AppTooltip) and its own drag target; the handle's colors come from the theme (AA in light and dark).\",\n      \"pt\": \"O divisor tem tooltip (AppTooltip) e alvo de arraste próprio; cores do handle vêm do tema (AA em claro/escuro).\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_scaffold\",\n      \"app_resizable_panel\"\n    ]\n  },\n  {\n    \"id\": \"app_workspace_tabs\",\n    \"name\": \"AppWorkspaceTabs\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Browser-style tab bar (icon + title + close).\",\n      \"pt\": \"Barra de abas estilo navegador (ícone + título + fechar).\"\n    },\n    \"description\": {\n      \"en\": \"The desktop workspace's \\\"browser-like\\\" tab strip: tabs with an icon, a title and a close button. A **controlled** component (state lives outside). Only the active tab has a fill (a `tertiary` tone), with rounded top corners. Colors 100% from the theme; hover and fade on motion tokens (reduce-motion).\",\n      \"pt\": \"Tab strip \\\"browser-like\\\" do workspace desktop: abas com ícone, título e botão de fechar. Componente **controlado** (estado fora). Só a aba ativa tem preenchimento (tom `tertiary`), cantos arredondados no topo. Cores 100% do tema; hover/fade via tokens de motion (reduce-motion).\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Workspace tabs on desktop (open/close/select).\"\n      ],\n      \"pt\": [\n        \"Abas de workspace no desktop (abrir/fechar/selecionar).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Content tabs within a section → AppTabView.\"\n      ],\n      \"pt\": [\n        \"Abas de conteúdo de uma seção → AppTabView.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"tabs\",\n        \"type\": \"List<AppWorkspaceTabItem>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"activeId\",\n        \"type\": \"String?\",\n        \"required\": true\n      },\n      {\n        \"name\": \"onSelect\",\n        \"type\": \"ValueChanged<String>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"onClose\",\n        \"type\": \"ValueChanged<String>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"decoration\",\n        \"type\": \"BoxDecoration?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"tab-active\",\n      \"tab-inactive\",\n      \"tab-hovered\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Workspace tabs\",\n          \"pt\": \"Abas do workspace\"\n        },\n        \"code\": \"AppWorkspaceTabs(tabs: tabs, activeId: active, onSelect: cubit.select, onClose: cubit.close)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Keep the tabs' state outside (a controlled component).\"\n      ],\n      \"pt\": [\n        \"Mantenha o estado das abas fora (componente controlado).\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it for content tabs (AppTabView).\"\n      ],\n      \"pt\": [\n        \"Não use para abas de conteúdo (AppTabView).\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"The active tab is highlighted by color (tertiary, from the theme, AA). The close button has its own touch target.\",\n      \"pt\": \"A aba ativa é destacada por cor (tertiary, do tema, AA). O botão de fechar tem alvo de toque próprio.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_tab_view\"\n    ]\n  },\n  {\n    \"id\": \"app_overlay_alert\",\n    \"name\": \"AppOverlayAlert\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Alert card with a semantic color through a ColorSwatch (AppAlert's sibling).\",\n      \"pt\": \"Card de alerta com cor semântica via ColorSwatch (irmão do AppAlert).\"\n    },\n    \"description\": {\n      \"en\": \"The alert variant that takes the semantic color as a ColorSwatch (color) instead of an enum. surfaceContainer tinted by the color, container on the AppStyle axis (elevated by default), shape from the radius axis. Colors 100% from the theme; announced (liveRegion). Prefer AppAlert whenever the role enum will do.\",\n      \"pt\": \"Variante do alerta que recebe a cor semântica como um ColorSwatch (color) em vez de um enum. surfaceContainer tingido pela cor, container no eixo AppStyle (default elevated), forma pelo eixo de raio. Cores 100% do tema; anunciado (liveRegion). Prefira AppAlert quando puder usar o enum de papéis.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"An alert when you already have the semantic swatch (not the enum).\"\n      ],\n      \"pt\": [\n        \"Alerta quando você já tem o swatch semântico (não o enum).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A known semantic role (info/success/warning/danger) → AppAlert.\"\n      ],\n      \"pt\": [\n        \"Papel semântico conhecido (info/success/warning/danger) → AppAlert.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"title\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"description\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"color\",\n        \"type\": \"ColorSwatch<int>?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Semantic swatch; null uses the theme's info.\",\n          \"pt\": \"Swatch semântico; null usa info do tema.\"\n        }\n      },\n      {\n        \"name\": \"icon\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppStyle?\",\n        \"required\": false,\n        \"default\": \"AppStyle.elevated\",\n        \"enumValues\": [\n          \"filled\",\n          \"outlined\",\n          \"elevated\"\n        ]\n      },\n      {\n        \"name\": \"radiusMode\",\n        \"type\": \"AppRadiusMode?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"default\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Error alert\",\n          \"pt\": \"Alerta de erro\"\n        },\n        \"code\": \"AppOverlayAlert(title: 'Falha', description: '...', color: theme.colorTheme.danger)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use the semantic color that matches the message.\"\n      ],\n      \"pt\": [\n        \"Use a cor semântica que casa com a mensagem.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not stack several in the same corner.\"\n      ],\n      \"pt\": [\n        \"Não empilhe vários no mesmo canto.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Wrapped in AppSemantics.liveRegion → announced when it appears. Title in onSurface and description in neutral s700 both pass AA; border and icon ≥ 3:1.\",\n      \"pt\": \"Embrulhado em AppSemantics.liveRegion → anunciado ao surgir. Título onSurface e descrição neutro s700 passam AA; borda/ícone ≥ 3:1.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_alert\",\n      \"app_snackbar\"\n    ]\n  },\n  {\n    \"id\": \"app_overlay_card\",\n    \"name\": \"AppOverlayCard\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Floating card that intercepts the pointer (for floating over maps).\",\n      \"pt\": \"Card flutuante que intercepta o ponteiro (para flutuar sobre mapas).\"\n    },\n    \"description\": {\n      \"en\": \"Like AppCard, but it wraps the content in a PointerInterceptor — it stops clicks from leaking to a platform view underneath (e.g. a map on the web). A surfaceContainer surface on the AppStyle (elevated by default) and AppRadiusMode axes; colors 100% from the theme.\",\n      \"pt\": \"Como o AppCard, mas embrulha o conteúdo num PointerInterceptor — bloqueia cliques de vazarem para uma platform view embaixo (ex.: mapa no web). Superfície surfaceContainer nos eixos AppStyle (default elevated) e AppRadiusMode; cores 100% do tema.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"A card or panel that floats over a map or a video (web) and must not leak clicks.\"\n      ],\n      \"pt\": [\n        \"Card/painel que flutua sobre um mapa ou vídeo (web) e não pode vazar clique.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"An ordinary card, with no platform view underneath → AppCard.\"\n      ],\n      \"pt\": [\n        \"Card comum, sem platform view embaixo → AppCard.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"child\",\n        \"type\": \"Widget\",\n        \"required\": true\n      },\n      {\n        \"name\": \"accentColor\",\n        \"type\": \"Color?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"padding\",\n        \"type\": \"EdgeInsetsGeometry?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppStyle?\",\n        \"required\": false,\n        \"default\": \"AppStyle.elevated\",\n        \"enumValues\": [\n          \"filled\",\n          \"outlined\",\n          \"elevated\"\n        ]\n      },\n      {\n        \"name\": \"radiusMode\",\n        \"type\": \"AppRadiusMode?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"default\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Panel over the map\",\n          \"pt\": \"Painel sobre o mapa\"\n        },\n        \"code\": \"AppOverlayCard(child: filterPanel)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use it over platform views (a map, a video) on the web.\"\n      ],\n      \"pt\": [\n        \"Use sobre platform views (mapa/vídeo) no web.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it when there is nothing to intercept (AppCard).\"\n      ],\n      \"pt\": [\n        \"Não use quando não há nada para interceptar (AppCard).\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"The theme's surface (surfaceContainer/outline) passes AA in light and dark. The interceptor does not alter the content's semantics.\",\n      \"pt\": \"Superfície do tema (surfaceContainer/outline) passa AA em claro/escuro. O interceptor não altera a semântica do conteúdo.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_card\",\n      \"app_overlay_alert\"\n    ]\n  },\n  {\n    \"id\": \"app_action_item\",\n    \"name\": \"AppActionItem\",\n    \"category\": \"molecule\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Action item (icon + text) on a clickable tinted surface.\",\n      \"pt\": \"Item de ação (ícone + texto) numa superfície tingida clicável.\"\n    },\n    \"description\": {\n      \"en\": \"Action row for menus and option lists: icon on the left + text. Tinted surface (primary.s50 by default), taking part in the AppStyle and AppRadiusMode axes. Colors 100% from the theme.\",\n      \"pt\": \"Linha de ação para menus/listas de opções: ícone à esquerda + texto. Superfície tingida (primary.s50 por padrão), participando dos eixos AppStyle e AppRadiusMode. Cores 100% do tema.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Quick actions in an option list or a menu.\"\n      ],\n      \"pt\": [\n        \"Ações rápidas numa lista de opções ou menu.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A rich list row (avatar, trailing, selection) → AppListTile.\"\n      ],\n      \"pt\": [\n        \"Linha de lista rica (avatar, trailing, seleção) → AppListTile.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"icon\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"text\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"onPressed\",\n        \"type\": \"VoidCallback\",\n        \"required\": true\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppStyle?\",\n        \"required\": false,\n        \"enumValues\": [\n          \"filled\",\n          \"outlined\",\n          \"elevated\"\n        ]\n      },\n      {\n        \"name\": \"radiusMode\",\n        \"type\": \"AppRadiusMode?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"default\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Support item\",\n          \"pt\": \"Item de suporte\"\n        },\n        \"code\": \"AppActionItem(icon: AppIconToken.support, text: 'Suporte', onPressed: openSupport)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Short text (1 line); an icon that reinforces the action.\"\n      ],\n      \"pt\": [\n        \"Texto curto (1 linha); ícone que reforça a ação.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it for complex list rows (AppListTile).\"\n      ],\n      \"pt\": [\n        \"Não use para linhas de lista complexas (AppListTile).\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Text with a semanticLabel; the icon in secondary and the text in neutralPrimary s900 over the tinted background both pass AA.\",\n      \"pt\": \"Texto com semanticLabel; ícone na cor secondary e texto neutralPrimary s900 sobre o fundo tingido passam AA.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_list_tile\",\n      \"app_menu\"\n    ]\n  },\n  {\n    \"id\": \"app_dialog\",\n    \"name\": \"AppDialog\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"The central card of a modal dialog (the floating surface).\",\n      \"pt\": \"Card central de um dialog modal (a superfície flutuante).\"\n    },\n    \"description\": {\n      \"en\": \"A dialog's surface: a top bar, scrollable content and an optional footer. Show it as a modal (barrier + transition + focus) through the `showAppDialog` helper. The bar is the same one the sheets use — an optional title and a close button (on and to the right by default) — but with the title aligned to the START, and it sits outside the scroll, like the footer; with no title and no button it does not exist. Because it floats, the container follows the AppStyle axis with its own `elevated` default (a shadow), overridable per instance; the shape follows the global radius axis. Colors 100% from the theme → AA contrast.\",\n      \"pt\": \"A superfície de um dialog: uma barra de topo, conteúdo rolável e um rodapé opcional. Exiba-o como modal (barrier + transição + foco) via o helper `showAppDialog`. A barra é a mesma das sheets — título opcional e botão de fechar (ligado e à direita por padrão) — mas com o título alinhado ao INÍCIO, e fica fora da rolagem, como o rodapé; sem título e sem botão ela não existe. Por ser flutuante, o container segue o eixo AppStyle com default próprio `elevated` (sombra), sobrescrevível por instância; a forma segue o eixo de raio global. Cores 100% do tema → contraste AA.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Confirming an action (delete, leave without saving) — blocking the flow.\",\n        \"Showing a notice or a result that requires acknowledgement before moving on.\"\n      ],\n      \"pt\": [\n        \"Confirmar uma ação (excluir, sair sem salvar) — bloqueando o fluxo.\",\n        \"Mostrar um aviso/resultado que exige reconhecimento antes de seguir.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Transient, non-blocking feedback → AppAlert through showAppOverlay.\",\n        \"A choice anchored to a trigger (a short list) → AppMenu/AppPopover.\",\n        \"A long form on mobile rising from the bottom → AppBottomSheet.\"\n      ],\n      \"pt\": [\n        \"Feedback transitório e não-bloqueante → AppAlert via showAppOverlay.\",\n        \"Escolha ancorada a um gatilho (lista curta) → AppMenu/AppPopover.\",\n        \"Formulário longo no mobile subindo de baixo → AppBottomSheet.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"child\",\n        \"type\": \"Widget\",\n        \"required\": true\n      },\n      {\n        \"name\": \"footer\",\n        \"type\": \"Widget?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Action footer (e.g. AppButtonsFooter).\",\n          \"pt\": \"Rodapé de ações (ex.: AppButtonsFooter).\"\n        }\n      },\n      {\n        \"name\": \"title\",\n        \"type\": \"Widget?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Title in the top bar, aligned to the start. `null` leaves the bar with only the close button.\",\n          \"pt\": \"Título na barra de topo, alinhado ao início. `null` deixa a barra só com o botão de fechar.\"\n        }\n      },\n      {\n        \"name\": \"showCloseButton\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\",\n        \"description\": {\n          \"en\": \"Circular close chip in the top bar. Turn it off in a `barrierDismissible: false` dialog only if the footer already offers a way out.\",\n          \"pt\": \"Chip circular de fechar na barra de topo. Desligue num dialog `barrierDismissible: false` só se o rodapé já oferecer uma saída.\"\n        }\n      },\n      {\n        \"name\": \"closeSide\",\n        \"type\": \"AppSheetCloseSide\",\n        \"required\": false,\n        \"default\": \"AppSheetCloseSide.end\",\n        \"description\": {\n          \"en\": \"Side of the close button. `end` = right in LTR.\",\n          \"pt\": \"Lado do botão de fechar. `end` = direita em LTR.\"\n        },\n        \"enumValues\": [\n          \"start\",\n          \"end\"\n        ]\n      },\n      {\n        \"name\": \"onCloseButton\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"The close button's action. `null` pops the route.\",\n          \"pt\": \"Ação do botão de fechar. `null` dá pop na rota.\"\n        }\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppStyle?\",\n        \"required\": false,\n        \"default\": \"AppStyle.elevated\",\n        \"enumValues\": [\n          \"filled\",\n          \"outlined\",\n          \"elevated\"\n        ]\n      },\n      {\n        \"name\": \"radiusMode\",\n        \"type\": \"AppRadiusMode?\",\n        \"required\": false,\n        \"enumValues\": [\n          \"reto\",\n          \"redondo\",\n          \"circular\",\n          \"padrao\"\n        ]\n      },\n      {\n        \"name\": \"radius\",\n        \"type\": \"BorderRadius?\",\n        \"required\": false\n      }\n    ],\n    \"variants\": [\n      \"filled\",\n      \"outlined\",\n      \"elevated\"\n    ],\n    \"states\": [\n      \"default\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Confirmation\",\n          \"pt\": \"Confirmação\"\n        },\n        \"code\": \"showAppDialog(context: context, title: const AppText('Excluir?'), child: const AppDialogContent(message: '...', illustration: 'assets/delete.svg'), footer: buttonsFooter)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use an AppButtonsFooter with a primary + a secondary action in the footer.\",\n        \"Keep the content short; the body scrolls if it exceeds the height.\",\n        \"Put the title in the bar's `title`, not in the body — in the body it scrolls away.\"\n      ],\n      \"pt\": [\n        \"Use um AppButtonsFooter com ação primária + secundária no rodapé.\",\n        \"Mantenha o conteúdo curto; o corpo rola se exceder a altura.\",\n        \"Ponha o título no `title` da barra, não no corpo — no corpo ele rola.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it for passing feedback (that is AppAlert/overlay).\",\n        \"Do not switch showCloseButton off in a barrierDismissible: false dialog without a way out in the footer — the user gets trapped.\"\n      ],\n      \"pt\": [\n        \"Não use para feedback passageiro (isso é AppAlert/overlay).\",\n        \"Não desligue o showCloseButton num dialog barrierDismissible: false sem uma saída no rodapé — o usuário fica preso.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Shown through the Navigator (a PopupRoute): the focus scope and returning focus to the trigger are managed by the route; the barrier is labelled \\\"Close\\\". The close button is the dialog's first focusable node and carries the same label; the bar's title is announced as a heading. The theme's colors (surfaceContainer/outline) pass AA in light and dark.\",\n      \"pt\": \"Exibido via Navigator (PopupRoute): escopo de foco e devolução de foco ao gatilho são geridos pela rota; o barrier tem rótulo \\\"Fechar\\\". O botão de fechar é o primeiro nó focável do dialog e tem o mesmo rótulo; o título da barra é anunciado como cabeçalho. Cores do tema (surfaceContainer/outline) passam AA em claro/escuro.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_dialog_content\",\n      \"app_bottom_sheet\",\n      \"app_alert\"\n    ]\n  },\n  {\n    \"id\": \"app_dialog_content\",\n    \"name\": \"AppDialogContent\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Standard dialog body: title, message and illustration.\",\n      \"pt\": \"Corpo padrão de um dialog: título, mensagem e ilustração.\"\n    },\n    \"description\": {\n      \"en\": \"The most common body of an AppDialog (confirm/notify): a prominent title (optional), a message and a central illustration. When the dialog already carries the title in its top bar, leave this `title` null so it is not repeated. The top breathing room shrinks on its own once the surface has drawn the bar. Colors from the theme; the illustration's accent color uses `secondary` when none is given.\",\n      \"pt\": \"O corpo mais comum de um AppDialog (confirmar/avisar): título em destaque (opcional), mensagem e uma ilustração central. Quando o dialog já leva o título na barra de topo, deixe o `title` daqui nulo para não repetir. O respiro do topo encolhe sozinho quando a superfície desenhou a barra. Cores do tema; a cor de destaque da ilustração usa `secondary` quando não informada.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Filling a confirmation/notice AppDialog with the standard layout.\"\n      ],\n      \"pt\": [\n        \"Preencher um AppDialog de confirmação/aviso com o layout padrão.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Custom content (a form, a list) → pass your own child.\"\n      ],\n      \"pt\": [\n        \"Conteúdo customizado (formulário, lista) → passe seu próprio child.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"title\",\n        \"type\": \"String?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Null when the title is already in the dialog's top bar.\",\n          \"pt\": \"Nulo quando o título já está na barra de topo do dialog.\"\n        }\n      },\n      {\n        \"name\": \"message\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"illustration\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"accentRole\",\n        \"type\": \"ColorSwatch<int>?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"The piece's color role — pass the SAME one as the action button (e.g. theme.colorTheme.danger). The illustration is tinted with that role's accent, the very value the button paints. Defaults to secondary.\",\n          \"pt\": \"Papel de cor da peça — passe o MESMO do botão de ação (ex.: theme.colorTheme.danger). A ilustração é tingida com o acento desse papel, o mesmo valor que o botão pinta. Default = secondary.\"\n        }\n      }\n    ],\n    \"states\": [\n      \"default\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Success\",\n          \"pt\": \"Sucesso\"\n        },\n        \"code\": \"AppDialogContent(title: 'Tudo certo!', message: 'Alterações salvas.', illustration: 'assets/success.svg')\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"A short title (1 line) and a to-the-point message.\"\n      ],\n      \"pt\": [\n        \"Título curto (1 linha) e mensagem objetiva.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not stack multiple illustrations.\"\n      ],\n      \"pt\": [\n        \"Não empilhe múltiplas ilustrações.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Title and message forward semanticLabel. Title in onSurface and message in neutral s700 pass AA against the dialog's surface.\",\n      \"pt\": \"Título e mensagem repassam semanticLabel. Título onSurface e mensagem neutro s700 passam AA sobre a superfície do dialog.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_dialog\"\n    ]\n  },\n  {\n    \"id\": \"app_shell\",\n    \"name\": \"AppShell\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Desktop workspace skeleton: rail, header, content in a card and a full-height side panel.\",\n      \"pt\": \"Esqueleto do workspace desktop: rail, header, conteúdo em cartão e painel lateral de altura total.\"\n    },\n    \"description\": {\n      \"en\": \"It places the shell's four areas. The [aside] takes the full height; the [header] runs from the left edge UP TO the aside (it is not full-width); the [rail] sits below the header; the [content] becomes a floating card with rounded corners on all four sides and a margin that lifts it off the bottom. The continuity between rail, header and aside comes from sharing one surface, with no dividers — the contrast is the card. It works the same in light and dark: the shell does not pin a mode. The rail's and the aside's widths belong to whoever passes them, which allows a draggable panel without the design system knowing anything about persistence.\",\n      \"pt\": \"Posiciona as quatro áreas do shell. O [aside] ocupa a altura total; o [header] vai da borda esquerda ATÉ o aside (não é full-width); o [rail] fica abaixo do header; o [content] vira um cartão flutuante com cantos arredondados nos quatro lados e margem que o afasta da base. A continuidade entre rail, header e aside vem de compartilharem a mesma superfície, sem divisórias — o contraste é o cartão. Funciona igual nos temas claro e escuro: o shell não fixa um modo. Larguras de rail e aside são de quem os passa, o que permite um painel arrastável sem o DS saber de persistência.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"A work app with side navigation and an always-present panel.\",\n        \"When the content should read as a card over the background.\"\n      ],\n      \"pt\": [\n        \"App de trabalho com navegação lateral e um painel sempre presente.\",\n        \"Quando o conteúdo deve ler como um cartão sobre o fundo.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A single screen with no persistent navigation → AppScaffold.\",\n        \"An authentication layout → AppAuthSplitLayout.\"\n      ],\n      \"pt\": [\n        \"Tela única sem navegação persistente → AppScaffold.\",\n        \"Layout de autenticação → AppAuthSplitLayout.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"content\",\n        \"type\": \"Widget\",\n        \"required\": true\n      },\n      {\n        \"name\": \"rail\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"header\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"aside\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"fullscreen\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\",\n        \"description\": {\n          \"en\": \"Hides rail/header/aside. The content does not move in the tree, so the screens' state survives.\",\n          \"pt\": \"Esconde rail/header/aside. O content não muda de lugar na árvore, então o estado das telas sobrevive.\"\n        }\n      },\n      {\n        \"name\": \"contentMargin\",\n        \"type\": \"EdgeInsets\",\n        \"required\": false,\n        \"default\": \"kAppShellContentMargin\"\n      },\n      {\n        \"name\": \"contentRadius\",\n        \"type\": \"BorderRadius?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"decoration\",\n        \"type\": \"BoxDecoration?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"normal\",\n      \"fullscreen\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Full shell\",\n          \"pt\": \"Shell completo\"\n        },\n        \"code\": \"AppShell(rail: AppNavigationRail(...), header: header, aside: AppAssistantPanel(...), content: workspace)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Let the rail and the aside define their own width.\",\n        \"Use fullscreen for maps, without remounting the content.\"\n      ],\n      \"pt\": [\n        \"Deixe rail e aside definirem a própria largura.\",\n        \"Use fullscreen para mapas, sem remontar o conteúdo.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not paint the header from outside: it already inherits the frame's surface.\",\n        \"Do not force a dark theme on the shell — the contrast is surface vs surfaceContainer, and it works in both modes.\"\n      ],\n      \"pt\": [\n        \"Não pinte o header por fora: ele já herda a superfície da moldura.\",\n        \"Não force um tema escuro no shell — o contraste é surface x surfaceContainer, e funciona nos dois modos.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Layout only: it introduces no semantics nodes of its own and captures no focus. Traversal order is header → rail → content → aside.\",\n      \"pt\": \"Só layout: não introduz nós de semântica próprios nem captura foco. A ordem de travessia segue header → rail → conteúdo → aside.\"\n    },\n    \"crossPlatform\": false,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_scaffold\",\n      \"app_navigation_rail\",\n      \"app_assistant_panel\",\n      \"app_workspace_tabs\"\n    ]\n  },\n  {\n    \"id\": \"app_omni_search\",\n    \"name\": \"AppOmniSearch\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Global search with async autocomplete, results grouped by entity and `/` commands.\",\n      \"pt\": \"Busca global com autocomplete assíncrono, resultados agrupados por entidade e comandos `/`.\"\n    },\n    \"description\": {\n      \"en\": \"One field, two sources. An ordinary term goes to onSearch (async, debounced, discarding out-of-order responses). A term starting with `/` does NOT: it resolves locally through AppCommandScope's AppCommandRegistry, which keeps commands instant and avoids sending \\\"/logout\\\" to the server. Results arrive grouped by entity — the block's label is what keeps a list mixing plate, IMEI and ICCID readable. The typed fragment is highlighted in the title. Keyboard: the arrows cross the groups, Enter picks, Esc closes; the panel never steals focus from the field.\",\n      \"pt\": \"Um campo, duas fontes. Termo comum vai para onSearch (assíncrono, com debounce e descarte de resposta fora de ordem). Termo iniciado por `/` NÃO vai: resolve local pelo AppCommandRegistry do AppCommandScope, o que mantém o comando instantâneo e evita mandar \\\"/sair\\\" ao servidor. Os resultados vêm agrupados por entidade — é o rótulo do bloco que faz uma lista misturando placa, IMEI e ICCID continuar legível. O trecho digitado é realçado no título. Teclado: setas atravessam os grupos, Enter escolhe, Esc fecha; o painel nunca rouba o foco do campo.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Search that crosses several entities from a single field.\",\n        \"A command palette combined with search.\"\n      ],\n      \"pt\": [\n        \"Busca que cruza várias entidades a partir de um campo só.\",\n        \"Paleta de comandos combinada com busca.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Selection from a known fixed list → AppSearchableDropdown.\",\n        \"Filtering a table → that toolbar's own field.\"\n      ],\n      \"pt\": [\n        \"Seleção de uma lista fixa conhecida → AppSearchableDropdown.\",\n        \"Filtro de uma tabela → o campo da própria toolbar.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"onSearch\",\n        \"type\": \"AppOmniSearchCallback\",\n        \"required\": true,\n        \"description\": {\n          \"en\": \"Receives the trimmed, non-empty term.\",\n          \"pt\": \"Recebe o termo aparado e não vazio.\"\n        }\n      },\n      {\n        \"name\": \"controller\",\n        \"type\": \"TextEditingController?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"focusNode\",\n        \"type\": \"FocusNode?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Pass your own to focus the field from outside (the `/` shortcut).\",\n          \"pt\": \"Passe o seu para focar o campo de fora (atalho `/`).\"\n        }\n      },\n      {\n        \"name\": \"hintText\",\n        \"type\": \"String\",\n        \"required\": false,\n        \"default\": \"'Buscar'\"\n      },\n      {\n        \"name\": \"helperText\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"shortcutHint\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"debounce\",\n        \"type\": \"Duration\",\n        \"required\": false,\n        \"default\": \"kAppOmniSearchDebounce\"\n      },\n      {\n        \"name\": \"panelMaxHeight\",\n        \"type\": \"double\",\n        \"required\": false,\n        \"default\": \"kAppOmniSearchPanelMaxHeight\"\n      },\n      {\n        \"name\": \"emptyLabel\",\n        \"type\": \"String\",\n        \"required\": false,\n        \"default\": \"'Nada encontrado'\"\n      }\n    ],\n    \"states\": [\n      \"idle\",\n      \"loading\",\n      \"results\",\n      \"commands\",\n      \"empty\",\n      \"error\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Fleet search\",\n          \"pt\": \"Busca de frota\"\n        },\n        \"code\": \"AppOmniSearch(helperText: 'Placa, chassi, CPF, CNPJ, IMEI…', onSearch: (term) => searchCubit.search(term))\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Group by entity and name each block.\",\n        \"Return AppOmniSearchResult.failed on error — it is different from empty.\"\n      ],\n      \"pt\": [\n        \"Agrupe por entidade e nomeie cada bloco.\",\n        \"Devolva AppOmniSearchResult.failed em erro — é diferente de vazio.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not send command terms to the server.\",\n        \"Do not let the panel steal focus: typing would stop.\"\n      ],\n      \"pt\": [\n        \"Não mande termos de comando ao servidor.\",\n        \"Não deixe o painel roubar o foco: a digitação pararia.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Each row exposes Semantics(button:true) with a title and a subtitle; the keyboard highlight uses the same color as hover, so mouse focus and arrow focus do not look like different states.\",\n      \"pt\": \"Cada linha expõe Semantics(button:true) com título e subtítulo; o realce por teclado usa a mesma cor do hover, para foco de mouse e de seta não parecerem estados diferentes.\"\n    },\n    \"crossPlatform\": false,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_searchable_dropdown\",\n      \"app_shell\"\n    ]\n  },\n  {\n    \"id\": \"app_assistant_panel\",\n    \"name\": \"AppAssistantPanel\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Assistant side panel, always present: header, fixed banner, conversation and composer.\",\n      \"pt\": \"Painel lateral do assistente, sempre presente: cabeçalho, faixa fixa, conversa e composer.\"\n    },\n    \"description\": {\n      \"en\": \"A full-height column beside the content, not an overlay. An assistant that covers the screen forces a choice between seeing the data and asking about it; here you can talk while looking at the screen that prompted the question. The alertBanner is FIXED between the header and the conversation: it is what upholds \\\"alerts visible at all times\\\", since a card inside the flow leaves the viewport as soon as the conversation scrolls. The shortcut badge in the header exists so the shortcut gets discovered. The width belongs to the caller — the panel fills whatever it is given.\",\n      \"pt\": \"Coluna de altura total ao lado do conteúdo, não um overlay. Um assistente que cobre a tela obriga a escolher entre ver o dado e perguntar sobre ele; aqui dá para conversar olhando a tela que motivou a pergunta. O alertBanner é FIXO entre cabeçalho e conversa: é o que sustenta \\\"alertas visíveis a todo tempo\\\", já que um cartão dentro do fluxo sai de vista assim que a conversa rola. O selo de atalho no cabeçalho existe para o atalho ser descoberto. A largura é de quem usa — o painel preenche o que receber.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"An assistant that has to coexist with the content, not cover it.\",\n        \"A side panel with a header, a scrollable body and a fixed composer.\"\n      ],\n      \"pt\": [\n        \"Assistente que precisa conviver com o conteúdo, não cobri-lo.\",\n        \"Painel lateral com cabeçalho, corpo rolável e composer fixo.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A full-screen conversation (kiosk mode) → the chat screen directly.\",\n        \"An ephemeral panel triggered by a button → AppSideSheet.\"\n      ],\n      \"pt\": [\n        \"Conversa em tela cheia (modo quiosque) → a tela de chat direto.\",\n        \"Painel efêmero acionado por um botão → AppSideSheet.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"body\",\n        \"type\": \"Widget\",\n        \"required\": true\n      },\n      {\n        \"name\": \"title\",\n        \"type\": \"String\",\n        \"required\": false,\n        \"default\": \"'Assistente'\"\n      },\n      {\n        \"name\": \"statusLabel\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"isOnline\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"avatar\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"alertBanner\",\n        \"type\": \"Widget?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"FIXED banner between the header and the conversation.\",\n          \"pt\": \"Faixa FIXA entre cabeçalho e conversa.\"\n        }\n      },\n      {\n        \"name\": \"composer\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"actions\",\n        \"type\": \"List<Widget>\",\n        \"required\": false,\n        \"default\": \"const []\"\n      },\n      {\n        \"name\": \"decoration\",\n        \"type\": \"BoxDecoration?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"online\",\n      \"offline\",\n      \"with-banner\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Assistant in the shell\",\n          \"pt\": \"Assistente no shell\"\n        },\n        \"code\": \"AppAssistantPanel(title: 'Atlas', statusLabel: 'Sempre online', alertBanner: alertsStrip, body: AppChatMessageList(...), composer: AppChatComposer(...))\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Keep the panel mounted — the history lives in it.\",\n        \"Use the alertBanner for whatever has to survive the scroll.\"\n      ],\n      \"pt\": [\n        \"Mantenha o painel montado — o histórico vive nele.\",\n        \"Use o alertBanner para o que precisa sobreviver ao scroll.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not turn it into an overlay: that removes the context that prompted the question.\",\n        \"Do not pin a width here — whoever assembles the shell decides.\"\n      ],\n      \"pt\": [\n        \"Não transforme em overlay: some o contexto que motivou a pergunta.\",\n        \"Não fixe largura aqui — quem monta o shell decide.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"The header is legible text (name + status), not color alone: the status dot accompanies the label instead of replacing it.\",\n      \"pt\": \"Cabeçalho é texto legível (nome + status), não só cor: o ponto de status acompanha o rótulo em vez de substituí-lo.\"\n    },\n    \"crossPlatform\": false,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_shell\",\n      \"app_chat_message_list\",\n      \"app_chat_composer\"\n    ]\n  },\n  {\n    \"id\": \"app_scaffold\",\n    \"name\": \"AppScaffold\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Page layout: header · content · footer over the surface.\",\n      \"pt\": \"Layout de página: header · conteúdo · footer sobre a surface.\"\n    },\n    \"description\": {\n      \"en\": \"A layout organism (structural): it places an optional header at the top, the content in the middle (expanded) and an optional footer at the bottom, over the theme's `surface` color, with an optional SafeArea. It takes no part in the style/radius axes (it is structure, not surface).\",\n      \"pt\": \"Organismo de layout (estrutural): posiciona um cabeçalho opcional no topo, o conteúdo no meio (expandido) e um rodapé opcional na base, sobre a cor `surface` do tema, com SafeArea opcional. Não participa dos eixos de estilo/raio (é estrutura, não superfície).\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"The base of a page or screen with a fixed header and/or footer.\",\n        \"The body of an AppBottomSheet (scrollable content + an action footer).\"\n      ],\n      \"pt\": [\n        \"Base de uma página/tela com header e/ou footer fixos.\",\n        \"Corpo de um AppBottomSheet (conteúdo rolável + rodapé de ações).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A surface with a fill, a border or a shadow (a floating card) → AppCard/AppDialog.\"\n      ],\n      \"pt\": [\n        \"Superfície com fill/borda/sombra (card flutuante) → AppCard/AppDialog.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"child\",\n        \"type\": \"Widget\",\n        \"required\": true\n      },\n      {\n        \"name\": \"fadeFooter\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      },\n      {\n        \"name\": \"fadeHeader\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      },\n      {\n        \"name\": \"floatingAction\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"floatingActionAlignment\",\n        \"type\": \"AlignmentGeometry\",\n        \"required\": false,\n        \"default\": \"AlignmentDirectional.bottomEnd\"\n      },\n      {\n        \"name\": \"footer\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"header\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"safeAreaOnBottom\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      },\n      {\n        \"name\": \"safeAreaOnTop\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      }\n    ],\n    \"states\": [\n      \"default\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Page with a header and a footer\",\n          \"pt\": \"Página com header e footer\"\n        },\n        \"code\": \"AppScaffold(header: const AppSimpleHeader(child: AppText('Veículos')), footer: buttonsFooter, child: content)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use AppSimpleHeader/AppPrimaryHeader in the header.\"\n      ],\n      \"pt\": [\n        \"Use AppSimpleHeader/AppPrimaryHeader no header.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not nest AppScaffolds just to stack sections.\"\n      ],\n      \"pt\": [\n        \"Não aninhe AppScaffolds só para empilhar seções.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Structural: it injects no semantics of its own; the regions (header/footer/content) bring theirs. A `surface` background with `onSurface` text passes AA.\",\n      \"pt\": \"Estrutural: não injeta semântica própria; as regiões (header/footer/conteúdo) trazem a sua. Fundo `surface`/texto `onSurface` passam AA.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_bottom_sheet\",\n      \"app_simple_header\",\n      \"app_buttons_footer\",\n      \"app_floating_button\"\n    ]\n  },\n  {\n    \"id\": \"app_auth_split_layout\",\n    \"name\": \"AppAuthSplitLayout\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Split layout for the authentication pages (login/OTP).\",\n      \"pt\": \"Layout dividido das páginas de autenticação (login/OTP).\"\n    },\n    \"description\": {\n      \"en\": \"On desktop: a brand panel (clickable logo, title/subtitle + the form) on the left and a background image on the right. On mobile: a centered card over the background image. It breaks at AppDevice's breakpoints. Colors from the theme; the mobile card's corners from the radius axis; the logo has a touch micro-interaction (it opens the brand's site).\",\n      \"pt\": \"No desktop: painel de marca (logo clicável, título/subtítulo + o formulário) à esquerda e imagem de fundo à direita. No mobile: card centralizado sobre a imagem de fundo. Quebra pelos breakpoints de AppDevice. Cores do tema; cantos do card mobile pelo eixo de raio; logo com micro-interação de toque (abre o site da marca).\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Authentication screens (login, OTP, recovery) in the apps.\"\n      ],\n      \"pt\": [\n        \"Telas de autenticação (login, OTP, recuperação) nos apps.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"An ordinary inner page → AppScaffold.\"\n      ],\n      \"pt\": [\n        \"Página interna comum → AppScaffold.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"brandTitle\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"brandSubtitle\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"child\",\n        \"type\": \"Widget\",\n        \"required\": true\n      },\n      {\n        \"name\": \"backgroundImageUrl\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"logoUrl\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"websiteUrl\",\n        \"type\": \"String?\",\n        \"required\": false\n      }\n    ],\n    \"variants\": [\n      \"desktop\",\n      \"mobile\"\n    ],\n    \"states\": [\n      \"default\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Login screen\",\n          \"pt\": \"Tela de login\"\n        },\n        \"code\": \"AppAuthSplitLayout(brandTitle: 'Bem-vindo', brandSubtitle: 'Acesse sua conta', logoUrl: logo, child: loginForm)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Pass the auth form in child.\"\n      ],\n      \"pt\": [\n        \"Passe o formulário de auth em child.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it on inner screens (that is AppScaffold).\"\n      ],\n      \"pt\": [\n        \"Não use em telas internas (isso é AppScaffold).\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"The background image is decorative (excluded from the semantics); the logo is clickable and labelled. Title and subtitle derive a legible stop over the panel (`surfaceContainer`) through `readableStopOn`, passing AA in both themes.\",\n      \"pt\": \"Imagem de fundo é decorativa (excluída da semântica); logo é clicável com rótulo. Título e subtítulo derivam o stop legível sobre o painel (`surfaceContainer`) por `readableStopOn`, passando AA nos dois temas.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_scaffold\"\n    ]\n  },\n  {\n    \"id\": \"app_bottom_sheet\",\n    \"name\": \"AppBottomSheet\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Floating panel anchored to the bottom (bottom sheet), optionally draggable.\",\n      \"pt\": \"Painel flutuante ancorado na base (bottom sheet), opcionalmente arrastável.\"\n    },\n    \"description\": {\n      \"en\": \"A detached card that rises from the bottom (margins on L/R/bottom, rounded corners) until the content fits (a `maxHeightFraction` ceiling, with internal scrolling above that). Show it as a modal through `showAppBottomSheet` (barrier + slide-up); with `draggable: true` it gains two states (rest ⇄ edge-to-edge page) with a fluid morph, an optional handle and swipe-to-dismiss. A top bar with an optional title and a close button (a circular chip, side chosen by `closeSide`). The container follows the AppStyle axis (its own `elevated` default, not the global one); the corners follow the radius axis. Colors 100% from the theme. `useRootNavigator` resolves the root navigator.\",\n      \"pt\": \"Um card destacado que sobe pela base (margem em L/R/base, cantos arredondados) até o conteúdo caber (teto `maxHeightFraction`, com scroll interno acima disso). Exiba como modal via `showAppBottomSheet` (barrier + slide-up); com `draggable: true` ganha dois estados (repouso ⇄ page edge-to-edge) com morph fluido, handle opcional e swipe-to-dismiss. Barra de topo com título opcional e botão de fechar (chip circular, lado via `closeSide`). Container segue o eixo AppStyle (default próprio `elevated`, não segue o global); os cantos seguem o eixo de raio. Cores 100% do tema. `useRootNavigator` resolve o navigator raiz.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"A form or detail that rises from the bottom on mobile (filters, actions).\",\n        \"A long list or form that benefits from being dragged up into a page.\"\n      ],\n      \"pt\": [\n        \"Formulário/detalhe que sobe de baixo no mobile (filtros, ações).\",\n        \"Lista/formulário longo que se beneficia de arrastar até virar page.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A blocking central confirmation on desktop → AppDialog.\",\n        \"A short menu anchored to a trigger → AppMenu.\",\n        \"A full iOS-style page (with a peek at the top) → AppBottomSheetPage.\"\n      ],\n      \"pt\": [\n        \"Confirmação central bloqueante no desktop → AppDialog.\",\n        \"Menu curto ancorado a um gatilho → AppMenu.\",\n        \"Página cheia estilo iOS (peek no topo) → AppBottomSheetPage.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"child\",\n        \"type\": \"Widget\",\n        \"required\": true\n      },\n      {\n        \"name\": \"footer\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"title\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"draggable\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      },\n      {\n        \"name\": \"alwaysClose\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      },\n      {\n        \"name\": \"showHandle\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      },\n      {\n        \"name\": \"showCloseButton\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"onCloseButton\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onClose\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"closeSide\",\n        \"type\": \"AppSheetCloseSide\",\n        \"required\": false,\n        \"default\": \"AppSheetCloseSide.end\",\n        \"enumValues\": [\n          \"start\",\n          \"end\"\n        ]\n      },\n      {\n        \"name\": \"maxHeightFraction\",\n        \"type\": \"double\",\n        \"required\": false,\n        \"default\": \"0.65\"\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppStyle?\",\n        \"required\": false,\n        \"default\": \"AppStyle.elevated\",\n        \"enumValues\": [\n          \"filled\",\n          \"outlined\",\n          \"elevated\"\n        ]\n      },\n      {\n        \"name\": \"radiusMode\",\n        \"type\": \"AppRadiusMode?\",\n        \"required\": false,\n        \"enumValues\": [\n          \"reto\",\n          \"redondo\",\n          \"circular\",\n          \"padrao\"\n        ]\n      }\n    ],\n    \"variants\": [\n      \"filled\",\n      \"outlined\",\n      \"elevated\"\n    ],\n    \"states\": [\n      \"rest\",\n      \"page\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Draggable filters on mobile\",\n          \"pt\": \"Filtros arrastáveis no mobile\"\n        },\n        \"code\": \"showAppBottomSheet<void>(context: context, draggable: true, showHandle: true, title: Text(\\\"Filtros\\\"), footer: buttonsFooter, useRootNavigator: true, child: filtersForm)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use a fixed AppButtonsFooter for the actions.\",\n        \"Pass useRootNavigator: true to cover the bottom navigation.\",\n        \"Use draggable + showHandle for long content (rest ⇄ page).\"\n      ],\n      \"pt\": [\n        \"Use um AppButtonsFooter fixo para as ações.\",\n        \"Passe useRootNavigator: true para cobrir a bottom navigation.\",\n        \"Use draggable + showHandle para conteúdo longo (repouso ⇄ page).\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it on desktop for confirmation (that is AppDialog).\"\n      ],\n      \"pt\": [\n        \"Não use no desktop para confirmação (isso é AppDialog).\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Shown through the Navigator (a PopupRoute): focus and its return are managed by the route; the barrier and the close button are labelled \\\"Close\\\". The theme's colors pass AA.\",\n      \"pt\": \"Exibido via Navigator (PopupRoute): foco e devolução geridos pela rota; barrier e botão de fechar com rótulo \\\"Fechar\\\". Cores do tema passam AA.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_bottom_sheet_page\",\n      \"app_bottom_sheet_content\",\n      \"app_dialog\",\n      \"app_scaffold\"\n    ]\n  },\n  {\n    \"id\": \"app_bottom_sheet_page\",\n    \"name\": \"AppBottomSheetPage\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"iOS-style modal page that rises to the top (peek), edge-to-edge.\",\n      \"pt\": \"Página modal estilo iOS que sobe até o topo (peek), edge-to-edge.\"\n    },\n    \"description\": {\n      \"en\": \"A page that rises to just below the top safe area, leaving a gap (peek) that shows the screen underneath behind the top corners. It is edge-to-edge on L/R/bottom; it closes from the close button, from the barrier or with a downward swipe. Show it through `showAppBottomSheetPage`. A top bar with an optional title and a close button (side chosen by `closeSide`). The container follows the AppStyle axis (its own `elevated` default); the top corners follow the radius axis. Colors 100% from the theme.\",\n      \"pt\": \"Página que sobe até logo abaixo do safe-area do topo, deixando um respiro (peek) que mostra a tela de baixo por trás dos cantos de cima. É edge-to-edge em L/R/base; fecha pelo botão de fechar, pelo barrier ou por swipe para baixo. Exiba via `showAppBottomSheetPage`. Barra de topo com título opcional e botão de fechar (lado via `closeSide`). Container segue o eixo AppStyle (default próprio `elevated`); cantos de cima pelo eixo de raio. Cores 100% do tema.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"A contextual full screen on mobile (settings, a detail, a long form).\",\n        \"A flow that needs almost the whole screen while keeping the context underneath (the peek).\"\n      ],\n      \"pt\": [\n        \"Tela cheia contextual no mobile (configurações, detalhe, formulário longo).\",\n        \"Fluxo que precisa quase toda a tela mantendo o contexto de baixo (peek).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A short or medium panel that rises to fit its content → AppBottomSheet.\",\n        \"A central confirmation on desktop → AppDialog.\"\n      ],\n      \"pt\": [\n        \"Painel curto/médio que sobe até o conteúdo → AppBottomSheet.\",\n        \"Confirmação central no desktop → AppDialog.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"child\",\n        \"type\": \"Widget\",\n        \"required\": true\n      },\n      {\n        \"name\": \"title\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"footer\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"showCloseButton\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"onCloseButton\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"closeSide\",\n        \"type\": \"AppSheetCloseSide\",\n        \"required\": false,\n        \"default\": \"AppSheetCloseSide.end\",\n        \"enumValues\": [\n          \"start\",\n          \"end\"\n        ]\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppStyle?\",\n        \"required\": false,\n        \"default\": \"AppStyle.elevated\",\n        \"enumValues\": [\n          \"filled\",\n          \"outlined\",\n          \"elevated\"\n        ]\n      },\n      {\n        \"name\": \"radiusMode\",\n        \"type\": \"AppRadiusMode?\",\n        \"required\": false,\n        \"enumValues\": [\n          \"reto\",\n          \"redondo\",\n          \"circular\",\n          \"padrao\"\n        ]\n      }\n    ],\n    \"variants\": [\n      \"filled\",\n      \"outlined\",\n      \"elevated\"\n    ],\n    \"states\": [\n      \"default\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Full-screen settings\",\n          \"pt\": \"Configurações em tela cheia\"\n        },\n        \"code\": \"showAppBottomSheetPage<void>(context: context, title: Text(\\\"Ajustes\\\"), useRootNavigator: true, child: settingsBody)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use it for content that needs almost the whole screen.\",\n        \"Pass useRootNavigator: true to cover the bottom navigation.\"\n      ],\n      \"pt\": [\n        \"Use para conteúdo que precisa de quase toda a tela.\",\n        \"Passe useRootNavigator: true para cobrir a bottom navigation.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it for short panels (that is AppBottomSheet).\"\n      ],\n      \"pt\": [\n        \"Não use para painéis curtos (isso é AppBottomSheet).\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Shown through the Navigator (a PopupRoute): focus and its return are managed by the route; the barrier and the close button are labelled \\\"Close\\\". The theme's colors pass AA.\",\n      \"pt\": \"Exibido via Navigator (PopupRoute): foco e devolução geridos pela rota; barrier e botão de fechar com rótulo \\\"Fechar\\\". Cores do tema passam AA.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_bottom_sheet\",\n      \"app_dialog\",\n      \"app_scaffold\"\n    ]\n  },\n  {\n    \"id\": \"app_bottom_sheet_content\",\n    \"name\": \"AppBottomSheetContent\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Standard bottom sheet body: title, message and illustration.\",\n      \"pt\": \"Corpo padrão de um bottom sheet: título, mensagem e ilustração.\"\n    },\n    \"description\": {\n      \"en\": \"The most common body of an AppBottomSheet (a notice or a detail), scrollable: title, message and illustration. Colors from the theme; the illustration's accent uses `secondary` when none is given.\",\n      \"pt\": \"O corpo mais comum de um AppBottomSheet (aviso/detalhe), rolável: título, mensagem e ilustração. Cores do tema; o destaque da ilustração usa `secondary` quando não informado.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Filling an AppBottomSheet with the standard notice/detail layout.\"\n      ],\n      \"pt\": [\n        \"Preencher um AppBottomSheet com o layout padrão de aviso/detalhe.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Custom content (a form, a list) → pass your own child.\"\n      ],\n      \"pt\": [\n        \"Conteúdo customizado (formulário/lista) → passe seu próprio child.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"title\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"message\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"illustration\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"accentRole\",\n        \"type\": \"ColorSwatch<int>?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"The piece's color role — pass the SAME one as the action button (e.g. theme.colorTheme.danger). The illustration is tinted with that role's accent, the very value the button paints. Defaults to secondary.\",\n          \"pt\": \"Papel de cor da peça — passe o MESMO do botão de ação (ex.: theme.colorTheme.danger). A ilustração é tingida com o acento desse papel, o mesmo valor que o botão pinta. Default = secondary.\"\n        }\n      }\n    ],\n    \"states\": [\n      \"default\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Notice\",\n          \"pt\": \"Aviso\"\n        },\n        \"code\": \"AppBottomSheetContent(title: 'Atenção', message: '...', illustration: 'assets/warning.svg')\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"A short title and a to-the-point message.\"\n      ],\n      \"pt\": [\n        \"Título curto e mensagem objetiva.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not stack multiple illustrations.\"\n      ],\n      \"pt\": [\n        \"Não empilhe múltiplas ilustrações.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Title and message forward semanticLabel; title in onSurface and message in neutral s700 pass AA against the surface.\",\n      \"pt\": \"Título e mensagem repassam semanticLabel; título onSurface e mensagem neutro s700 passam AA sobre a superfície.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_bottom_sheet\"\n    ]\n  },\n  {\n    \"id\": \"app_side_sheet\",\n    \"name\": \"AppSideSheet\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Floating side panel (the bottom sheet's horizontal sibling), responsive.\",\n      \"pt\": \"Painel lateral flutuante (irmão horizontal do bottom sheet), responsivo.\"\n    },\n    \"description\": {\n      \"en\": \"A detached card that slides in from the `side` edge (start/end, end = right by default) and grows toward the center. Show it through `showAppSideSheet`; with `draggable: true` it resizes by dragging the inner edge with responsive snaps (screens > 1024: 40% → 70% → full; <= 1024: 70% → full) and morphs to edge-to-edge at full (leaving a peek on the opposite edge). A top bar with an optional title and a close button (a chip; by default in the inner corner, through `closeSide`). `alwaysClose` closes it when shrinking from full. It follows the AppStyle (its own `elevated` default), radius and motion axes; colors 100% from the theme.\",\n      \"pt\": \"Um card destacado que desliza da borda `side` (start/end, default end = direita) e cresce em direção ao centro. Exiba via `showAppSideSheet`; com `draggable: true` redimensiona por arraste da borda interna com snaps responsivos (telas > 1024: 40% → 70% → full; <= 1024: 70% → full) e morph para edge-to-edge no full (deixando um peek na borda oposta). Barra de topo com título opcional e botão de fechar (chip; default no canto interno via `closeSide`). `alwaysClose` fecha ao encolher da full. Segue os eixos AppStyle (default próprio `elevated`) / raio / motion; cores 100% do tema.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"A detail or an edit beside the main content (desktop/tablet: a map + a panel).\",\n        \"A contextual form or list that benefits from resizing (40/70/full).\"\n      ],\n      \"pt\": [\n        \"Detalhe/edição ao lado do conteúdo principal (desktop/tablet: mapa + painel).\",\n        \"Formulário ou lista contextual que se beneficia de redimensionar (40/70/full).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A panel that rises from the bottom on mobile → AppBottomSheet.\",\n        \"A blocking central confirmation → AppDialog.\"\n      ],\n      \"pt\": [\n        \"Painel que sobe da base no mobile → AppBottomSheet.\",\n        \"Confirmação central bloqueante → AppDialog.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"child\",\n        \"type\": \"Widget\",\n        \"required\": true\n      },\n      {\n        \"name\": \"side\",\n        \"type\": \"AppSheetSide\",\n        \"required\": false,\n        \"default\": \"AppSheetSide.end\",\n        \"enumValues\": [\n          \"start\",\n          \"end\"\n        ]\n      },\n      {\n        \"name\": \"title\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"footer\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"draggable\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      },\n      {\n        \"name\": \"alwaysClose\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      },\n      {\n        \"name\": \"showHandle\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      },\n      {\n        \"name\": \"showCloseButton\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"onCloseButton\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onClose\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"closeSide\",\n        \"type\": \"AppSheetCloseSide?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"null → the inner corner, according to side.\",\n          \"pt\": \"null → canto interno conforme side.\"\n        },\n        \"enumValues\": [\n          \"start\",\n          \"end\"\n        ]\n      },\n      {\n        \"name\": \"mediumFraction\",\n        \"type\": \"double\",\n        \"required\": false,\n        \"default\": \"0.40\"\n      },\n      {\n        \"name\": \"largeFraction\",\n        \"type\": \"double\",\n        \"required\": false,\n        \"default\": \"0.70\"\n      },\n      {\n        \"name\": \"initialSnap\",\n        \"type\": \"AppSideSheetSnap\",\n        \"required\": false,\n        \"default\": \"AppSideSheetSnap.rest\",\n        \"description\": {\n          \"en\": \"The snap the sheet opens at. `full` for content that needs the whole width (two columns, wide tables).\",\n          \"pt\": \"Snap em que a sheet abre. `full` para conteúdo que precisa da largura toda (duas colunas, tabelas largas).\"\n        },\n        \"enumValues\": [\n          \"rest\",\n          \"full\"\n        ]\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppStyle?\",\n        \"required\": false,\n        \"default\": \"AppStyle.elevated\",\n        \"enumValues\": [\n          \"filled\",\n          \"outlined\",\n          \"elevated\"\n        ]\n      },\n      {\n        \"name\": \"radiusMode\",\n        \"type\": \"AppRadiusMode?\",\n        \"required\": false,\n        \"enumValues\": [\n          \"reto\",\n          \"redondo\",\n          \"circular\",\n          \"padrao\"\n        ]\n      }\n    ],\n    \"variants\": [\n      \"filled\",\n      \"outlined\",\n      \"elevated\"\n    ],\n    \"states\": [\n      \"rest\",\n      \"full\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Draggable detail on the right\",\n          \"pt\": \"Detalhe arrastável à direita\"\n        },\n        \"code\": \"showAppSideSheet<void>(\\n  context: context,\\n  draggable: true,\\n  showHandle: true,\\n  title: 'Veículo',\\n  child: details,\\n)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use draggable + showHandle to resize it (40/70/full).\",\n        \"Use side to choose the edge (start/end).\"\n      ],\n      \"pt\": [\n        \"Use draggable + showHandle para redimensionar (40/70/full).\",\n        \"Use side para escolher a borda (start/end).\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it on mobile for a panel that rises (that is AppBottomSheet).\"\n      ],\n      \"pt\": [\n        \"Não use no mobile para painel que sobe (isso é AppBottomSheet).\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Shown through the Navigator (a PopupRoute): focus and its return are managed by the route; the barrier and the close button are labelled \\\"Close\\\". The theme's colors pass AA.\",\n      \"pt\": \"Exibido via Navigator (PopupRoute): foco e devolução geridos pela rota; barrier e botão de fechar com rótulo \\\"Fechar\\\". Cores do tema passam AA.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_bottom_sheet\",\n      \"app_dialog\",\n      \"app_resizable_split\"\n    ]\n  },\n  {\n    \"id\": \"app_side_sheet_page\",\n    \"name\": \"AppSideSheetPage\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"The same surface as AppSideSheet, shown by a PERSISTENT route (SideSheetPageRoute) instead of an ephemeral one.\",\n      \"pt\": \"A mesma superfície do AppSideSheet, exibida por uma rota PERSISTENTE (SideSheetPageRoute) em vez de uma efêmera.\"\n    },\n    \"description\": {\n      \"en\": \"Visually it is IDENTICAL to AppSideSheet — same surface, same snaps (40/70/full), same chrome, same engine. What changes is the route's class. That matters when the panel is a first-class \\\"page\\\": heavy, with state of its own, that has to survive and still be able to host an ephemeral sheet ON TOP (the Vehicle Record is the case that motivated it). An ephemeral route does not stack that way: the second sheet would close the first. Choose by the nature of the content, not by the look.\",\n      \"pt\": \"Visualmente é IDÊNTICO ao AppSideSheet — mesma superfície, mesmos snaps (40/70/full), mesmo chrome, mesmo motor. O que muda é a classe da rota. Isso importa quando o painel é uma \\\"página\\\" de primeira classe: pesada, com estado próprio, que precisa sobreviver e ainda poder hospedar um sheet efêmero POR CIMA (a Ficha do Veículo é o caso que motivou). Uma rota efêmera não empilha assim: o segundo sheet fecharia o primeiro. Escolha pela natureza do conteúdo, não pela aparência.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"A destination panel with state of its own, opened by URL or route.\",\n        \"A panel that has to host another sheet on top without closing.\"\n      ],\n      \"pt\": [\n        \"Painel-destino com estado próprio, aberto por URL/rota.\",\n        \"Painel que precisa hospedar outro sheet por cima sem se fechar.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"An aside that closes right away → AppSideSheet (an ephemeral route).\",\n        \"A panel that rises from the bottom on mobile → AppBottomSheetPage.\"\n      ],\n      \"pt\": [\n        \"Aparte que se fecha logo → AppSideSheet (rota efêmera).\",\n        \"Painel que sobe da base no mobile → AppBottomSheetPage.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"child\",\n        \"type\": \"Widget\",\n        \"required\": true\n      },\n      {\n        \"name\": \"side\",\n        \"type\": \"AppSheetSide\",\n        \"required\": false,\n        \"default\": \"AppSheetSide.end\",\n        \"enumValues\": [\n          \"start\",\n          \"end\"\n        ]\n      },\n      {\n        \"name\": \"title\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"titleWidget\",\n        \"type\": \"Widget?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Escape hatch for a title that does not fit in a String.\",\n          \"pt\": \"Escape hatch para o título que não cabe numa String.\"\n        }\n      },\n      {\n        \"name\": \"footer\",\n        \"type\": \"Widget?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"showHandle\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      },\n      {\n        \"name\": \"showCloseButton\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"closeSide\",\n        \"type\": \"AppSheetCloseSide?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"null resolves to the INNER corner.\",\n          \"pt\": \"null resolve para o canto INTERNO.\"\n        },\n        \"enumValues\": [\n          \"start\",\n          \"end\"\n        ]\n      },\n      {\n        \"name\": \"onCloseButton\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppStyle?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"glass\",\n        \"type\": \"bool?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"radiusMode\",\n        \"type\": \"AppRadiusMode?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"rest\",\n      \"resizing\",\n      \"with-ephemeral-sheet-above\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Record opened as a page\",\n          \"pt\": \"Ficha aberta como página\"\n        },\n        \"code\": \"showAppSideSheetPage<void>(\\n  context: context,\\n  title: 'Ficha do veículo',\\n  draggable: true,\\n  child: VehicleProfile(id: id),\\n)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use it when the panel has to survive another sheet opening on top of it.\"\n      ],\n      \"pt\": [\n        \"Use quando o painel precisa sobreviver a outro sheet aberto por cima.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not choose by appearance: it is the same as AppSideSheet's.\"\n      ],\n      \"pt\": [\n        \"Não escolha pela aparência: ela é a mesma do AppSideSheet.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"A persistent route: focus and its return are managed by the Navigator, and the panel stays in the tree when an ephemeral sheet opens over it — the screen reader returns to where it was when that sheet closes. The close button is labelled \\\"Close\\\".\",\n      \"pt\": \"Rota persistente: foco e devolução são geridos pelo Navigator, e o painel continua na árvore quando um sheet efêmero abre por cima — o leitor de tela volta para onde estava ao fechá-lo. Botão de fechar rotulado \\\"Fechar\\\".\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_side_sheet\",\n      \"app_bottom_sheet_page\"\n    ]\n  },\n  {\n    \"id\": \"app_api_method_badge\",\n    \"name\": \"AppApiMethodBadge\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"HTTP verb pill, tinted by the method's semantic role.\",\n      \"pt\": \"Pílula do verbo HTTP, tingida pelo papel semântico do método.\"\n    },\n    \"description\": {\n      \"en\": \"A thin shell over AppBadge: uppercase, a color role per verb (GET info, POST success, PUT/PATCH warning, DELETE danger) and, by default, a fixed-width column so the paths in a list all start at the same abscissa.\",\n      \"pt\": \"Casca fina sobre o AppBadge: caixa alta, papel de cor por verbo (GET info, POST success, PUT/PATCH warning, DELETE danger) e, por padrão, uma coluna de largura fixa para os paths de uma lista começarem na mesma abscissa.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"The header of an endpoint in a documentation list.\",\n        \"A reference to a call inside a flow step.\"\n      ],\n      \"pt\": [\n        \"Cabeçalho de um endpoint numa lista de documentação.\",\n        \"Referência a uma chamada dentro de um passo de fluxo.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A response status (2xx/4xx) → AppBadge with the appropriate role.\"\n      ],\n      \"pt\": [\n        \"Status de uma resposta (2xx/4xx) → AppBadge com o papel adequado.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"method\",\n        \"type\": \"AppApiMethod\",\n        \"required\": true,\n        \"enumValues\": [\n          \"get\",\n          \"post\",\n          \"put\",\n          \"patch\",\n          \"delete\",\n          \"head\",\n          \"options\"\n        ]\n      },\n      {\n        \"name\": \"size\",\n        \"type\": \"AppBadgeSize\",\n        \"required\": false,\n        \"default\": \"AppBadgeSize.s\",\n        \"enumValues\": [\n          \"s\",\n          \"m\",\n          \"l\",\n          \"xl\"\n        ]\n      },\n      {\n        \"name\": \"width\",\n        \"type\": \"double?\",\n        \"required\": false,\n        \"default\": \"kAppApiMethodBadgeWidth\",\n        \"description\": {\n          \"en\": \"null = the pill's natural width.\",\n          \"pt\": \"null = largura natural da pílula.\"\n        }\n      }\n    ],\n    \"variants\": [\n      \"get\",\n      \"post\",\n      \"put\",\n      \"patch\",\n      \"delete\",\n      \"head\",\n      \"options\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Verb\",\n          \"pt\": \"Verbo\"\n        },\n        \"code\": \"AppApiMethodBadge(AppApiMethod.post)\"\n      },\n      {\n        \"title\": {\n          \"en\": \"Natural width\",\n          \"pt\": \"Largura natural\"\n        },\n        \"code\": \"AppApiMethodBadge(AppApiMethod.get, width: null)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Keep the default width in lists — it is what aligns the paths.\"\n      ],\n      \"pt\": [\n        \"Mantenha a largura padrão em listas — é o que alinha os paths.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not recolor it from outside: the color IS the verb's information.\"\n      ],\n      \"pt\": [\n        \"Não recolora por fora: a cor É a informação do verbo.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Inherits AppBadge's single labelled node; the verb is read in uppercase.\",\n      \"pt\": \"Herda o nó rotulado único do AppBadge; o verbo é lido em caixa alta.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_badge\",\n      \"app_api_endpoint_tile\"\n    ]\n  },\n  {\n    \"id\": \"app_api_path\",\n    \"name\": \"AppApiPath\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Endpoint path in mono, with the placeholders highlighted.\",\n      \"pt\": \"Path de endpoint em mono, com os placeholders destacados.\"\n    },\n    \"description\": {\n      \"en\": \"The segments in braces take the primary accent and a heavier weight — they are what the reader has to substitute, and highlighting them keeps {id} from being read as a literal part of the path. It uses AppContentStyle's mono family, so the path looks identical to the same path inside an AppCodeBlock.\",\n      \"pt\": \"Os segmentos entre chaves recebem o acento primário e peso maior — é o que o leitor precisa substituir, e destacá-los evita ler {id} como parte literal do path. Usa a família mono da AppContentStyle, então o path fica idêntico ao mesmo path dentro de um AppCodeBlock.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"The header of an endpoint; the line of a flow step.\"\n      ],\n      \"pt\": [\n        \"Cabeçalho de um endpoint; linha de um passo de fluxo.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A clickable navigation URL → AppRichText with a link.\"\n      ],\n      \"pt\": [\n        \"URL clicável de navegação → AppRichText com link.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"path\",\n        \"type\": \"String\",\n        \"required\": true\n      },\n      {\n        \"name\": \"prefix\",\n        \"type\": \"String?\",\n        \"required\": false,\n        \"description\": {\n          \"en\": \"Base shown before the path, dimmed.\",\n          \"pt\": \"Base mostrada antes do path, esmaecida.\"\n        }\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"TextStyle?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"maxLines\",\n        \"type\": \"int?\",\n        \"required\": false,\n        \"default\": \"1\"\n      },\n      {\n        \"name\": \"overflow\",\n        \"type\": \"TextOverflow\",\n        \"required\": false,\n        \"default\": \"TextOverflow.ellipsis\"\n      }\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Path\",\n          \"pt\": \"Path\"\n        },\n        \"code\": \"AppApiPath('/devices/{id}')\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Pass the prefix when the base URL matters for copy-and-paste.\"\n      ],\n      \"pt\": [\n        \"Passe o prefix quando a base URL importar para copiar/colar.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not escape the braces: they are the highlight.\"\n      ],\n      \"pt\": [\n        \"Não escape as chaves: elas são o destaque.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Exposes the full path (prefix included) as the semantic label.\",\n      \"pt\": \"Expõe o path completo (prefixo incluído) como rótulo semântico.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_code_block\",\n      \"app_api_method_badge\"\n    ]\n  },\n  {\n    \"id\": \"app_api_param_table\",\n    \"name\": \"AppApiParamTable\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Request parameter table built on AppSimpleDataTable.\",\n      \"pt\": \"Tabela de parâmetros de requisição sobre o AppSimpleDataTable.\"\n    },\n    \"description\": {\n      \"en\": \"Columns Parameter / In / Type / Description. Name and type in mono; \\\"In\\\" and \\\"required\\\" as badges. No sorting and no pagination: the list is short and the order comes from the specification. It renders empty when there are no parameters, so the call site can include it without a conditional.\",\n      \"pt\": \"Colunas Parâmetro / Em / Tipo / Descrição. Nome e tipo em mono; \\\"Em\\\" e \\\"obrigatório\\\" como badges. Sem ordenação nem paginação: a lista é curta e a ordem vem da especificação. Renderiza vazio quando não há parâmetros, para o call site incluir sem condicional.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"The body of an endpoint card.\"\n      ],\n      \"pt\": [\n        \"Corpo de um cartão de endpoint.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A nested body schema → AppApiSchemaTree.\"\n      ],\n      \"pt\": [\n        \"Schema de corpo com aninhamento → AppApiSchemaTree.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"params\",\n        \"type\": \"List<AppApiParam>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"showLocation\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      }\n    ],\n    \"states\": [\n      \"default\",\n      \"empty\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Query\",\n          \"pt\": \"Query\"\n        },\n        \"code\": \"AppApiParamTable(endpoint.params)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Pass the parameters in the specification's order.\"\n      ],\n      \"pt\": [\n        \"Passe os parâmetros na ordem da especificação.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not use it for the body: a nested body does not fit in a table.\"\n      ],\n      \"pt\": [\n        \"Não use para o corpo: um body aninhado não cabe em tabela.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Inherits AppSimpleDataTable's table semantics and selection.\",\n      \"pt\": \"Herda a semântica de tabela e a seleção do AppSimpleDataTable.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_simple_data_table\",\n      \"app_api_schema_tree\"\n    ]\n  },\n  {\n    \"id\": \"app_api_schema_tree\",\n    \"name\": \"AppApiSchemaTree\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Field tree for a schema, with nodes that open level by level.\",\n      \"pt\": \"Árvore de campos de um schema, com nós abríveis por nível.\"\n    },\n    \"description\": {\n      \"en\": \"Each row is name · type · required · description; fields with subfields become openable nodes (AppExpand). It starts open only down to initiallyExpandedDepth — keeping the deep levels closed is what stops a real schema (pagination + entity + relationships) from becoming a wall of text. The chevron occupies the same box on leaves, so the names do not dance horizontally.\",\n      \"pt\": \"Cada linha é nome · tipo · obrigatório · descrição; campos com subcampos viram nós abríveis (AppExpand). Nasce aberta só até initiallyExpandedDepth — manter os níveis fundos fechados é o que impede um schema real (paginação + entidade + relacionamentos) de virar parede de texto. O chevron ocupa a mesma caixa em folhas, para os nomes não dançarem na horizontal.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"An endpoint's request body and response body.\"\n      ],\n      \"pt\": [\n        \"Corpo de requisição e corpo de resposta de um endpoint.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A flat list of parameters → AppApiParamTable.\"\n      ],\n      \"pt\": [\n        \"Lista plana de parâmetros → AppApiParamTable.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"fields\",\n        \"type\": \"List<AppApiField>\",\n        \"required\": true\n      },\n      {\n        \"name\": \"initiallyExpandedDepth\",\n        \"type\": \"int\",\n        \"required\": false,\n        \"default\": \"1\",\n        \"description\": {\n          \"en\": \"Depth (0-based) down to which nodes start open.\",\n          \"pt\": \"Profundidade (0-based) até a qual os nós nascem abertos.\"\n        }\n      }\n    ],\n    \"states\": [\n      \"collapsed\",\n      \"expanded\",\n      \"empty\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Request body\",\n          \"pt\": \"Corpo da requisição\"\n        },\n        \"code\": \"AppApiSchemaTree(endpoint.requestFields)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Cut cycles and impose a depth ceiling BEFORE building the tree.\"\n      ],\n      \"pt\": [\n        \"Corte ciclos e imponha teto de profundidade ANTES de montar a árvore.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not open everything by default: a real schema has dozens of fields.\"\n      ],\n      \"pt\": [\n        \"Não abra tudo por padrão: o schema real tem dezenas de campos.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Nodes with children become buttons (AppSemantics.button) activatable by keyboard; leaves stay as selectable text.\",\n      \"pt\": \"Nós com filhos viram botões (AppSemantics.button) ativáveis por teclado; folhas ficam como texto selecionável.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_api_param_table\",\n      \"app_expansion_tile\"\n    ]\n  },\n  {\n    \"id\": \"app_api_endpoint_tile\",\n    \"name\": \"AppApiEndpointTile\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Collapsible endpoint card: verb, path, params, responses.\",\n      \"pt\": \"Cartão colapsável de um endpoint: verbo, path, params, respostas.\"\n    },\n    \"description\": {\n      \"en\": \"A header with the verb pill, the path in mono, a summary and copy-path; a body with authentication, tags, parameters, the request schema, the responses and a sample curl. Built on FlocksInteraction + AppExpand + AppAnimatedRotation (the same primitives as AppExpansionTile) because that one only accepts a String title and here the header is composed. Read-only: the curl carries a credential placeholder, never the session token.\",\n      \"pt\": \"Cabeçalho com pílula do verbo, path em mono, resumo e copiar-path; corpo com autenticação, tags, parâmetros, schema de requisição, respostas e um curl de exemplo. Construído sobre FlocksInteraction + AppExpand + AppAnimatedRotation (as mesmas primitivas do AppExpansionTile) porque aquele só aceita título String e aqui o cabeçalho é composto. Somente leitura: o curl traz placeholder de credencial, nunca o token da sessão.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"Listing the endpoints of a screen's context.\"\n      ],\n      \"pt\": [\n        \"Listar os endpoints de um contexto de tela.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Executing the call — this component fires no request at all.\"\n      ],\n      \"pt\": [\n        \"Executar a chamada — este componente não dispara request nenhum.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"endpoint\",\n        \"type\": \"AppApiEndpoint\",\n        \"required\": true\n      },\n      {\n        \"name\": \"baseUrl\",\n        \"type\": \"String?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"initiallyExpanded\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"false\"\n      },\n      {\n        \"name\": \"onExpansionChanged\",\n        \"type\": \"ValueChanged<bool>?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"showCopyPath\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppStyle?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"radiusMode\",\n        \"type\": \"AppRadiusMode?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"collapsed\",\n      \"expanded\",\n      \"hovered\",\n      \"focused\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Card\",\n          \"pt\": \"Cartão\"\n        },\n        \"code\": \"AppApiEndpointTile(endpoint: e, baseUrl: doc.baseUrl)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Use the GlobalKey<AppApiEndpointTileState> to open a card from outside.\"\n      ],\n      \"pt\": [\n        \"Use a GlobalKey<AppApiEndpointTileState> para abrir um cartão de fora.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Never put a real credential in the curl.\"\n      ],\n      \"pt\": [\n        \"Nunca coloque credencial real no curl.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"The header is a button (AppSemantics.button) labelled with the verb, the path and the summary, activatable by keyboard and with a focus ring.\",\n      \"pt\": \"O cabeçalho é um botão (AppSemantics.button) rotulado com verbo, path e resumo, ativável por teclado e com anel de foco.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_api_method_badge\",\n      \"app_api_schema_tree\",\n      \"app_code_block\"\n    ]\n  },\n  {\n    \"id\": \"app_api_flow\",\n    \"name\": \"AppApiFlow\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"A business flow as a numbered vertical timeline of calls.\",\n      \"pt\": \"Fluxo de negócio como timeline vertical numerada de chamadas.\"\n    },\n    \"description\": {\n      \"en\": \"It answers what the endpoint list does not: in what ORDER. Each step has a number, what the step does and — when it is a call — the verb + path line, clickable to reach the endpoint's card. The connector grows with the step's real height (IntrinsicHeight), otherwise steps of differing heights would leave gaps in the line.\",\n      \"pt\": \"Responde ao que a lista de endpoints não responde: em que ORDEM. Cada passo tem número, o que a etapa faz e — quando é uma chamada — a linha verbo + path, clicável para levar ao cartão do endpoint. O conector cresce com a altura real do passo (IntrinsicHeight), senão passos de alturas diferentes deixariam buracos na linha.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"A required sequence of calls (register → associate → activate).\"\n      ],\n      \"pt\": [\n        \"Sequência obrigatória de chamadas (cadastrar → associar → ativar).\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"A form wizard in the application → AppStepper.\",\n        \"A list of endpoints with no order between them → just the panel's groups.\"\n      ],\n      \"pt\": [\n        \"Wizard de formulário na aplicação → AppStepper.\",\n        \"Lista de endpoints sem ordem entre si → apenas os grupos do painel.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"flow\",\n        \"type\": \"AppApiFlowData\",\n        \"required\": true\n      },\n      {\n        \"name\": \"onStepTap\",\n        \"type\": \"ValueChanged<AppApiFlowStep>?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"style\",\n        \"type\": \"AppStyle?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"radiusMode\",\n        \"type\": \"AppRadiusMode?\",\n        \"required\": false\n      }\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Navigable timeline\",\n          \"pt\": \"Timeline navegável\"\n        },\n        \"code\": \"AppApiFlow(flow: doc.flows.first, onStepTap: panel.reveal)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Write the step by its business effect, not by the HTTP verb.\"\n      ],\n      \"pt\": [\n        \"Escreva o passo pelo efeito de negócio, não pelo verbo HTTP.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not repeat the endpoint's full documentation here.\"\n      ],\n      \"pt\": [\n        \"Não repita aqui a documentação inteira do endpoint.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"The verb + path line becomes a labelled AppInteraction (\\\"See the … endpoint\\\"), keyboard-focusable. The numbers are text, not color alone.\",\n      \"pt\": \"A linha verbo + path vira um AppInteraction rotulado (\\\"Ver o endpoint …\\\"), focável por teclado. Os números são texto, não só cor.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_api_docs_panel\",\n      \"app_stepper\"\n    ]\n  },\n  {\n    \"id\": \"app_api_docs_panel\",\n    \"name\": \"AppApiDocsPanel\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"API documentation in the context of one screen, in a single flow.\",\n      \"pt\": \"Documentação da API no contexto de uma tela, num só fluxo.\"\n    },\n    \"description\": {\n      \"en\": \"A header (title, context, copyable base URL, a link to the full reference), search, business flows and endpoint groups. Tapping a flow step OPENS and SCROLLS to the endpoint's card — that is what stitches the narrative (\\\"in what order\\\") to the reference (\\\"what each one does\\\"). It does not scroll on its own: the sheet's contract is that the surface owns the scrolling. Purely presentational — it takes an already-resolved AppApiDoc and makes no network calls.\",\n      \"pt\": \"Cabeçalho (título, contexto, base URL copiável, link para a referência completa), busca, fluxos de negócio e grupos de endpoints. Tocar um passo de fluxo ABRE e ROLA até o cartão do endpoint — é o que costura a narrativa (\\\"em que ordem\\\") à referência (\\\"o que cada um faz\\\"). Não rola sozinho: o contrato do sheet é que a superfície cuida da rolagem. Puro de apresentação — recebe um AppApiDoc já resolvido e não faz rede.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"The content of a screen's \\\"API documentation\\\" bottom/side sheet.\"\n      ],\n      \"pt\": [\n        \"Conteúdo do bottom/side sheet de \\\"documentação da API\\\" de uma tela.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"The complete reference for the whole API → Swagger UI.\",\n        \"Loading and error states: they belong to the host, not to the panel.\"\n      ],\n      \"pt\": [\n        \"Referência completa da API inteira → Swagger UI.\",\n        \"Estados de carregamento/erro: são do host, não do painel.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"doc\",\n        \"type\": \"AppApiDoc\",\n        \"required\": true\n      },\n      {\n        \"name\": \"onOpenExternal\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"showSearch\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"searchHint\",\n        \"type\": \"String\",\n        \"required\": false\n      },\n      {\n        \"name\": \"emptyText\",\n        \"type\": \"String\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"default\",\n      \"filtered\",\n      \"empty\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"In the bottom sheet\",\n          \"pt\": \"No bottom sheet\"\n        },\n        \"code\": \"showAppBottomSheet(context: context, draggable: true, child: AppApiDocsPanel(doc: doc))\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Wrap it in a scroll when using it outside a sheet.\",\n        \"Pass the base URL: it is what makes copy-path pasteable.\"\n      ],\n      \"pt\": [\n        \"Embrulhe num scroll quando usar fora de um sheet.\",\n        \"Passe a base URL: é o que torna o copiar-path colável.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not put the panel inside another scroll within the sheet.\"\n      ],\n      \"pt\": [\n        \"Não coloque o painel dentro de outro scroll dentro do sheet.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Search is a labelled AppInput; each card is a focusable button; the copy chips expose their own semantic label.\",\n      \"pt\": \"Busca é um AppInput rotulado; cada cartão é um botão focável; os chips de copiar expõem rótulo semântico próprio.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_api_endpoint_tile\",\n      \"app_api_flow\",\n      \"app_bottom_sheet\"\n    ]\n  },\n  {\n    \"id\": \"app_entity_doc_panel\",\n    \"name\": \"AppEntityDocPanel\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Conceptual documentation for an entity: what it is, what it relates to and who exchanges data with it.\",\n      \"pt\": \"Documentação conceitual de uma entidade: o que é, com quem se relaciona e quem troca dados com ela.\"\n    },\n    \"description\": {\n      \"en\": \"The half the API reference does not cover. Free prose (the overview and the sections) comes in as Markdown, because lifecycle and business rules do not fit a fixed structure; relationships and integrations are structured as cards, because they are what the reader scans. Cardinality (1 → N) and the direction of an integration (receives/sends) come out as a label, not as color alone. It does not scroll on its own — the host provides the scroll.\",\n      \"pt\": \"A metade que a referência de API não cobre. Prosa livre (overview e seções) entra como Markdown, porque ciclo de vida e regra de negócio não cabem numa estrutura fixa; relações e integrações são estruturadas em cartões, porque são o que o leitor varre com o olho. Cardinalidade (1 → N) e sentido da integração (recebe/envia) saem como rótulo, não só como cor. Não rola sozinho — quem hospeda dá o scroll.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"The left column of AppDocsWorkspace.\",\n        \"Explaining a domain entity to whoever is going to integrate with it.\"\n      ],\n      \"pt\": [\n        \"Coluna esquerda do AppDocsWorkspace.\",\n        \"Explicar uma entidade do domínio para quem vai integrar com ela.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"An endpoint signature → AppApiDocsPanel.\",\n        \"A free document with no entity structure → AppMarkdown directly.\"\n      ],\n      \"pt\": [\n        \"Assinatura de endpoint → AppApiDocsPanel.\",\n        \"Documento livre sem estrutura de entidade → AppMarkdown direto.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"doc\",\n        \"type\": \"AppEntityDoc\",\n        \"required\": true\n      },\n      {\n        \"name\": \"showHeader\",\n        \"type\": \"bool\",\n        \"required\": false,\n        \"default\": \"true\"\n      },\n      {\n        \"name\": \"relationsTitle\",\n        \"type\": \"String\",\n        \"required\": false,\n        \"default\": \"'Relações'\"\n      },\n      {\n        \"name\": \"integrationsTitle\",\n        \"type\": \"String\",\n        \"required\": false,\n        \"default\": \"'Integrações'\"\n      },\n      {\n        \"name\": \"onTapLink\",\n        \"type\": \"void Function(String)?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"default\",\n      \"empty\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"Concept column\",\n          \"pt\": \"Coluna de conceito\"\n        },\n        \"code\": \"AppEntityDocPanel(doc: entity, showHeader: false)\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Write the relationship by its business effect, not by the foreign key.\"\n      ],\n      \"pt\": [\n        \"Escreva a relação pelo efeito de negócio, não pela chave estrangeira.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not repeat the endpoint's signature here: the column beside it already has it.\"\n      ],\n      \"pt\": [\n        \"Não repita aqui a assinatura do endpoint: a coluna ao lado já a tem.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Cardinality and direction are text inside the AppBadge, so a screen reader and a colorblind reader get the same information the color carries.\",\n      \"pt\": \"Cardinalidade e sentido são texto dentro do AppBadge, então leitor de tela e daltônico recebem a mesma informação que a cor carrega.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_docs_workspace\",\n      \"app_markdown\",\n      \"app_api_docs_panel\"\n    ]\n  },\n  {\n    \"id\": \"app_docs_workspace\",\n    \"name\": \"AppDocsWorkspace\",\n    \"category\": \"organism\",\n    \"status\": \"migrated\",\n    \"summary\": {\n      \"en\": \"Documentation for one context in two columns: concept and API.\",\n      \"pt\": \"Documentação de um contexto em duas colunas: conceito e API.\"\n    },\n    \"description\": {\n      \"en\": \"The two halves answer different questions and the reader switches between them constantly (\\\"what is a device?\\\" and \\\"how do I create one?\\\"). Side by side, switching is eye movement; stacked, it would be scrolling. The divider is draggable (AppResizableSplit) and each column scrolls on its own, so reading a schema does not make the explanation disappear. Below kAppDocsWorkspaceStackBelow the columns stack into a single scroll. It requires a bounded height — which is what an AppSideSheet body provides.\",\n      \"pt\": \"As duas metades respondem perguntas diferentes e o leitor alterna entre elas o tempo todo (\\\"o que é um dispositivo?\\\" e \\\"como eu crio um?\\\"). Lado a lado, a alternância é o movimento dos olhos; empilhadas, seria scroll. A divisória é arrastável (AppResizableSplit) e cada coluna rola sozinha, para que ler um schema não faça a explicação sumir. Abaixo de kAppDocsWorkspaceStackBelow as colunas empilham num scroll único. Exige altura limitada — é o que o corpo de um AppSideSheet dá.\"\n    },\n    \"whenToUse\": {\n      \"en\": [\n        \"The body of a screen's documentation side sheet, at the full snap.\"\n      ],\n      \"pt\": [\n        \"Corpo do side sheet de documentação de uma tela, no snap full.\"\n      ]\n    },\n    \"whenNotToUse\": {\n      \"en\": [\n        \"Inside a vertical scroll: the component needs a bounded height.\",\n        \"Endpoints only, with no concept → AppApiDocsPanel directly.\"\n      ],\n      \"pt\": [\n        \"Dentro de um scroll vertical: o componente precisa de altura limitada.\",\n        \"Só endpoints, sem conceito → AppApiDocsPanel direto.\"\n      ]\n    },\n    \"props\": [\n      {\n        \"name\": \"entity\",\n        \"type\": \"AppEntityDoc?\",\n        \"required\": true,\n        \"description\": {\n          \"en\": \"null hides the left column; the API takes everything.\",\n          \"pt\": \"null esconde a coluna esquerda; a API ocupa tudo.\"\n        }\n      },\n      {\n        \"name\": \"api\",\n        \"type\": \"AppApiDoc\",\n        \"required\": true\n      },\n      {\n        \"name\": \"entityTitle\",\n        \"type\": \"String\",\n        \"required\": false,\n        \"default\": \"'Documentação'\"\n      },\n      {\n        \"name\": \"apiTitle\",\n        \"type\": \"String\",\n        \"required\": false,\n        \"default\": \"'API'\"\n      },\n      {\n        \"name\": \"onOpenEntityDocs\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"onOpenApiDocs\",\n        \"type\": \"VoidCallback?\",\n        \"required\": false\n      },\n      {\n        \"name\": \"initialFirstFraction\",\n        \"type\": \"double\",\n        \"required\": false,\n        \"default\": \"0.45\",\n        \"description\": {\n          \"en\": \"Smaller than half: the API column carries tables and code.\",\n          \"pt\": \"Menor que a metade: a coluna de API carrega tabelas e código.\"\n        }\n      },\n      {\n        \"name\": \"onTapLink\",\n        \"type\": \"void Function(String)?\",\n        \"required\": false\n      }\n    ],\n    \"states\": [\n      \"split\",\n      \"stacked\",\n      \"api-only\"\n    ],\n    \"examples\": [\n      {\n        \"title\": {\n          \"en\": \"In the wide side sheet\",\n          \"pt\": \"No side sheet largo\"\n        },\n        \"code\": \"showAppSideSheet(context: context, draggable: true, initialSnap: AppSideSheetSnap.full, child: AppDocsWorkspace(entity: e, api: a))\"\n      }\n    ],\n    \"do\": {\n      \"en\": [\n        \"Open it at the full snap: two columns do not fit in the resting snap.\",\n        \"Give it both external links — the panel is an excerpt, not the source.\"\n      ],\n      \"pt\": [\n        \"Abra no snap full: duas colunas não cabem no snap de repouso.\",\n        \"Dê os dois links externos — o painel é um recorte, não a fonte.\"\n      ]\n    },\n    \"dont\": {\n      \"en\": [\n        \"Do not nest it in a vertical scroll; the height has to come from outside.\"\n      ],\n      \"pt\": [\n        \"Não aninhe num scroll vertical; a altura tem que vir de fora.\"\n      ]\n    },\n    \"a11y\": {\n      \"en\": \"Each column has its own header outside the scroll, so the position in the document is never lost. External links expose a semantic label.\",\n      \"pt\": \"Cada coluna tem cabeçalho próprio fora do scroll, então a posição no documento nunca se perde. Os links externos expõem rótulo semântico.\"\n    },\n    \"crossPlatform\": true,\n    \"themeAware\": true,\n    \"reducesMotion\": true,\n    \"related\": [\n      \"app_entity_doc_panel\",\n      \"app_api_docs_panel\",\n      \"app_resizable_split\",\n      \"app_side_sheet\"\n    ]\n  }\n]\n";
